INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C1','kor',6,2,'u3',1,'주장 · 이유 · 근거 — 주장은 어떤 주제에 대한 자신의 의견을 드러내는 말, 이유는 왜 그렇게 주장하는지를 설명하는 말, 근거는 이유를 뒷받침하는 자료나 사실이며, 셋의 자리를 갈라야 평가할 수 있다',ARRAY['6국01 듣기·말하기(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C2','kor',6,2,'u3',1,'비판적으로 보고 듣기 — 무조건 믿거나 무조건 의심하는 것이 아니라 옳고 그른지를 제대로 따져 보는 것(맞는 것은 맞다고, 부족한 것은 부족하다고 까닭을 들어 말하기), 따져 보지 않으면 사실이 아닌 것을 믿고 옮기게 되고, 따져 보면 믿을 만한 정보를 골라 쓰고 내 생각과 견주어 볼 수 있다',ARRAY['6국01 듣기·말하기(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C3','kor',6,2,'u3',2,'주장하는 말을 듣는 방법 — 말은 되감을 수 없으므로 메모하며 듣기(이유·근거 적기)·요약하며 듣기(주장·이유·근거로 간추리기)·견주며 듣기(내 생각과 견주기)를 하고, 지나치게 감정에 호소하지는 않는지 태도까지 살핀다',ARRAY['6국01 듣기·말하기(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C4','kor',6,2,'u3',2,'주장의 타당성 판단 기준 — 주장이 가치 있고 중요한지는 문제를 해결하거나 생활하는 데 도움이 되는가, 실천 가능한가(언제 무엇을 할지 정해져 있는가)로 판단한다',ARRAY['6국01 듣기·말하기(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C5','kor',6,2,'u3',2,'이유의 타당성 판단 기준 — 이유가 주장과 관련 있는가, 많은 사람이 받아들일 만한가(혼자만의 느낌·사정이 아닌가) 두 물음을 함께 통과해야 한다',ARRAY['6국01 듣기·말하기(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C6','kor',6,2,'u3',2,'근거의 타당성 판단 기준과 근거 자료 — 근거가 이유와 관련 있는가, 객관적인 사실이나 정보인가로 판단하고, 근거 자료의 유형(표·그래프·면담 자료·사례)을 알며, 근거가 사실인지 책·기사·기관 누리집·어른께 여쭈어 확인하고 출처가 믿을 만한지 다시 살핀다',ARRAY['6국01 듣기·말하기(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C7','kor',6,2,'u3',4,'주장하는 말의 내용을 평가하며 듣기 — 타당한 점을 먼저 찾고 보완할 점을 찾으며(평가는 이긴 쪽을 고르는 일이 아니라 더 나아지게 하는 일), 평가 기준표에 ◎·○·△로 판단하고 그렇게 판단한 까닭(어떤 기준을 더 무겁게 보았는지)을 말한다',ARRAY['6국01 듣기·말하기(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C8','kor',6,2,'u3',4,'객관적인 근거와 출처 밝히기 — 누가 보아도 그러한 객관적인 근거와 혼자만의 느낌·짐작인 주관적인 말을 가르고, 주관적인 근거는 더 힘주어 말하거나 감정에 호소하지 않고 확인할 수 있는 자료로 고치며, 가져다 쓴 자료는 어디에서 나왔는지 밝힌다',ARRAY['6국01 듣기·말하기(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C9','kor',6,2,'u3',7,'영상의 주장 파악하기 — 알려 주는 영상·보여 주는 영상·주장하는 영상을 가르고, 영상은 주장을 직접 말하지 않는 경우가 많으므로 제목(그렇게 정한 까닭)·제시한 자료(무엇을 보여 주려고 넣었는지)·강조하는 장면이나 표현(되풀이·음악이 멈추는 자리·글자만 남는 화면)을 합쳐 주장을 한 문장으로 세운다',ARRAY['6국06 매체(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C10','kor',6,2,'u3',7,'강조와 타당성 가르기 — 음악·되풀이 자막 같은 강조는 만든 사람이 무엇을 가장 하고 싶은 말로 여기는지 알려 주는 실마리일 뿐 그 말이 타당한지·사실인지는 알려 주지 못하며, 주장을 찾는 일과 타당한지 따지는 일은 다르다(끝까지 한 번 보고 두 번째에 적으며 보기)',ARRAY['6국06 매체(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C11','kor',6,2,'u3',9,'카드 뉴스 내용을 평가하며 보기 — 카드 뉴스는 첫 장의 제목과 굵은 글씨에 주장이, 가운데 장에 이유와 근거가 한 쌍씩 놓이며, 짧을수록 빠진 것이 잘 보이지 않으므로 이유마다 「그래서 왜?」, 근거마다 「이게 그 이유를 보여 주나?」를 물으며 같은 세 기준으로 평가한다',ARRAY['6국06 매체(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C12','kor',6,2,'u3',9,'약한 자리 짚기와 부분 평가 — 잘 세워진 자리를 먼저 세고, 문제의 규모(많다·늘고 있다)만 말하는 이유나 이유를 보여 주지 않고 해결 방안(제도)을 말하는 근거를 약한 자리로 짚되, 하나가 약하다고 주장 전체가 틀린 것은 아니며 고칠 자리를 짚어 준다',ARRAY['6국06 매체(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C13','kor',6,2,'u3',12,'영상을 골라 타당성을 평가하고 설명하기 — 여러 사람이 함께 생각해 볼 만한 주제를 정해 구체적인 말로 찾고, 자세히 보기·알아낸 것 말하기·생각하기·궁금해하기 차례로 보며, 주장이 없는 영상은 평가표에서 가려내고, 내용의 타당성을 먼저·표현은 그다음에 보고, 제목·주장·이유·근거·판단·까닭을 넣어 설명한다',ARRAY['6국06 매체(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u3-C14','kor',6,2,'u3',12,'받침 ㅎ의 발음 — 받침 ㅎ 뒤에 ㄱ·ㄷ·ㅈ이 오면 합쳐서 ㅋ·ㅌ·ㅊ으로(넣고[너코]·빨갛다[빨가타]·그렇지[그러치]), ㄴ이 오면 ㄴ으로(넣는[넌는]), 모음이 오면 ㅎ 소리를 내지 않는다(좋아[조아])(기초 다지기)',ARRAY['6국04 문법(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X01','kor',6,'u3',ARRAY['K6-2-u3-C1','K6-2-u3-C9','K6-2-u3-C11']::text[],'주장 · 이유 · 근거의 자리를 섞는다(이유를 주장으로, 주장을 근거로 여기는 등)','하자는 말? 왜 그런지? 받쳐 주는 자료?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X02','kor',6,'u3',ARRAY['K6-2-u3-C2','K6-2-u3-C7','K6-2-u3-C12']::text[],'비판적으로 보기를 무조건 의심하기·말한 사람 깎아내리기·어딘가 잘못이 있다고 미리 정하기로 여긴다','따져 보기 = 맞는 것은 맞다고, 부족한 것은 부족하다고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X03','kor',6,'u3',ARRAY['K6-2-u3-C2','K6-2-u3-C11']::text[],'말을 잘하거나 짧고 보기 좋거나 많이 퍼진 주장을 따져 보지 않고 그대로 믿는다','「이 말, 무엇이 받쳐 주지?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X04','kor',6,'u3',ARRAY['K6-2-u3-C3']::text[],'메모하거나 간추리지 않고 들어 평가할 거리를 남기지 못하거나, 결론을 미리 정하고 목소리·말솜씨로 판단한다','말은 되감을 수 없어요 — 적고 간추리며 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X05','kor',6,'u3',ARRAY['K6-2-u3-C4']::text[],'말만 크고 무엇부터 할지 알 수 없는 주장도 가치 있다고 여긴다(실천 가능성을 보지 않음)','언제 · 무엇을 할지 정해져 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X06','kor',6,'u3',ARRAY['K6-2-u3-C5']::text[],'주장과 관련 없는 이유를 받아들이거나, 관련 있는 이유를 관련 없다고 여긴다','이 이유가 주장이 말하는 일과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X07','kor',6,'u3',ARRAY['K6-2-u3-C5']::text[],'혼자만의 느낌이나 사정인 이유도 많은 사람이 받아들일 만한 이유로 여긴다','나만 그런가, 많은 사람이 고개를 끄덕일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X08','kor',6,'u3',ARRAY['K6-2-u3-C6','K6-2-u3-C8']::text[],'말한 사람의 느낌이나 짐작을 근거로 여기거나, 근거는 길고 많을수록 좋다고 여긴다','누가 보아도 그러한가, 확인할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X09','kor',6,'u3',ARRAY['K6-2-u3-C6']::text[],'근거가 사실인지 확인하지 않거나, 검색해 나온 것·많이 퍼진 글을 출처 확인 없이 믿는다','책 · 기사 · 기관 누리집 · 어른께 — 그리고 출처 한 번 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X10','kor',6,'u3',ARRAY['K6-2-u3-C6']::text[],'근거 자료의 유형(표·그래프·면담 자료·사례)과 그 쓰임을 헷갈린다','나란히 견주기? 흐름? 사람의 말? 있었던 일?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X11','kor',6,'u3',ARRAY['K6-2-u3-C7','K6-2-u3-C12']::text[],'평가를 흠부터 찾는 일이나 이긴 쪽을 고르는 일로 여겨 타당한 점을 먼저 찾지 않는다','살릴 것 먼저, 고칠 것은 그다음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X12','kor',6,'u3',ARRAY['K6-2-u3-C7','K6-2-u3-C13']::text[],'까닭 없이 표시만 하거나 「그냥 그렇게 느꼈다」로 판단하고, 판단이 갈릴 때 어떤 기준을 무겁게 보았는지 말하지 않는다','「나는 ○○을 가장 무겁게 보았어. 그래서 …」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X13','kor',6,'u3',ARRAY['K6-2-u3-C8']::text[],'가져다 쓴 자료의 출처를 밝히지 않아 확인할 길을 막거나 남의 자료를 내 것처럼 쓴다','어디에서 · 언제 나온 자료인지 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X14','kor',6,'u3',ARRAY['K6-2-u3-C8']::text[],'약한 근거를 고칠 때 더 힘주어 되풀이하거나 듣는 사람의 감정에 호소한다','느낌을 키우지 말고 확인할 수 있는 자료로 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X15','kor',6,'u3',ARRAY['K6-2-u3-C9','K6-2-u3-C13']::text[],'영상의 주장을 한 요소(제목만·분위기만)로 정하거나, 주장과 관계없는 것(길이·벽 색)을 실마리로 삼거나, 알려 주는 영상과 주장하는 영상을 헷갈린다','제목 + 자료 + 강조 → 한 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X16','kor',6,'u3',ARRAY['K6-2-u3-C9']::text[],'영상도 주장을 문장으로 직접 말할 것이라 여겨, 직접 말하지 않으면 주장이 없다고 본다','「그래서 나더러 무엇을 하라는 걸까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X17','kor',6,'u3',ARRAY['K6-2-u3-C10']::text[],'음악이 커지고 자막이 되풀이될수록, 곧 강조가 셀수록 주장이 옳거나 사실이라고 여긴다','강조는 「무엇을」 말하고 싶은지만 알려 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X18','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'문제의 규모(많다·늘고 있다)만으로 문제가 되는 까닭을 말했다고 여긴다','많아서 → 무엇이 어떻게 나빠지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X19','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'문제에 대한 해결 방안(제도·규칙·대책)을 그 문제가 있다는 이유를 보여 주는 근거로 여긴다','이 근거는 문제를 보여 주나, 그 뒤의 일을 말하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X20','kor',6,'u3',ARRAY['K6-2-u3-C12']::text[],'이유나 근거 하나가 약하면 주장 전체가 틀렸다거나 믿을 수 없다고 여긴다','약한 자리는 고칠 자리 — 주장 전체와 가르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X21','kor',6,'u3',ARRAY['K6-2-u3-C13']::text[],'주장이 없는 영상도 평가표로 재거나, 음악·편집·말투 같은 표현과 재미로 타당성을 판단한다','먼저 평가할 수 있는 영상인지 · 내용 먼저, 표현은 그다음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X22','kor',6,'u3',ARRAY['K6-2-u3-C13']::text[],'영상을 찾고 보는 차례를 지키지 않는다(두루뭉술하거나 자극적인 검색어, 본 것과 짐작한 것을 섞기)','구체적인 말로 찾기 · 본 것 → 생각 → 물음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u3-X23','kor',6,'u3',ARRAY['K6-2-u3-C14']::text[],'받침 ㅎ을 뒤 소리와 상관없이 그대로 소리 내거나, ㄱ·ㄷ·ㅈ과 합치지 않고 ㄷ으로 끊어 소리 낸다','ㄱ·ㄷ·ㅈ → ㅋ·ㅌ·ㅊ · ㄴ → ㄴ · 모음 → 소리 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#1','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',1,'mc','auto','「주장」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"mc","stem":"「주장」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 주제에 대한 자신의 의견을 드러내는 말","correct":true},{"t":"왜 그렇게 주장하는지를 설명하는 말","mis":"K6-2-u3-X01"},{"t":"이유를 뒷받침하는 자료나 사실","mis":"K6-2-u3-X01"},{"t":"다른 사람의 말을 그대로 옮긴 말","mis":"K6-2-u3-X01"}],"explanation":["주장은 「무엇을 하자」는 의견이에요.","왜 그런지 밝히는 말은 이유예요.","이유를 받쳐 주는 자료는 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#2','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',1,'sa','auto','이유를 뒷받침하는 자료나 사실을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C1","difficulty":1,"kind":"sa","stem":"이유를 뒷받침하는 자료나 사실을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["근거"],"explanation":["주장은 의견, 이유는 까닭이에요.","이유가 사실인지 보여 주는 자료가 있어야 해요.","그 자료나 사실을 근거라고 해요."],"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#3','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',1,'ox','auto','비판적으로 본다는 것은 무조건 믿지 않는 것이에요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":3,"concept":"K6-2-u3-C2","difficulty":1,"kind":"ox","stem":"비판적으로 본다는 것은 무조건 믿지 않는 것이에요.","answer":"X","reason_options":[{"t":"옳고 그른지를 제대로 따져 보는 것이기 때문에","correct":true},{"t":"어떤 말이든 먼저 의심해야 속지 않기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["무조건 믿지 않는 것은 따져 보기 전에 정해 버리는 것이에요.","비판적으로 보기는 까닭을 들어 따지는 것이에요.","맞는 것은 맞다고, 부족한 것은 부족하다고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#4','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',1,'mc','auto','주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일은 어느 것인가요?',ARRAY['K6-2-u3-X03','K6-2-u3-X02']::text[],false,'{"seq":4,"concept":"K6-2-u3-C2","difficulty":1,"kind":"mc","stem":"주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일은 어느 것인가요?","options":[{"t":"사실이 아닌 것을 사실로 알게 된다","correct":true},{"t":"아무 일도 생기지 않는다","mis":"K6-2-u3-X03"},{"t":"말한 사람을 깎아내리게 된다","mis":"K6-2-u3-X02"},{"t":"글을 더 빨리 읽게 된다","mis":"K6-2-u3-X03"}],"explanation":["따져 보지 않으면 사실이 아닌 것도 그대로 믿게 돼요.","그 말을 다른 사람에게 옮길 수도 있어요.","그래서 한 번 더 따져 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#5','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',2,'mc','auto','서담이가 본 영상이 하려던 주장은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":5,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"서담이가 본 영상이 하려던 주장은 무엇인가요?","options":[{"t":"아침에 물을 두 컵 마시자","correct":true},{"t":"자는 동안 몸에서 물이 빠져나간다","mis":"K6-2-u3-X01"},{"t":"짧은 영상을 자주 보자","mis":"K6-2-u3-X01"},{"t":"물에 대한 자료를 찾아보자","mis":"K6-2-u3-X01"}],"explanation":["영상이 보는 사람에게 하라고 한 일이 주장이에요.","「물이 빠져나가기 때문」은 왜 그런지 밝힌 이유예요.","주장과 이유의 자리가 달라요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#6','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',2,'mc','auto','서담이가 본 영상에 빠져 있던 것은 어느 것인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":6,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"서담이가 본 영상에 빠져 있던 것은 어느 것인가요?","options":[{"t":"근거 — 이유가 사실이라는 자료","correct":true},{"t":"주장 — 무엇을 하자는 말","mis":"K6-2-u3-X01"},{"t":"이유 — 그렇게 말한 까닭","mis":"K6-2-u3-X01"},{"t":"주장과 이유 모두","mis":"K6-2-u3-X01"}],"explanation":["영상에는 「물을 두 컵 마시자」는 주장이 있었어요.","「물이 빠져나가기 때문」이라는 이유도 있었어요.","그 말이 사실이라는 자료는 없었어요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#7','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C1',2,'match','auto','주장 · 이유 · 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C1","difficulty":2,"kind":"match","stem":"주장 · 이유 · 근거를 알맞게 이으세요.","pairs":[{"l":"주장","r":"복도에서는 걸어 다닙시다"},{"l":"이유","r":"뛰면 부딪칠 수 있기 때문입니다"},{"l":"근거","r":"복도에서 부딪친 일이 여러 번 있었다는 보건실 기록"}],"mis":"K6-2-u3-X01","explanation":["무엇을 하자는 말이 주장이에요.","「~ 때문입니다」로 까닭을 밝히면 이유예요.","이유를 받쳐 주는 기록이 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#8','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',2,'mc','auto','비판적으로 듣는 사람의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X03']::text[],false,'{"seq":8,"concept":"K6-2-u3-C2","difficulty":2,"kind":"mc","stem":"비판적으로 듣는 사람의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"이유와 근거가 주장과 잘 맞는지 따져 본다","correct":true},{"t":"일단 틀린 곳이 있다고 생각하고 듣는다","mis":"K6-2-u3-X02"},{"t":"말을 잘하는 사람의 말이면 그대로 받아들인다","mis":"K6-2-u3-X03"},{"t":"말한 사람이 마음에 들지 않으면 듣지 않는다","mis":"K6-2-u3-X02"}],"explanation":["믿거나 믿지 않거나 둘 중 하나로 정해 버리지 않아요.","이유와 근거가 주장과 맞는지 따져요.","말솜씨나 사람이 아니라 내용을 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#9','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',2,'ox','auto','주장을 따져 보면 믿을 만한 정보를 골라 쓸 수 있어요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":9,"concept":"K6-2-u3-C2","difficulty":2,"kind":"ox","stem":"주장을 따져 보면 믿을 만한 정보를 골라 쓸 수 있어요.","answer":"O","reason_options":[{"t":"내용을 제대로 이해하고 내 생각과 견주어 볼 수 있기 때문에","correct":true},{"t":"따져 보면 모든 주장이 틀렸다는 것을 알게 되기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["따져 보면 내용을 제대로 이해할 수 있어요.","내 생각과 견주어 볼 수 있어요.","따져 본다고 모든 주장이 틀린 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_basic#10','kor',6,2,'u3','L01','g6_2_kor_u3_L01_basic','lesson_basic','K6-2-u3-C2',3,'error','auto','비판적으로 보는 것에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X11']::text[],false,'{"seq":10,"concept":"K6-2-u3-C2","difficulty":3,"kind":"error","stem":"비판적으로 보는 것에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「어느 영상이든 잘못이 있게 마련이니 틀린 곳부터 찾으면 돼.」","correct":true,"mis_target":"K6-2-u3-X02"},{"t":"지호 — 「맞는 것은 맞다고, 부족한 것은 부족하다고 까닭을 들어 말하는 거야.」","mis":"K6-2-u3-X02"},{"t":"라온 — 「타당한 점을 먼저 찾고 그다음에 보완할 점을 찾아.」","mis":"K6-2-u3-X11"}],"explanation":["지호와 라온은 따져 보기를 바르게 말했어요.","은솔은 잘못이 있다고 미리 정해 두었어요.","그것은 비판이 아니라 의심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#1','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',2,'mc','auto','주장이 우리를 만나는 자리에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X03']::text[],false,'{"seq":1,"concept":"K6-2-u3-C2","difficulty":2,"kind":"mc","stem":"주장이 우리를 만나는 자리에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"발표 · 영상 · 카드 뉴스 · 광고 · 누리 소통망 글 어디에나 주장이 담길 수 있다","correct":true},{"t":"발표와 연설 같은 말에만 주장이 들어 있다","mis":"K6-2-u3-X03"},{"t":"영상과 카드 뉴스는 사실만 전하므로 주장이 없다","mis":"K6-2-u3-X03"},{"t":"광고는 물건을 보여 줄 뿐 주장이 없다","mis":"K6-2-u3-X03"}],"explanation":["담는 그릇은 여러 가지예요.","영상·카드 뉴스·광고에도 주장이 담겨요.","찾는 방법은 같아요 — 주장·이유·근거."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#2','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',2,'sa','auto','이유는 왜 그렇게 주장하는지를 ○○하는 말이에요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C1","difficulty":2,"kind":"sa","stem":"이유는 왜 그렇게 주장하는지를 ○○하는 말이에요. ○○에 알맞은 두 글자를 쓰세요.","answer":["설명"],"explanation":["주장은 의견을 드러내는 말이에요.","이유는 그 의견의 까닭을 설명해요.","근거는 이유를 뒷받침해요."],"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#3','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',3,'mc','auto','하리가 「그 말이 사실이라는 자료도 보여 주었어?」라고 물은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X01','K6-2-u3-X03']::text[],false,'{"seq":3,"concept":"K6-2-u3-C1","difficulty":3,"kind":"mc","stem":"하리가 「그 말이 사실이라는 자료도 보여 주었어?」라고 물은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"이유를 뒷받침하는 근거가 있는지 따져 보려고","correct":true},{"t":"서담이의 말을 믿지 않기로 미리 정해서","mis":"K6-2-u3-X02"},{"t":"영상의 주장이 무엇인지 몰라서","mis":"K6-2-u3-X01"},{"t":"영상이 얼마나 길었는지 궁금해서","mis":"K6-2-u3-X03"}],"explanation":["하리는 먼저 이유가 있었는지 물었어요.","그다음 이유를 받쳐 줄 자료를 물었어요.","믿지 않으려는 것이 아니라 따져 보려는 물음이에요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#4','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',3,'mc','auto','「비판적으로 보기」와 「무조건 의심하기」를 바르게 가른 것은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X03']::text[],false,'{"seq":4,"concept":"K6-2-u3-C2","difficulty":3,"kind":"mc","stem":"「비판적으로 보기」와 「무조건 의심하기」를 바르게 가른 것은 어느 것인가요?","options":[{"t":"비판적으로 보기는 까닭을 들어 옳고 그름을 따지고, 무조건 의심하기는 따지기 전에 믿지 않기로 정한다","correct":true},{"t":"둘은 같은 말이다","mis":"K6-2-u3-X02"},{"t":"비판적으로 보기는 말한 사람을 깎아내리는 것이다","mis":"K6-2-u3-X02"},{"t":"의심하지 않고 그대로 믿는 것이 비판적으로 보기이다","mis":"K6-2-u3-X03"}],"explanation":["의심은 따지기 전에 정해 버려요.","비판은 까닭을 들어 따져요.","그래서 맞는 것은 맞다고도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#5','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',3,'ox','auto','「복도에서 뛰면 부딪칠 수 있다」는 주장이에요.',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":5,"concept":"K6-2-u3-C1","difficulty":3,"kind":"ox","stem":"「복도에서 뛰면 부딪칠 수 있다」는 주장이에요.","answer":"X","reason_options":[{"t":"왜 걸어 다녀야 하는지를 밝힌 이유이기 때문에","correct":true},{"t":"무엇을 하자는 말이 들어 있기 때문에","mis":"K6-2-u3-X01"}],"mis":"K6-2-u3-X01","explanation":["「복도에서는 걸어 다닙시다」가 주장이에요.","「부딪칠 수 있다」는 그 까닭이에요.","그래서 이 말은 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#6','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',3,'match','auto','주장을 대하는 태도와 그 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C2","difficulty":3,"kind":"match","stem":"주장을 대하는 태도와 그 결과를 알맞게 이으세요.","pairs":[{"l":"그대로 믿는다","r":"사실이 아닌 것을 다른 사람에게 옮길 수 있다"},{"l":"무조건 의심한다","r":"맞는 말도 받아들이지 못한다"},{"l":"까닭을 들어 따진다","r":"믿을 만한 정보를 골라 쓸 수 있다"}],"mis":"K6-2-u3-X02","explanation":["그대로 믿으면 잘못된 정보도 옮겨요.","무조건 의심하면 맞는 말도 놓쳐요.","따져 보아야 골라 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#7','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',3,'error','auto','「급식을 남기지 맙시다」의 이유와 근거를 친구들이 말했어요. 자리를 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":7,"concept":"K6-2-u3-C1","difficulty":3,"kind":"error","stem":"「급식을 남기지 맙시다」의 이유와 근거를 친구들이 말했어요. 자리를 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「근거는 ‘음식을 남기지 맙시다’야.」","correct":true,"mis_target":"K6-2-u3-X01"},{"t":"준서 — 「이유는 ‘남은 음식은 버려지기 때문이다’야.」","mis":"K6-2-u3-X01"},{"t":"가윤 — 「근거는 ‘하루에 남은 음식을 잰 우리 학교 기록’이야.」","mis":"K6-2-u3-X01"}],"explanation":["준서는 까닭을 이유로 바르게 말했어요.","가윤은 이유를 받쳐 주는 기록을 근거로 말했어요.","태린이 말한 것은 주장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#8','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',4,'mc','auto','주장 · 이유 · 근거가 모두 갖추어진 말은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X08']::text[],false,'{"seq":8,"concept":"K6-2-u3-C1","difficulty":4,"kind":"mc","stem":"주장 · 이유 · 근거가 모두 갖추어진 말은 어느 것인가요?","options":[{"t":"「계단 손잡이를 잡고 내려갑시다. 발을 헛디뎌도 버틸 수 있기 때문입니다. 손잡이를 잡은 날 덜 미끄러졌다고 답한 우리 반 조사가 있습니다.」","correct":true},{"t":"「계단 손잡이를 잡고 내려갑시다. 꼭 그렇게 합시다.」","mis":"K6-2-u3-X01"},{"t":"「계단 손잡이를 잡고 내려갑시다. 발을 헛디뎌도 버틸 수 있기 때문입니다.」","mis":"K6-2-u3-X08"},{"t":"「우리 반 조사가 있습니다. 손잡이는 차갑습니다.」","mis":"K6-2-u3-X01"}],"explanation":["첫째 보기는 주장을 되풀이했을 뿐이에요.","둘째 보기는 이유까지만 있고 근거가 없어요.","정답은 하자는 말·까닭·조사 자료를 모두 갖추었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#9','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C1',4,'essay','teacher','서담이가 본 영상의 내용을 주장 · 이유 · 근거로 나누어 쓰고, 빠진 것이 무엇인지 밝히세요. 그리고 빠진 자리를 채우려면 어떤 자료가 있으면 좋을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":4,"kind":"essay","stem":"서담이가 본 영상의 내용을 주장 · 이유 · 근거로 나누어 쓰고, 빠진 것이 무엇인지 밝히세요. 그리고 빠진 자리를 채우려면 어떤 자료가 있으면 좋을지 쓰세요.","answer_guide":{"answer":"예: 주장 — 아침에 물을 두 컵 마시자. 이유 — 자는 동안 몸에서 물이 빠져나가기 때문이다. 근거 — 없다. 그 말이 사실이라는 자료를 보여 주지 않았다. 자는 동안 몸에서 물이 빠져나간다는 것을 다룬 책이나 건강 기관의 안내 자료를 보여 주면 이유가 힘을 얻을 것이다.","scoring_points":["주장과 이유를 바르게 갈라 썼는가","근거가 빠졌다는 것을 밝혔는가","확인할 수 있는 자료(책·기관 안내 등)를 들었는가"]},"explanation":["하자는 말과 까닭을 먼저 갈라요.","하리가 물은 것이 바로 빠진 자리예요.","근거는 확인할 수 있는 자료여야 해요."],"asset":{"type":"speech","turns":[{"who":"서담","text":"방금 본 영상에서 그러던데, 아침에 물을 두 컵 마시면 하루 종일 힘이 난대."},{"who":"하리","text":"그렇게 말한 까닭도 나왔어?"},{"who":"서담","text":"응. 자는 동안 몸에서 물이 빠져나가기 때문이래."},{"who":"하리","text":"그 말이 사실이라는 자료도 보여 주었어?"},{"who":"서담","text":"아니. 그 말만 하고 다음 장면으로 넘어갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L01_challenge#10','kor',6,2,'u3','L01','g6_2_kor_u3_L01_challenge','lesson_challenge','K6-2-u3-C2',4,'essay','teacher','「비판적으로 본다는 것은 무조건 의심하는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C2","difficulty":4,"kind":"essay","stem":"「비판적으로 본다는 것은 무조건 의심하는 것이다.」라는 말이 왜 알맞지 않은지 쓰고, 주장을 따져 보지 않고 그대로 믿었을 때 생길 수 있는 일을 두 가지 쓰세요.","answer_guide":{"answer":"예: 비판적으로 본다는 것은 무조건 믿지 않는 것이 아니라 옳고 그른지를 제대로 따져 보는 것이다. 맞는 것은 맞다고, 부족한 것은 부족하다고 까닭을 들어 말하는 것이기 때문이다. 그대로 믿으면 사실이 아닌 것을 사실로 알게 되고, 그 잘못된 정보를 다른 사람에게 옮길 수 있다.","scoring_points":["따져 보기와 무조건 의심하기를 바르게 갈랐는가","맞는 것은 맞다고도 말한다는 점을 썼는가","그대로 믿었을 때의 문제를 두 가지 썼는가"]},"explanation":["의심은 따지기 전에 정해요.","비판은 까닭을 들어 따져요.","그대로 믿으면 잘못된 정보가 퍼져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#1','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C3',1,'mc','auto','주장하는 말을 들을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":1,"concept":"K6-2-u3-C3","difficulty":1,"kind":"mc","stem":"주장하는 말을 들을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"이유와 근거를 메모하며 듣는다","correct":true},{"t":"말이 끝나기 전에 결론을 미리 정해 둔다","mis":"K6-2-u3-X04"},{"t":"말하는 사람의 목소리 크기만 보고 판단한다","mis":"K6-2-u3-X04"},{"t":"주장만 듣고 나머지는 흘려듣는다","mis":"K6-2-u3-X04"}],"explanation":["말은 되감을 수 없어요.","이유와 근거를 적어 두어야 평가할 거리가 남아요.","결론은 다 들은 뒤에 내려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#2','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',1,'sa','auto','실제로 있었던 일 하나를 들어 보이는 근거 자료를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C6","difficulty":1,"kind":"sa","stem":"실제로 있었던 일 하나를 들어 보이는 근거 자료를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["사례"],"explanation":["표는 값을 나란히 놓아요.","그래프는 흐름을, 면담 자료는 사람의 말을 보여 줘요.","있었던 일 하나를 들면 사례예요."],"mis":"K6-2-u3-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#3','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C4',1,'ox','auto','실천 가능한 주장이어야 가치 있는 주장이라고 할 수 있어요.',ARRAY['K6-2-u3-X05']::text[],false,'{"seq":3,"concept":"K6-2-u3-C4","difficulty":1,"kind":"ox","stem":"실천 가능한 주장이어야 가치 있는 주장이라고 할 수 있어요.","answer":"O","reason_options":[{"t":"무엇을 언제 할지 알아야 생활에서 해 볼 수 있기 때문에","correct":true},{"t":"말이 크고 멋있을수록 가치 있는 주장이기 때문에","mis":"K6-2-u3-X05"}],"mis":"K6-2-u3-X05","explanation":["주장은 문제 해결에 도움이 되어야 해요.","그리고 실천할 수 있어야 해요.","말만 크면 무엇부터 할지 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#4','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',1,'mc','auto','근거의 타당성을 판단하는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X01']::text[],false,'{"seq":4,"concept":"K6-2-u3-C6","difficulty":1,"kind":"mc","stem":"근거의 타당성을 판단하는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"근거가 이유와 관련 있고 객관적인 사실이나 정보인가?","correct":true},{"t":"근거가 말한 사람의 느낌을 잘 드러내는가?","mis":"K6-2-u3-X08"},{"t":"근거가 길고 어려운 말로 되어 있는가?","mis":"K6-2-u3-X08"},{"t":"근거가 주장보다 먼저 나오는가?","mis":"K6-2-u3-X01"}],"explanation":["근거는 이유를 받쳐 주어야 해요.","느낌이나 짐작은 근거가 되지 못해요.","누가 보아도 그러한 사실이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#5','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C3',2,'mc','auto','민율이의 말을 주장 · 이유 · 근거로 나누어 간추릴 때, 주장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X04']::text[],false,'{"seq":5,"concept":"K6-2-u3-C3","difficulty":2,"kind":"mc","stem":"민율이의 말을 주장 · 이유 · 근거로 나누어 간추릴 때, 주장으로 알맞은 것은 어느 것인가요?","options":[{"t":"모르는 것은 그날 안에 물어보자","correct":true},{"t":"모르는 것을 그대로 두면 다음에 배울 것까지 막힌다","mis":"K6-2-u3-X01"},{"t":"예담이는 분수의 뜻을 몰라 여러 단원에서 어려워했다","mis":"K6-2-u3-X01"},{"t":"묻는 일은 부끄러운 일이다","mis":"K6-2-u3-X04"}],"explanation":["「그날 안에 물어보자」가 하자는 말이에요.","「막히기 때문」은 이유, 예담이 이야기는 근거예요.","「부끄러운 일이다」는 민율이가 한 말과 반대예요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#6','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C5',2,'mc','auto','「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X07','K6-2-u3-X06']::text[],false,'{"seq":6,"concept":"K6-2-u3-C5","difficulty":2,"kind":"mc","stem":"「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"다음에 배울 것까지 막히기 때문이다","correct":true},{"t":"나는 손을 드는 것이 재미있기 때문이다","mis":"K6-2-u3-X07"},{"t":"수업 시간은 사십 분이기 때문이다","mis":"K6-2-u3-X06"},{"t":"선생님 목소리가 크기 때문이다","mis":"K6-2-u3-X06"}],"explanation":["이유는 주장과 이어져야 해요.","많은 사람이 받아들일 만해야 해요.","「막히기 때문」은 누구에게나 해당하고 주장과 곧바로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#7','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',2,'match','auto','근거 자료의 유형과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C6","difficulty":2,"kind":"match","stem":"근거 자료의 유형과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"표","r":"여러 값을 나란히 놓아 견주게 해 준다"},{"l":"그래프","r":"늘고 주는 흐름을 한눈에 보여 준다"},{"l":"면담 자료","r":"그 일을 겪은 사람의 말을 그대로 옮긴다"},{"l":"사례","r":"실제로 있었던 일 하나를 들어 보인다"}],"mis":"K6-2-u3-X10","explanation":["표는 나란히, 그래프는 흐름이에요.","면담 자료는 사람의 말이에요.","사례는 있었던 일 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#8','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C4',2,'mc','auto','더 실천 가능한 주장은 어느 것인가요?',ARRAY['K6-2-u3-X05']::text[],false,'{"seq":8,"concept":"K6-2-u3-C4","difficulty":2,"kind":"mc","stem":"더 실천 가능한 주장은 어느 것인가요?","options":[{"t":"잠자기 전에 열 쪽씩 책을 읽읍시다","correct":true},{"t":"우리 모두 훌륭한 사람이 됩시다","mis":"K6-2-u3-X05"},{"t":"세상을 더 좋게 만듭시다","mis":"K6-2-u3-X05"},{"t":"언젠가는 책을 많이 읽읍시다","mis":"K6-2-u3-X05"}],"explanation":["언제 무엇을 할지 정해져 있어야 실천할 수 있어요.","「잠자기 전에 열 쪽씩」은 오늘 바로 할 수 있어요.","말이 크면 무엇부터 할지 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#9','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C5',2,'ox','auto','「학교 도서관에 책을 더 사자. 내가 읽고 싶은 책이 아직 없기 때문이다.」의 이유는 많은 사람이 받아들일 만해요.',ARRAY['K6-2-u3-X07']::text[],false,'{"seq":9,"concept":"K6-2-u3-C5","difficulty":2,"kind":"ox","stem":"「학교 도서관에 책을 더 사자. 내가 읽고 싶은 책이 아직 없기 때문이다.」의 이유는 많은 사람이 받아들일 만해요.","answer":"X","reason_options":[{"t":"주장과 관련은 있지만 한 사람의 사정이라 많은 사람이 고개를 끄덕이기 어렵기 때문에","correct":true},{"t":"주장과 관련이 있으면 타당한 이유이기 때문에","mis":"K6-2-u3-X07"}],"mis":"K6-2-u3-X07","explanation":["이 이유는 주장과 관련은 있어요.","그러나 한 사람이 읽고 싶은 책 이야기예요.","두 물음 가운데 하나만 통과했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_basic#10','kor',6,2,'u3','L02','g6_2_kor_u3_L02_basic','lesson_basic','K6-2-u3-C6',3,'error','auto','근거로 나온 말이 사실인지 확인하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X09']::text[],false,'{"seq":10,"concept":"K6-2-u3-C6","difficulty":3,"kind":"error","stem":"근거로 나온 말이 사실인지 확인하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하엘 — 「누리집에서 한 번 검색해서 나온 기사면 그대로 믿으면 돼.」","correct":true,"mis_target":"K6-2-u3-X09"},{"t":"도하 — 「그 내용을 다룬 책이나 기사를 찾아보고 출처도 살펴봐.」","mis":"K6-2-u3-X09"},{"t":"세아 — 「그 일을 맡은 기관의 누리집에서 확인하거나 어른께 여쭈어.」","mis":"K6-2-u3-X09"}],"explanation":["책·기사·기관 누리집·어른께 여쭙기가 모두 방법이에요.","찾은 기사도 어디에서 나왔는지 한 번 더 살펴요.","검색 한 번으로 끝내면 확인한 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#1','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C3',2,'sa','auto','주장 · 이유 · 근거로 나누어 간추리며 듣는 것을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C3","difficulty":2,"kind":"sa","stem":"주장 · 이유 · 근거로 나누어 간추리며 듣는 것을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["요약"],"explanation":["메모하며 듣기는 적으며 들어요.","요약하며 듣기는 간추리며 들어요.","견주며 듣기는 내 생각과 견주어요."],"mis":"K6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#2','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C4',2,'mc','auto','주장이 가치 있고 중요한지 판단하는 두 물음을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X05','K6-2-u3-X01','K6-2-u3-X03']::text[],false,'{"seq":2,"concept":"K6-2-u3-C4","difficulty":2,"kind":"mc","stem":"주장이 가치 있고 중요한지 판단하는 두 물음을 바르게 모은 것은 어느 것인가요?","options":[{"t":"문제를 해결하거나 생활하는 데 도움이 되는가 · 실천 가능한가","correct":true},{"t":"말이 멋있는가 · 길이가 적당한가","mis":"K6-2-u3-X05"},{"t":"주장과 관련 있는가 · 객관적인가","mis":"K6-2-u3-X01"},{"t":"말한 사람이 유명한가 · 목소리가 큰가","mis":"K6-2-u3-X03"}],"explanation":["주장은 도움이 되는지와 실천 가능한지로 재요.","「관련 있는가」는 이유와 근거를 재는 물음이에요.","말한 사람이나 말솜씨는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#3','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',3,'mc','auto','「그날의 물음」의 근거를 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X01']::text[],false,'{"seq":3,"concept":"K6-2-u3-C6","difficulty":3,"kind":"mc","stem":"「그날의 물음」의 근거를 바르게 모은 것은 어느 것인가요?","options":[{"t":"예담이의 사례와 우리 반 조사 결과","correct":true},{"t":"묻는 일은 부끄러운 일이 아니라는 말","mis":"K6-2-u3-X08"},{"t":"배움은 앞의 것 위에 뒤의 것이 쌓인다는 말","mis":"K6-2-u3-X01"},{"t":"오늘부터 그날 안에 물어보자는 말","mis":"K6-2-u3-X01"}],"explanation":["근거는 이유를 받쳐 주는 자료나 사실이에요.","예담이 이야기는 사례, 반 조사는 조사 결과예요.","「쌓이는 일」은 이유를 풀어 준 설명이에요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#4','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',3,'mc','auto','민율이가 근거를 「우리 반 친구의 사례」와 「우리 반에서 조사한 결과」로 든 것이 좋은 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X14','K6-2-u3-X09']::text[],false,'{"seq":4,"concept":"K6-2-u3-C6","difficulty":3,"kind":"mc","stem":"민율이가 근거를 「우리 반 친구의 사례」와 「우리 반에서 조사한 결과」로 든 것이 좋은 까닭은 어느 것인가요?","options":[{"t":"듣는 사람이 확인할 수 있는 객관적인 사실이어서","correct":true},{"t":"말한 사람의 느낌이 잘 드러나서","mis":"K6-2-u3-X08"},{"t":"듣는 사람의 마음을 세게 움직여서","mis":"K6-2-u3-X14"},{"t":"확인할 수 없어서 따질 수 없어서","mis":"K6-2-u3-X09"}],"explanation":["같은 반 친구는 예담이에게 물어볼 수 있어요.","반 조사 결과도 다시 확인할 수 있어요.","확인할 수 있어야 객관적인 근거예요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#5','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C5',3,'ox','auto','이유가 주장과 관련만 있으면 타당한 이유라고 할 수 있어요.',ARRAY['K6-2-u3-X07']::text[],false,'{"seq":5,"concept":"K6-2-u3-C5","difficulty":3,"kind":"ox","stem":"이유가 주장과 관련만 있으면 타당한 이유라고 할 수 있어요.","answer":"X","reason_options":[{"t":"많은 사람이 받아들일 만한지도 함께 따져야 하기 때문에","correct":true},{"t":"이유는 주장과 이어지기만 하면 되기 때문에","mis":"K6-2-u3-X07"}],"mis":"K6-2-u3-X07","explanation":["이유를 재는 물음은 두 가지예요.","주장과 관련 있는가, 많은 사람이 받아들일 만한가.","하나만 통과하면 약한 이유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#6','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C4',3,'match','auto','무엇의 타당성인지와 그것을 재는 물음을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C4","difficulty":3,"kind":"match","stem":"무엇의 타당성인지와 그것을 재는 물음을 알맞게 이으세요.","pairs":[{"l":"주장","r":"문제 해결에 도움이 되고 실천 가능한가"},{"l":"이유","r":"주장과 관련 있고 많은 사람이 받아들일 만한가"},{"l":"근거","r":"이유와 관련 있고 객관적인 사실이나 정보인가"}],"mis":"K6-2-u3-X01","explanation":["주장은 가치와 실천 가능성을 보아요.","이유는 주장과의 관련과 받아들일 만함을 보아요.","근거는 이유와의 관련과 객관성을 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#7','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C3',3,'error','auto','주장하는 말을 듣는 태도를 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":7,"concept":"K6-2-u3-C3","difficulty":3,"kind":"error","stem":"주장하는 말을 듣는 태도를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"나린 — 「말은 다시 들을 수 없으니 그냥 느낌만 기억하면 돼.」","correct":true,"mis_target":"K6-2-u3-X04"},{"t":"유찬 — 「말은 되감을 수 없으니 이유와 근거를 메모하며 들어.」","mis":"K6-2-u3-X04"},{"t":"보미 — 「지나치게 감정에 호소하지는 않는지도 살피며 들어.」","mis":"K6-2-u3-X04"}],"explanation":["말은 한 번 듣고 지나가요.","그래서 적고 간추리며 들어야 평가할 거리가 남아요.","느낌만 남기면 따질 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#8','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',4,'mc','auto','「동네 놀이터에 그늘막을 세우자. 여름 한낮에 놀이 기구가 뜨거워지기 때문이다.」의 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X06']::text[],false,'{"seq":8,"concept":"K6-2-u3-C6","difficulty":4,"kind":"mc","stem":"「동네 놀이터에 그늘막을 세우자. 여름 한낮에 놀이 기구가 뜨거워지기 때문이다.」의 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여름 한낮에 놀이 기구의 뜨거운 정도를 시간마다 재어 적은 표","correct":true},{"t":"나는 그늘에서 노는 것을 좋아한다는 말","mis":"K6-2-u3-X08"},{"t":"그늘막은 예쁜 색이 많다는 말","mis":"K6-2-u3-X06"},{"t":"이웃 동네 놀이터가 더 넓다는 사례","mis":"K6-2-u3-X06"}],"explanation":["이유는 「놀이 기구가 뜨거워진다」예요.","그것을 보여 주는 자료가 근거예요.","시간마다 잰 표는 이유와 관련 있고 객관적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#9','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C5',4,'essay','teacher','「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유를 하나 더 만들어 쓰고, 그 이유가 이유를 재는 두 물음을 통과하는지 하나씩 따져 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C5","difficulty":4,"kind":"essay","stem":"「모르는 것은 그날 안에 물어보자」를 뒷받침하는 이유를 하나 더 만들어 쓰고, 그 이유가 이유를 재는 두 물음을 통과하는지 하나씩 따져 쓰세요.","answer_guide":{"answer":"예: 이유 — 궁금한 것을 바로 물어보면 그날 배운 내용이 머릿속에 또렷하게 남기 때문이다. 이 이유는 「물어보자」는 주장과 곧바로 이어지므로 주장과 관련 있다. 또 나 혼자만의 사정이 아니라 수업을 듣는 누구에게나 해당하므로 많은 사람이 받아들일 만하다.","scoring_points":["주장과 이어지는 이유를 새로 만들었는가","주장과 관련 있는지 따졌는가","많은 사람이 받아들일 만한지 따졌는가"]},"explanation":["이유는 주장과 이어져야 해요.","나만의 느낌이 아니어야 해요.","두 물음을 하나씩 대어 보아요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L02_challenge#10','kor',6,2,'u3','L02','g6_2_kor_u3_L02_challenge','lesson_challenge','K6-2-u3-C6',4,'essay','teacher','「그날의 물음」의 근거 가운데 하나를 골라 근거의 유형을 쓰고, 그 근거가 사실인지 확인하는 방법을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C6","difficulty":4,"kind":"essay","stem":"「그날의 물음」의 근거 가운데 하나를 골라 근거의 유형을 쓰고, 그 근거가 사실인지 확인하는 방법을 두 가지 쓰세요.","answer_guide":{"answer":"예: 「궁금한 것을 물어본 날에는 다음 날 수업이 더 쉬웠다고 답한 사람이 많았다」는 우리 반 조사 결과로, 표로 나타낼 수 있는 자료이다. 사실인지 확인하려면 조사한 종이나 표를 직접 보여 달라고 하거나, 반 친구들에게 다시 물어 조사해 볼 수 있다.","scoring_points":["근거를 하나 골라 유형을 바르게 썼는가","확인 방법을 두 가지 썼는가","확인 방법이 그 근거에 알맞은가"]},"explanation":["조사 결과는 표나 그래프로 보여 줄 수 있어요.","사례는 겪은 사람에게 물어볼 수 있어요.","확인할 수 있어야 믿을 수 있어요."],"asset":{"type":"passage","lines":["저는 모르는 것은 그날 안에 물어보자고 말하고 싶습니다.","모르는 것을 그대로 두면 다음에 배울 것까지 막히기 때문입니다.","배움은 앞의 것 위에 뒤의 것이 쌓이는 일이라, 아래가 비면 위가 흔들립니다.","예담이는 분수의 뜻을 잘 모른 채로 넘어갔다가 여러 단원에서 어려워했습니다.","다시 물어보고 처음부터 확인한 뒤에야 막힌 곳이 풀렸습니다.","우리 반에서 조사해 보니, 궁금한 것을 물어본 날에는","다음 날 수업이 더 쉬웠다고 답한 사람이 훨씬 많았습니다.","묻는 일은 부끄러운 일이 아닙니다. 오늘부터 그날 안에 물어봅시다."],"title":"민율이의 주장하는 말 「그날의 물음」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#1','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',1,'mc','auto','주장하는 말을 평가하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X11','K6-2-u3-X12']::text[],false,'{"seq":1,"concept":"K6-2-u3-C7","difficulty":1,"kind":"mc","stem":"주장하는 말을 평가하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"타당한 점을 먼저 찾고 그다음에 보완할 점을 찾는다","correct":true},{"t":"흠부터 찾고 타당한 점은 찾지 않는다","mis":"K6-2-u3-X11"},{"t":"이긴 쪽을 고르고 끝낸다","mis":"K6-2-u3-X11"},{"t":"표시만 하고 까닭은 말하지 않는다","mis":"K6-2-u3-X12"}],"explanation":["흠부터 찾으면 어느 발표에나 잘못이 있다고 여기게 돼요.","타당한 점을 먼저 찾아요.","그래야 무엇을 살리고 고칠지 함께 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#2','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',1,'sa','auto','자기 생각이 아니라 누가 보아도 그러한 것을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C8","difficulty":1,"kind":"sa","stem":"자기 생각이 아니라 누가 보아도 그러한 것을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["객관적"],"explanation":["자기 혼자만의 느낌에 치우친 것은 주관적이에요.","누가 보아도 그러한 것은 객관적이에요.","근거는 객관적이어야 해요."],"mis":"K6-2-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#3','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',1,'ox','auto','조사한 자료를 근거로 쓸 때에는 어디에서 나온 자료인지 밝혀야 해요.',ARRAY['K6-2-u3-X13']::text[],false,'{"seq":3,"concept":"K6-2-u3-C8","difficulty":1,"kind":"ox","stem":"조사한 자료를 근거로 쓸 때에는 어디에서 나온 자료인지 밝혀야 해요.","answer":"O","reason_options":[{"t":"듣는 사람이 사실인지 확인할 수 있고 남의 자료를 내 것처럼 쓰지 않게 되기 때문에","correct":true},{"t":"출처를 밝히면 말이 길어져 설득력이 떨어지기 때문에","mis":"K6-2-u3-X13"}],"mis":"K6-2-u3-X13","explanation":["출처를 밝히지 않으면 확인할 길이 없어요.","남이 만든 자료를 내 것처럼 쓰게 돼요.","「○○에서 조사한 표입니다」처럼 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#4','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',1,'mc','auto','다경이와 세온이가 학교 도서관에 대해 발표한 목적은 무엇인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X11']::text[],false,'{"seq":4,"concept":"K6-2-u3-C7","difficulty":1,"kind":"mc","stem":"다경이와 세온이가 학교 도서관에 대해 발표한 목적은 무엇인가요?","options":[{"t":"학교 도서관을 바꾸자고 듣는 사람을 설득하려고","correct":true},{"t":"자기가 읽은 책을 소개하려고","mis":"K6-2-u3-X01"},{"t":"도서관이 어디에 있는지 알려 주려고","mis":"K6-2-u3-X01"},{"t":"누가 더 말을 잘하는지 겨루려고","mis":"K6-2-u3-X11"}],"explanation":["두 발표는 모두 도서관을 더 낫게 만들자는 말이에요.","설득하려는 말이니 주장하는 말이에요.","겨루기가 아니라 설득이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#5','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C1',2,'mc','auto','다경이의 발표에서 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":5,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"다경이의 발표에서 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"수업이 끝난 뒤에는 책을 볼 시간이 있는 학생이 적기 때문이다","correct":true},{"t":"점심시간에도 도서관을 열어야 한다","mis":"K6-2-u3-X01"},{"t":"이용하고 싶은 시간을 조사한 표","mis":"K6-2-u3-X01"},{"t":"이웃 학교 소식지에 실린 내용","mis":"K6-2-u3-X01"}],"explanation":["「열어야 한다」는 주장이에요.","「~ 때문입니다」로 밝힌 까닭이 이유예요.","조사한 표와 소식지 내용은 근거예요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관을 점심시간에도 열어야 한다고 생각합니다.","수업이 끝난 뒤에는 도서관에 남아 책을 볼 시간이 있는 학생이 적기 때문입니다.","하교 시간이 되면 대부분 바로 집이나 다른 곳으로 가야 합니다.","우리 학교 도서관에서 조사한 표를 보면, 이용하고 싶은 시간으로","점심시간을 고른 학생이 다른 시간을 고른 학생보다 훨씬 많았습니다.","이웃 학교는 점심시간에 문을 연 뒤로 찾는 학생이 눈에 띄게 늘었다고 합니다.","학교 소식지에 실린 내용입니다.","점심시간에 도서관을 열면 더 많은 학생이 책을 만날 수 있습니다."],"title":"다경이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#6','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',2,'mc','auto','세온이의 근거가 객관적이지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X05','K6-2-u3-X06']::text[],false,'{"seq":6,"concept":"K6-2-u3-C8","difficulty":2,"kind":"mc","stem":"세온이의 근거가 객관적이지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"새 책 냄새를 좋아한다는 느낌과 사람이 많아 보였다는 짐작에 머물러 있어서","correct":true},{"t":"근거가 너무 짧아서","mis":"K6-2-u3-X08"},{"t":"주장이 학생들에게 도움이 되지 않아서","mis":"K6-2-u3-X05"},{"t":"이유가 주장과 관련이 없어서","mis":"K6-2-u3-X06"}],"explanation":["「좋아합니다」는 세온이의 느낌이에요.","「많아 보였습니다」는 짐작이에요.","누가 보아도 그러한 것이 아니에요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#7','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',2,'match','auto','평가할 때 쓰는 말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C8","difficulty":2,"kind":"match","stem":"평가할 때 쓰는 말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"타당하다","r":"일의 이치로 보아 옳다"},{"l":"주관적","r":"자기 혼자만의 생각이나 느낌에 치우친 것"},{"l":"뒷받침하다","r":"뒤에서 받쳐 힘이 되어 주다"},{"l":"설득하다","r":"잘 알아듣도록 말하여 마음을 움직이다"}],"mis":"K6-2-u3-X08","explanation":["타당하다는 이치로 보아 옳다는 뜻이에요.","주관적은 객관적과 반대예요.","근거는 이유를 뒷받침해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#8','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',2,'mc','auto','세온이의 발표에서 타당한 점은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X11']::text[],false,'{"seq":8,"concept":"K6-2-u3-C7","difficulty":2,"kind":"mc","stem":"세온이의 발표에서 타당한 점은 어느 것인가요?","options":[{"t":"이유가 주장과 관련이 있다","correct":true},{"t":"근거로 조사한 자료를 보여 주었다","mis":"K6-2-u3-X08"},{"t":"다른 학교의 사례를 들었다","mis":"K6-2-u3-X08"},{"t":"타당한 점은 하나도 없다","mis":"K6-2-u3-X11"}],"explanation":["새 책이 많아야 온다는 이유는 새 책을 사자는 주장과 이어져요.","조사 자료와 사례는 다경이가 든 근거예요.","약한 발표에도 타당한 점은 있어요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#9','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C7',2,'ox','auto','같은 발표를 두고 사람마다 판단이 다를 때에는 「그냥 그렇게 느꼈어.」라고 말하면 돼요.',ARRAY['K6-2-u3-X12']::text[],false,'{"seq":9,"concept":"K6-2-u3-C7","difficulty":2,"kind":"ox","stem":"같은 발표를 두고 사람마다 판단이 다를 때에는 「그냥 그렇게 느꼈어.」라고 말하면 돼요.","answer":"X","reason_options":[{"t":"어떤 기준을 더 무겁게 보았는지 까닭을 말해야 하기 때문에","correct":true},{"t":"판단은 사람마다 다르니 까닭은 없어도 되기 때문에","mis":"K6-2-u3-X12"}],"mis":"K6-2-u3-X12","explanation":["판단은 갈릴 수 있어요.","그러나 까닭은 반드시 있어야 해요.","「나는 ○○을 가장 무겁게 보았어」처럼 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_basic#10','kor',6,2,'u3','L04','g6_2_kor_u3_L04_basic','lesson_basic','K6-2-u3-C8',3,'mc','auto','세온이의 근거를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X14','K6-2-u3-X08']::text[],false,'{"seq":10,"concept":"K6-2-u3-C8","difficulty":3,"kind":"mc","stem":"세온이의 근거를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"새 책이 들어온 달과 그렇지 않은 달의 대출 수를 견주어 보여 준다","correct":true},{"t":"새 책이 좋다고 더 힘주어 여러 번 말한다","mis":"K6-2-u3-X14"},{"t":"새 책이 없으면 너무 속상하다고 마음에 호소한다","mis":"K6-2-u3-X14"},{"t":"새 책 냄새가 얼마나 좋은지 자세히 그려 말한다","mis":"K6-2-u3-X08"}],"explanation":["느낌을 키우는 것은 고치는 것이 아니에요.","누가 보아도 그러한 자료로 바꾸어요.","대출 수를 견주면 확인할 수 있어요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#1','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',2,'sa','auto','평가 기준표에 ◎ · ○ · △로 표시만 하고 끝내지 않고, 그렇게 판단한 ○○을 함께 말해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C7","difficulty":2,"kind":"sa","stem":"평가 기준표에 ◎ · ○ · △로 표시만 하고 끝내지 않고, 그렇게 판단한 ○○을 함께 말해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["까닭"],"explanation":["표시만으로는 왜 그런지 알 수 없어요.","판단한 까닭을 말해야 해요.","그래야 듣는 사람이 따라올 수 있어요."],"mis":"K6-2-u3-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#2','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',2,'mc','auto','다경이와 세온이의 발표를 견줄 때 더 타당하다고 볼 수 있는 쪽과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X12']::text[],false,'{"seq":2,"concept":"K6-2-u3-C7","difficulty":2,"kind":"mc","stem":"다경이와 세온이의 발표를 견줄 때 더 타당하다고 볼 수 있는 쪽과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"다경 — 주장 · 이유 · 근거가 자연스럽게 이어지고 객관적인 자료를 썼다","correct":true},{"t":"세온 — 새 책 냄새를 좋아한다는 말이 솔직하다","mis":"K6-2-u3-X08"},{"t":"세온 — 발표가 더 짧고 쉽다","mis":"K6-2-u3-X12"},{"t":"다경 — 발표 시간이 더 길다","mis":"K6-2-u3-X12"}],"explanation":["다경이는 조사한 표와 소식지 내용을 근거로 들었어요.","세온이의 근거는 느낌과 짐작이에요.","길이나 솔직함은 타당성의 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#3','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C8',3,'mc','auto','다경이가 「학교 소식지에 실린 내용입니다.」라고 덧붙인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X13','K6-2-u3-X02']::text[],false,'{"seq":3,"concept":"K6-2-u3-C8","difficulty":3,"kind":"mc","stem":"다경이가 「학교 소식지에 실린 내용입니다.」라고 덧붙인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"근거의 출처를 밝혀 듣는 사람이 사실인지 확인할 수 있게 하려고","correct":true},{"t":"말을 더 길게 하려고","mis":"K6-2-u3-X13"},{"t":"소식지를 자랑하려고","mis":"K6-2-u3-X13"},{"t":"이웃 학교를 깎아내리려고","mis":"K6-2-u3-X02"}],"explanation":["어디에서 나온 자료인지 밝혔어요.","듣는 사람은 소식지를 찾아 확인할 수 있어요.","출처는 근거를 믿을 수 있게 해 줘요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관을 점심시간에도 열어야 한다고 생각합니다.","수업이 끝난 뒤에는 도서관에 남아 책을 볼 시간이 있는 학생이 적기 때문입니다.","하교 시간이 되면 대부분 바로 집이나 다른 곳으로 가야 합니다.","우리 학교 도서관에서 조사한 표를 보면, 이용하고 싶은 시간으로","점심시간을 고른 학생이 다른 시간을 고른 학생보다 훨씬 많았습니다.","이웃 학교는 점심시간에 문을 연 뒤로 찾는 학생이 눈에 띄게 늘었다고 합니다.","학교 소식지에 실린 내용입니다.","점심시간에 도서관을 열면 더 많은 학생이 책을 만날 수 있습니다."],"title":"다경이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#4','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',3,'ox','auto','세온이의 발표에 보완할 점이 있으니 세온이의 주장은 틀린 주장이에요.',ARRAY['K6-2-u3-X20']::text[],false,'{"seq":4,"concept":"K6-2-u3-C7","difficulty":3,"kind":"ox","stem":"세온이의 발표에 보완할 점이 있으니 세온이의 주장은 틀린 주장이에요.","answer":"X","reason_options":[{"t":"주장은 학생들에게 도움이 되는 내용이고, 근거를 객관적인 자료로 고치면 되기 때문에","correct":true},{"t":"보완할 점이 하나라도 있으면 주장 전체가 틀린 것이기 때문에","mis":"K6-2-u3-X20"}],"mis":"K6-2-u3-X20","explanation":["새 책을 사자는 주장은 학생들에게 도움이 돼요.","약한 것은 근거예요.","약한 자리를 고치면 더 나아져요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#5','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C5',3,'mc','auto','세온이의 이유가 많은 사람이 받아들이기에 부족한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X06','K6-2-u3-X08','K6-2-u3-X12']::text[],false,'{"seq":5,"concept":"K6-2-u3-C5","difficulty":3,"kind":"mc","stem":"세온이의 이유가 많은 사람이 받아들이기에 부족한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"학생들이 도서관에 오는 까닭은 새 책 말고도 여러 가지여서","correct":true},{"t":"이유가 주장과 관련이 없어서","mis":"K6-2-u3-X06"},{"t":"이유에 숫자가 없어서","mis":"K6-2-u3-X08"},{"t":"이유가 너무 짧아서","mis":"K6-2-u3-X12"}],"explanation":["이유는 주장과 관련은 있어요.","그러나 도서관에 오는 까닭은 여러 가지예요.","그래서 많은 사람이 받아들이기에 부족해요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#6','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',3,'match','auto','세온이의 발표를 평가 기준표 세 항목으로 판단한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C7","difficulty":3,"kind":"match","stem":"세온이의 발표를 평가 기준표 세 항목으로 판단한 내용을 알맞게 이으세요.","pairs":[{"l":"주장은 가치 있고 중요한가","r":"학생들에게 도움이 되는 주장이다"},{"l":"이유는 주장을 뒷받침하는가","r":"관련은 있지만 많은 사람이 받아들이기에 부족하다"},{"l":"근거는 이유를 뒷받침하는가","r":"느낌과 짐작에 머물러 있다"}],"mis":"K6-2-u3-X01","explanation":["주장은 가치 있는 내용이에요.","이유는 관련은 있으나 받아들이기에 부족해요.","근거는 객관적이지 않아요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#7','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C8',3,'error','auto','우리 반 생각 발표회에서 근거를 말했어요. 출처를 밝히지 않은 친구는 누구인가요?',ARRAY['K6-2-u3-X13']::text[],false,'{"seq":7,"concept":"K6-2-u3-C8","difficulty":3,"kind":"error","stem":"우리 반 생각 발표회에서 근거를 말했어요. 출처를 밝히지 않은 친구는 누구인가요?","options":[{"t":"도율 — 「어떤 조사를 보니 대부분 찬성했대요.」","correct":true,"mis_target":"K6-2-u3-X13"},{"t":"채이 — 「우리 학교 보건실에서 지난달에 정리한 기록입니다.」","mis":"K6-2-u3-X13"},{"t":"윤후 — 「우리 반이 지난주에 손을 들어 조사한 결과입니다.」","mis":"K6-2-u3-X13"}],"explanation":["채이와 윤후는 어디에서 언제 나온 자료인지 밝혔어요.","도율의 「어떤 조사」는 어디에서 나왔는지 알 수 없어요.","확인할 길이 없으면 믿기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#8','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',4,'mc','auto','우리 반 생각 발표회를 준비하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X08','K6-2-u3-X12']::text[],false,'{"seq":8,"concept":"K6-2-u3-C7","difficulty":4,"kind":"mc","stem":"우리 반 생각 발표회를 준비하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"고치고 싶은 일 떠올리기 → 주장 정하고 스스로 점검하기 → 이유와 근거 모으기 → 친구 발표를 기준표로 판단하고 까닭 적기","correct":true},{"t":"근거 모으기 → 고치고 싶은 일 떠올리기 → 주장 정하기 → 발표하기","mis":"K6-2-u3-X01"},{"t":"주장 정하기 → 근거 없이 바로 발표하기 → 친구 발표 듣기","mis":"K6-2-u3-X08"},{"t":"고치고 싶은 일 떠올리기 → 주장 정하기 → 이유와 근거 모으기 → 친구 발표에 표시만 하기","mis":"K6-2-u3-X12"}],"explanation":["고칠 일이 있어야 주장이 생겨요.","주장을 정한 뒤 이유와 근거를 모아요.","친구 발표는 기준표로 판단하고 까닭을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#9','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C8',4,'essay','teacher','세온이의 발표를 타당한 점과 보완할 점으로 나누어 평가하고, 근거를 객관적인 자료로 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C8","difficulty":4,"kind":"essay","stem":"세온이의 발표를 타당한 점과 보완할 점으로 나누어 평가하고, 근거를 객관적인 자료로 고쳐 쓰세요.","answer_guide":{"answer":"예: 타당한 점 — 새 책을 사자는 주장은 학생들에게 도움이 되고, 새 책이 많아야 학생들이 온다는 이유는 주장과 관련이 있다. 보완할 점 — 도서관에 오는 까닭은 여러 가지라 이유가 많은 사람이 받아들이기에 부족하고, 근거가 새 책 냄새를 좋아한다는 느낌과 사람이 많아 보였다는 짐작이다. 고친 근거 — 우리 학교 도서관에서 새 책이 들어온 달과 그렇지 않은 달의 대출 수를 견주어 정리한 표를 보여 준다.","scoring_points":["타당한 점을 먼저 썼는가","이유와 근거의 보완할 점을 까닭과 함께 썼는가","확인할 수 있는 자료로 근거를 고치고 출처를 밝혔는가"]},"explanation":["살릴 것을 먼저 찾아요.","고칠 것은 까닭과 함께 써요.","느낌을 확인할 수 있는 자료로 바꾸어요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관에 새 책을 더 많이 사야 한다고 생각합니다.","새 책이 많아야 학생들이 도서관에 오기 때문입니다.","저는 새 책 냄새를 좋아합니다. 새 책이 있으면 도서관에 가고 싶어집니다.","지난달에 도서관에 갔을 때 새로 들어온 책이 놓인 칸에","사람이 많아 보였습니다.","그러니 도서관에 새 책을 더 많이 사 주면 좋겠습니다."],"title":"세온이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L04_challenge#10','kor',6,2,'u3','L04','g6_2_kor_u3_L04_challenge','lesson_challenge','K6-2-u3-C7',4,'essay','teacher','다경이의 발표를 평가 기준표 세 항목(주장 · 이유 · 근거)에 ◎ · ○ · △로 판단하고, 각 판단마다 까닭을 한 문장씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C7","difficulty":4,"kind":"essay","stem":"다경이의 발표를 평가 기준표 세 항목(주장 · 이유 · 근거)에 ◎ · ○ · △로 판단하고, 각 판단마다 까닭을 한 문장씩 쓰세요.","answer_guide":{"answer":"예: 주장 ◎ — 점심시간에 도서관을 열면 더 많은 학생이 책을 만날 수 있어 도움이 되고 학교가 바로 해 볼 수 있다. 이유 ◎ — 수업이 끝난 뒤에는 책을 볼 시간이 있는 학생이 적다는 것은 주장과 이어지고 많은 학생이 겪는 일이다. 근거 ◎ — 학교 도서관에서 조사한 표와 학교 소식지에 실린 이웃 학교 사례로 출처가 밝혀진 객관적인 자료이다.","scoring_points":["세 항목 모두에 판단을 표시했는가","판단마다 기준에 맞는 까닭을 썼는가","근거의 객관성과 출처를 짚었는가"]},"explanation":["표시만 하고 끝내지 않아요.","기준에 대어 까닭을 써요.","다경이는 출처도 밝혔어요."],"asset":{"type":"passage","lines":["저는 우리 학교 도서관을 점심시간에도 열어야 한다고 생각합니다.","수업이 끝난 뒤에는 도서관에 남아 책을 볼 시간이 있는 학생이 적기 때문입니다.","하교 시간이 되면 대부분 바로 집이나 다른 곳으로 가야 합니다.","우리 학교 도서관에서 조사한 표를 보면, 이용하고 싶은 시간으로","점심시간을 고른 학생이 다른 시간을 고른 학생보다 훨씬 많았습니다.","이웃 학교는 점심시간에 문을 연 뒤로 찾는 학생이 눈에 띄게 늘었다고 합니다.","학교 소식지에 실린 내용입니다.","점심시간에 도서관을 열면 더 많은 학생이 책을 만날 수 있습니다."],"title":"다경이의 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#1','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',1,'mc','auto','영상의 주장을 파악할 때 살펴볼 것을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X17','K6-2-u3-X03']::text[],false,'{"seq":1,"concept":"K6-2-u3-C9","difficulty":1,"kind":"mc","stem":"영상의 주장을 파악할 때 살펴볼 것을 바르게 모은 것은 어느 것인가요?","options":[{"t":"제목 · 제시한 자료 · 강조하는 장면이나 표현","correct":true},{"t":"영상 길이 · 나오는 사람 수","mis":"K6-2-u3-X15"},{"t":"배경 음악의 크기 하나만","mis":"K6-2-u3-X17"},{"t":"조회 수 · 댓글 수","mis":"K6-2-u3-X03"}],"explanation":["제목에는 만든 사람의 눈이 담겨요.","자료와 강조된 장면도 함께 보아요.","셋을 합치면 주장이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#2','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',1,'sa','auto','무엇을 하자거나 하지 말자고 설득하는 영상을 「○○하는 영상」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C9","difficulty":1,"kind":"sa","stem":"무엇을 하자거나 하지 말자고 설득하는 영상을 「○○하는 영상」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["주장"],"explanation":["알려 주는 영상은 사실이나 방법을 전해요.","보여 주는 영상은 겪은 일을 담아요.","설득하는 영상은 주장하는 영상이에요."],"mis":"K6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#3','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C10',1,'ox','auto','음악이 커지고 자막이 되풀이될수록 그 영상의 주장은 타당해요.',ARRAY['K6-2-u3-X17']::text[],false,'{"seq":3,"concept":"K6-2-u3-C10","difficulty":1,"kind":"ox","stem":"음악이 커지고 자막이 되풀이될수록 그 영상의 주장은 타당해요.","answer":"X","reason_options":[{"t":"강조는 하고 싶은 말을 알려 줄 뿐 그 말이 타당한지는 알려 주지 못하기 때문에","correct":true},{"t":"강조가 셀수록 만든 사람이 확신하고 있기 때문에","mis":"K6-2-u3-X17"}],"mis":"K6-2-u3-X17","explanation":["강조는 주장을 찾는 실마리예요.","타당한지는 자료로 따로 따져요.","센 강조는 마음을 먼저 움직일 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#4','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',1,'mc','auto','주장을 담은 영상의 제목은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":4,"concept":"K6-2-u3-C9","difficulty":1,"kind":"mc","stem":"주장을 담은 영상의 제목은 어느 것인가요?","options":[{"t":"늦게 자는 습관, 오늘부터 바꿉시다","correct":true},{"t":"우리나라 사람들은 몇 시에 잠들까","mis":"K6-2-u3-X15"},{"t":"하루 동안 낮잠을 자 본 결과","mis":"K6-2-u3-X15"},{"t":"잠에 대한 열 가지 사실","mis":"K6-2-u3-X15"}],"explanation":["「바꿉시다」는 무엇을 하라고 이끄는 말이에요.","「몇 시에 잠들까」·「열 가지 사실」은 알려 주는 제목이에요.","「자 본 결과」는 겪은 일을 보여 주는 제목이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#5','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',2,'mc','auto','영상 「걸으면 보이는 것」의 주장은 무엇인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":5,"concept":"K6-2-u3-C9","difficulty":2,"kind":"mc","stem":"영상 「걸으면 보이는 것」의 주장은 무엇인가요?","options":[{"t":"가까운 곳은 걸어서 다니자","correct":true},{"t":"동네에 나무를 더 심자","mis":"K6-2-u3-X15"},{"t":"날마다 오래 달리기를 하자","mis":"K6-2-u3-X15"},{"t":"차를 타면 빨리 갈 수 있다","mis":"K6-2-u3-X15"}],"explanation":["제목은 걸을 때만 보이는 것이 있다고 말해요.","조사 화면은 가까운 길도 차로 다니는 문제를 보여 줘요.","마지막 자막이 「가까운 길은, 걸어서」예요."],"asset":{"type":"passage","lines":["장면 1 — 차 안에서 찍은 창밖. 가게와 나무가 흐릿하게 흘러간다. 자막 「빠르게」","장면 2 — 같은 길을 걷는 발. 간판과 벽의 그림이 또렷하다. 자막 「천천히」","장면 3 — 가까운 거리도 차로 다닌다고 답한 사람이 절반이 넘는다는 조사 화면","장면 4 — 걸어 다니는 사람이 늘어난 동네. 작은 가게 앞에서 인사를 나눈다.","장면 5 — 음악이 멈추고 검은 바탕에 글자만 남는다. 「가까운 길은, 걸어서」"],"title":"영상 「걸으면 보이는 것」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#6','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',2,'match','auto','영상의 요소와 그 요소를 볼 때 던질 물음을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C9","difficulty":2,"kind":"match","stem":"영상의 요소와 그 요소를 볼 때 던질 물음을 알맞게 이으세요.","pairs":[{"l":"제목","r":"왜 이렇게 이름을 붙였을까"},{"l":"제시한 자료","r":"무엇을 보여 주려고 이 자료를 넣었을까"},{"l":"강조하는 장면이나 표현","r":"왜 하필 여기에서 크게 · 되풀이해서 보여 줄까"}],"mis":"K6-2-u3-X15","explanation":["제목에는 이름을 붙인 까닭을 물어요.","자료에는 넣은 까닭을 물어요.","강조에는 그 자리를 고른 까닭을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#7','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',2,'mc','auto','「걸으면 보이는 것」에 장면 3의 조사 화면을 넣은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":7,"concept":"K6-2-u3-C9","difficulty":2,"kind":"mc","stem":"「걸으면 보이는 것」에 장면 3의 조사 화면을 넣은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가까운 거리도 차로 다니는 문제가 실제로 있다는 것을 보여 주려고","correct":true},{"t":"도시가 얼마나 큰지 알려 주려고","mis":"K6-2-u3-X15"},{"t":"차가 편하다는 것을 알리려고","mis":"K6-2-u3-X15"},{"t":"영상을 길게 만들려고","mis":"K6-2-u3-X15"}],"explanation":["자료를 넣은 자리에는 까닭이 있어요.","조사 화면은 문제가 있다는 것을 보여 줘요.","장면 4는 바꾸면 좋아진다는 것을 보여 줘요."],"asset":{"type":"passage","lines":["장면 1 — 차 안에서 찍은 창밖. 가게와 나무가 흐릿하게 흘러간다. 자막 「빠르게」","장면 2 — 같은 길을 걷는 발. 간판과 벽의 그림이 또렷하다. 자막 「천천히」","장면 3 — 가까운 거리도 차로 다닌다고 답한 사람이 절반이 넘는다는 조사 화면","장면 4 — 걸어 다니는 사람이 늘어난 동네. 작은 가게 앞에서 인사를 나눈다.","장면 5 — 음악이 멈추고 검은 바탕에 글자만 남는다. 「가까운 길은, 걸어서」"],"title":"영상 「걸으면 보이는 것」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#8','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C9',2,'ox','auto','영상은 대부분 「저는 ~해야 한다고 생각합니다.」처럼 주장을 직접 말해요.',ARRAY['K6-2-u3-X16']::text[],false,'{"seq":8,"concept":"K6-2-u3-C9","difficulty":2,"kind":"ox","stem":"영상은 대부분 「저는 ~해야 한다고 생각합니다.」처럼 주장을 직접 말해요.","answer":"X","reason_options":[{"t":"자료와 장면을 보여 주고 보는 사람이 스스로 알아채게 만드는 경우가 많기 때문에","correct":true},{"t":"영상도 주장하는 말처럼 주장을 문장으로 밝히기 때문에","mis":"K6-2-u3-X16"}],"mis":"K6-2-u3-X16","explanation":["영상은 주장을 말로 밝히지 않는 경우가 많아요.","자료와 장면을 이어 붙여 알아채게 해요.","「그래서 나더러 무엇을 하라는 걸까」를 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#9','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C10',2,'mc','auto','영상을 바르게 보는 태도로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X22','K6-2-u3-X17','K6-2-u3-X12']::text[],false,'{"seq":9,"concept":"K6-2-u3-C10","difficulty":2,"kind":"mc","stem":"영상을 바르게 보는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"처음에는 끝까지 한 번 보고, 두 번째에는 제목 · 자료 · 강조된 표현을 적으며 본다","correct":true},{"t":"처음부터 장면마다 멈추며 마음에 드는 것만 본다","mis":"K6-2-u3-X22"},{"t":"음악이 좋은 부분만 골라 본다","mis":"K6-2-u3-X17"},{"t":"보고 나서 느낌만 말한다","mis":"K6-2-u3-X12"}],"explanation":["처음에는 멈추지 않고 끝까지 보아요.","두 번째에 적으며 보아요.","본 뒤에는 알아낸 것과 궁금한 것을 나누어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_basic#10','kor',6,2,'u3','L07','g6_2_kor_u3_L07_basic','lesson_basic','K6-2-u3-C10',3,'error','auto','「멈추면 들리는 소리」를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X15']::text[],false,'{"seq":10,"concept":"K6-2-u3-C10","difficulty":3,"kind":"error","stem":"「멈추면 들리는 소리」를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소율 — 「마지막에 음악이 멈추고 자막만 남으니, 이 주장은 틀림없이 옳아.」","correct":true,"mis_target":"K6-2-u3-X17"},{"t":"하준 — 「자막 ‘끄면’이 되풀이되며 커지는 걸 보니, 화면을 끄라는 말이 하고 싶은 거야.」","mis":"K6-2-u3-X15"},{"t":"지안 — 「주장을 찾았으니 이제 타당한지는 자료로 따져 봐야 해.」","mis":"K6-2-u3-X17"}],"explanation":["하준은 강조를 주장을 찾는 실마리로 썼어요.","지안은 찾는 일과 따지는 일을 갈랐어요.","소율은 강조를 타당성으로 여겼어요."],"asset":{"type":"passage","lines":["장면 1 — 방 안에 켜진 화면 여러 개. 소리가 겹쳐 무엇인지 알기 어렵다.","장면 2 — 손이 화면을 하나씩 끈다. 끌 때마다 자막 「끄면」이 커진다.","장면 3 — 새소리 · 빗소리 · 계단을 오르는 발소리를 그림으로 보여 준다.","장면 4 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면","장면 5 — 음악이 멈추고 자막만 남는다. 「멈추면, 들립니다」"],"title":"영상 「멈추면 들리는 소리」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#1','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',2,'sa','auto','「걸으면 보이는 것」 마지막 화면에 글자만 남은 자막은 「○○○ 길은, 걸어서」예요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C9","difficulty":2,"kind":"sa","stem":"「걸으면 보이는 것」 마지막 화면에 글자만 남은 자막은 「○○○ 길은, 걸어서」예요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["가까운"],"explanation":["마지막에 음악이 멈춰요.","검은 바탕에 글자만 남아요.","가장 하고 싶은 말을 마지막에 크게 두었어요."],"asset":{"type":"passage","lines":["장면 1 — 차 안에서 찍은 창밖. 가게와 나무가 흐릿하게 흘러간다. 자막 「빠르게」","장면 2 — 같은 길을 걷는 발. 간판과 벽의 그림이 또렷하다. 자막 「천천히」","장면 3 — 가까운 거리도 차로 다닌다고 답한 사람이 절반이 넘는다는 조사 화면","장면 4 — 걸어 다니는 사람이 늘어난 동네. 작은 가게 앞에서 인사를 나눈다.","장면 5 — 음악이 멈추고 검은 바탕에 글자만 남는다. 「가까운 길은, 걸어서」"],"title":"영상 「걸으면 보이는 것」의 장면"},"mis":"K6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#2','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C10',2,'mc','auto','강조하는 장면이나 표현이 알려 주는 것은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X03']::text[],false,'{"seq":2,"concept":"K6-2-u3-C10","difficulty":2,"kind":"mc","stem":"강조하는 장면이나 표현이 알려 주는 것은 어느 것인가요?","options":[{"t":"만든 사람이 무엇을 가장 하고 싶은 말로 여기는지","correct":true},{"t":"그 말이 사실인지","mis":"K6-2-u3-X17"},{"t":"그 말이 타당한지","mis":"K6-2-u3-X17"},{"t":"영상이 얼마나 인기 있는지","mis":"K6-2-u3-X03"}],"explanation":["강조는 하고 싶은 말을 가리켜요.","사실인지·타당한지는 알려 주지 못해요.","그것은 자료로 따로 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#3','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',3,'mc','auto','제목을 「걷기의 좋은 점 세 가지」가 아니라 「걸으면 보이는 것」으로 정했을 때 달라지는 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":3,"concept":"K6-2-u3-C9","difficulty":3,"kind":"mc","stem":"제목을 「걷기의 좋은 점 세 가지」가 아니라 「걸으면 보이는 것」으로 정했을 때 달라지는 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"알려 주는 영상이 아니라, 차로 지나갈 때는 못 보던 것이 있다는 생각을 먼저 심어 준다","correct":true},{"t":"달라지는 것이 없다 — 제목은 주장과 관계없다","mis":"K6-2-u3-X15"},{"t":"걷기에 대한 사실만 알려 주게 된다","mis":"K6-2-u3-X15"},{"t":"영상이 더 짧아진다","mis":"K6-2-u3-X15"}],"explanation":["「좋은 점 세 가지」는 알려 주는 제목처럼 보여요.","「걸으면 보이는 것」은 생각을 먼저 심어요.","제목의 낱말 하나에 만든 사람의 눈이 담겨요."],"asset":{"type":"passage","lines":["장면 1 — 차 안에서 찍은 창밖. 가게와 나무가 흐릿하게 흘러간다. 자막 「빠르게」","장면 2 — 같은 길을 걷는 발. 간판과 벽의 그림이 또렷하다. 자막 「천천히」","장면 3 — 가까운 거리도 차로 다닌다고 답한 사람이 절반이 넘는다는 조사 화면","장면 4 — 걸어 다니는 사람이 늘어난 동네. 작은 가게 앞에서 인사를 나눈다.","장면 5 — 음악이 멈추고 검은 바탕에 글자만 남는다. 「가까운 길은, 걸어서」"],"title":"영상 「걸으면 보이는 것」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#4','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',3,'mc','auto','「멈추면 들리는 소리」의 주장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":4,"concept":"K6-2-u3-C9","difficulty":3,"kind":"mc","stem":"「멈추면 들리는 소리」의 주장으로 알맞은 것은 어느 것인가요?","options":[{"t":"켜 둔 화면을 끄고 멈추어 주변의 소리를 들어 보자","correct":true},{"t":"방 안에 화면을 여러 개 켜 두자","mis":"K6-2-u3-X15"},{"t":"집에서 새를 기르자","mis":"K6-2-u3-X15"},{"t":"비 오는 날에는 밖에 나가지 말자","mis":"K6-2-u3-X15"}],"explanation":["「끄면」이 되풀이되며 커져요.","새소리·빗소리는 끄면 들리는 소리예요.","마지막 자막이 「멈추면, 들립니다」예요."],"asset":{"type":"passage","lines":["장면 1 — 방 안에 켜진 화면 여러 개. 소리가 겹쳐 무엇인지 알기 어렵다.","장면 2 — 손이 화면을 하나씩 끈다. 끌 때마다 자막 「끄면」이 커진다.","장면 3 — 새소리 · 빗소리 · 계단을 오르는 발소리를 그림으로 보여 준다.","장면 4 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면","장면 5 — 음악이 멈추고 자막만 남는다. 「멈추면, 들립니다」"],"title":"영상 「멈추면 들리는 소리」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#5','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',3,'match','auto','「멈추면 들리는 소리」에서 영상의 요소와 그에 해당하는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u3-C9","difficulty":3,"kind":"match","stem":"「멈추면 들리는 소리」에서 영상의 요소와 그에 해당하는 것을 알맞게 이으세요.","pairs":[{"l":"제목","r":"멈추면 들리는 소리"},{"l":"제시한 자료","r":"십 분씩 소리를 들어 본 사람들이 겪은 일"},{"l":"강조하는 표현","r":"되풀이되며 커지는 자막 「끄면」"}],"mis":"K6-2-u3-X15","explanation":["제목은 영상의 이름이에요.","사람들이 겪은 일은 자료예요.","되풀이되며 커지는 자막은 강조예요."],"asset":{"type":"passage","lines":["장면 1 — 방 안에 켜진 화면 여러 개. 소리가 겹쳐 무엇인지 알기 어렵다.","장면 2 — 손이 화면을 하나씩 끈다. 끌 때마다 자막 「끄면」이 커진다.","장면 3 — 새소리 · 빗소리 · 계단을 오르는 발소리를 그림으로 보여 준다.","장면 4 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면","장면 5 — 음악이 멈추고 자막만 남는다. 「멈추면, 들립니다」"],"title":"영상 「멈추면 들리는 소리」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#6','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',3,'ox','auto','「멈추면 들리는 소리」의 주장을 파악하는 데 영상에 나오는 방의 벽 색깔이 도움이 돼요.',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":6,"concept":"K6-2-u3-C9","difficulty":3,"kind":"ox","stem":"「멈추면 들리는 소리」의 주장을 파악하는 데 영상에 나오는 방의 벽 색깔이 도움이 돼요.","answer":"X","reason_options":[{"t":"제목 · 자료 · 강조하는 장면이나 표현 세 갈래에 들지 않기 때문에","correct":true},{"t":"영상에 나오는 것은 모두 주장을 알려 주기 때문에","mis":"K6-2-u3-X15"}],"mis":"K6-2-u3-X15","explanation":["주장을 찾는 실마리는 세 갈래예요.","벽 색깔이나 영상 길이는 들지 않아요.","세 갈래만 모아 한 문장으로 만들어요."],"asset":{"type":"passage","lines":["장면 1 — 방 안에 켜진 화면 여러 개. 소리가 겹쳐 무엇인지 알기 어렵다.","장면 2 — 손이 화면을 하나씩 끈다. 끌 때마다 자막 「끄면」이 커진다.","장면 3 — 새소리 · 빗소리 · 계단을 오르는 발소리를 그림으로 보여 준다.","장면 4 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면","장면 5 — 음악이 멈추고 자막만 남는다. 「멈추면, 들립니다」"],"title":"영상 「멈추면 들리는 소리」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#7','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',3,'error','auto','영상의 주장을 파악하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X16']::text[],false,'{"seq":7,"concept":"K6-2-u3-C9","difficulty":3,"kind":"error","stem":"영상의 주장을 파악하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「제목만 보면 주장을 알 수 있으니 영상은 안 봐도 돼.」","correct":true,"mis_target":"K6-2-u3-X15"},{"t":"다인 — 「제목 · 자료 · 강조된 표현을 합쳐 한 문장으로 만들어.」","mis":"K6-2-u3-X15"},{"t":"루아 — 「‘그래서 나더러 무엇을 하라는 걸까’를 스스로 물어 봐.」","mis":"K6-2-u3-X16"}],"explanation":["다인은 세 갈래를 합쳤어요.","루아는 스스로 묻는 방법을 말했어요.","태오는 한 갈래만 보았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#8','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C10',4,'mc','auto','「주장을 찾는 일」과 「주장이 타당한지 따지는 일」을 바르게 설명한 것은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X16']::text[],false,'{"seq":8,"concept":"K6-2-u3-C10","difficulty":4,"kind":"mc","stem":"「주장을 찾는 일」과 「주장이 타당한지 따지는 일」을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"강조된 장면은 주장을 찾는 실마리가 되고, 타당한지는 자료가 이유를 뒷받침하는지로 따로 따진다","correct":true},{"t":"두 일은 같다 — 강조가 센 주장이 타당하다","mis":"K6-2-u3-X17"},{"t":"강조된 장면이 없으면 주장도 없다","mis":"K6-2-u3-X16"},{"t":"타당한지는 음악과 자막의 세기로 잰다","mis":"K6-2-u3-X17"}],"explanation":["찾는 일은 제목·자료·강조로 해요.","따지는 일은 세 기준으로 해요.","강조의 세기와 타당성은 아무 관계가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#9','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C9',4,'essay','teacher','「멈추면 들리는 소리」에서 제목 · 제시한 자료 · 강조하는 표현을 하나씩 찾아 쓰고, 셋을 합쳐 이 영상의 주장을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C9","difficulty":4,"kind":"essay","stem":"「멈추면 들리는 소리」에서 제목 · 제시한 자료 · 강조하는 표현을 하나씩 찾아 쓰고, 셋을 합쳐 이 영상의 주장을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 제목 — 「멈추면 들리는 소리」로, 멈추어야 들리는 것이 있다는 생각을 심어 준다. 자료 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면이다. 강조 — 화면을 끌 때마다 커지는 자막 「끄면」과, 음악이 멈추고 남는 자막 「멈추면, 들립니다」이다. 주장 — 켜 둔 화면을 끄고 잠깐 멈추어 주변의 소리를 들어 보자.","scoring_points":["제목·자료·강조하는 표현을 하나씩 바르게 찾았는가","셋을 합쳐 주장을 한 문장으로 썼는가","주장이 무엇을 하자는 말로 되어 있는가"]},"explanation":["세 갈래를 하나씩 찾아요.","따로 보면 흩어져 보여요.","합치면 한 문장이 돼요."],"asset":{"type":"passage","lines":["장면 1 — 방 안에 켜진 화면 여러 개. 소리가 겹쳐 무엇인지 알기 어렵다.","장면 2 — 손이 화면을 하나씩 끈다. 끌 때마다 자막 「끄면」이 커진다.","장면 3 — 새소리 · 빗소리 · 계단을 오르는 발소리를 그림으로 보여 준다.","장면 4 — 하루에 십 분씩 소리를 들어 본 사람들이 겪은 일을 옮긴 화면","장면 5 — 음악이 멈추고 자막만 남는다. 「멈추면, 들립니다」"],"title":"영상 「멈추면 들리는 소리」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L07_challenge#10','kor',6,2,'u3','L07','g6_2_kor_u3_L07_challenge','lesson_challenge','K6-2-u3-C10',4,'essay','teacher','「강조가 세다고 주장이 타당한 것은 아니다.」라는 말을 「걸으면 보이는 것」의 장면을 들어 설명하세요. 강조가 알려 주는 것과 알려 주지 못하는 것을 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C10","difficulty":4,"kind":"essay","stem":"「강조가 세다고 주장이 타당한 것은 아니다.」라는 말을 「걸으면 보이는 것」의 장면을 들어 설명하세요. 강조가 알려 주는 것과 알려 주지 못하는 것을 함께 쓰세요.","answer_guide":{"answer":"예: 장면 5에서 음악이 멈추고 「가까운 길은, 걸어서」만 남는다. 이 강조는 만든 사람이 「가까운 곳은 걸어서 다니자」를 가장 하고 싶은 말로 여긴다는 것을 알려 준다. 그러나 이 주장이 타당한지는 알려 주지 못한다. 타당한지는 장면 3의 조사 화면이 믿을 만한 자료인지, 그 자료가 이유를 뒷받침하는지를 따져 보아야 알 수 있다.","scoring_points":["영상의 강조된 장면을 들었는가","강조가 알려 주는 것(하고 싶은 말)을 썼는가","강조가 알려 주지 못하는 것(타당성)과 따지는 방법을 썼는가"]},"explanation":["강조는 「무엇을」 말하고 싶은지 알려 줘요.","「옳은지」는 알려 주지 못해요.","타당성은 자료로 따져요."],"asset":{"type":"passage","lines":["장면 1 — 차 안에서 찍은 창밖. 가게와 나무가 흐릿하게 흘러간다. 자막 「빠르게」","장면 2 — 같은 길을 걷는 발. 간판과 벽의 그림이 또렷하다. 자막 「천천히」","장면 3 — 가까운 거리도 차로 다닌다고 답한 사람이 절반이 넘는다는 조사 화면","장면 4 — 걸어 다니는 사람이 늘어난 동네. 작은 가게 앞에서 인사를 나눈다.","장면 5 — 음악이 멈추고 검은 바탕에 글자만 남는다. 「가까운 길은, 걸어서」"],"title":"영상 「걸으면 보이는 것」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#1','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',1,'mc','auto','카드 뉴스를 볼 때 알맞은 태도는 어느 것인가요?',ARRAY['K6-2-u3-X03','K6-2-u3-X02']::text[],false,'{"seq":1,"concept":"K6-2-u3-C11","difficulty":1,"kind":"mc","stem":"카드 뉴스를 볼 때 알맞은 태도는 어느 것인가요?","options":[{"t":"주장하는 내용이 있다면 그 타당성을 평가하며 본다","correct":true},{"t":"그림이 예쁜지만 보고 넘긴다","mis":"K6-2-u3-X03"},{"t":"카드 뉴스는 짧으니 믿지 않고 넘긴다","mis":"K6-2-u3-X02"},{"t":"장 수가 많으면 그대로 믿는다","mis":"K6-2-u3-X03"}],"explanation":["카드 뉴스도 주장을 담아요.","그림이 보기 좋은 것과 내용이 타당한 것은 달라요.","믿거나 안 믿거나가 아니라 따져 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#2','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',1,'sa','auto','카드 뉴스 「밤이 너무 밝습니다」의 주장은 「필요 없는 밤 ○○을 줄입시다.」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C11","difficulty":1,"kind":"sa","stem":"카드 뉴스 「밤이 너무 밝습니다」의 주장은 「필요 없는 밤 ○○을 줄입시다.」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["불빛"],"explanation":["주장은 첫째 장에 있어요.","제목과 굵은 글씨를 보아요.","「필요 없는 밤 불빛을 줄입시다」예요."],"asset":{"type":"passage","lines":["첫째 장 — 밤이 너무 밝습니다. 필요 없는 밤 불빛을 줄입시다.","둘째 장 — 밤 불빛은 해가 진 뒤에 사람이 켜 두는 빛입니다.","가로등, 가게 간판, 건물 안팎의 불빛이 모두 여기에 듭니다.","꼭 있어야 하는 빛도 있지만, 아무도 쓰지 않는데 켜져 있는 빛도 있습니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 첫째 · 둘째 장"},"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#3','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',1,'ox','auto','카드 뉴스는 글이 짧으니 따져 볼 것이 적어요.',ARRAY['K6-2-u3-X03']::text[],false,'{"seq":3,"concept":"K6-2-u3-C11","difficulty":1,"kind":"ox","stem":"카드 뉴스는 글이 짧으니 따져 볼 것이 적어요.","answer":"X","reason_options":[{"t":"짧을수록 빠진 것이 잘 보이지 않아 오히려 따져 볼 것이 많기 때문에","correct":true},{"t":"짧은 글에는 주장 · 이유 · 근거가 들어가지 않기 때문에","mis":"K6-2-u3-X03"}],"mis":"K6-2-u3-X03","explanation":["카드 뉴스는 핵심만 빠르게 전해요.","짧으면 빠진 것이 눈에 잘 띄지 않아요.","그래서 더 따져 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#4','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',1,'mc','auto','카드 뉴스에서 주장이 대개 들어 있는 자리는 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X03']::text[],false,'{"seq":4,"concept":"K6-2-u3-C11","difficulty":1,"kind":"mc","stem":"카드 뉴스에서 주장이 대개 들어 있는 자리는 어느 것인가요?","options":[{"t":"첫 장의 제목과 굵은 글씨","correct":true},{"t":"마지막 장의 그림","mis":"K6-2-u3-X01"},{"t":"가운데 장의 근거","mis":"K6-2-u3-X01"},{"t":"카드 뉴스에는 주장이 없다","mis":"K6-2-u3-X03"}],"explanation":["첫 장에 제목과 주장이 들어가요.","가운데 장에는 이유와 근거가 한 쌍씩 놓여요.","주장은 첫 장부터 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#5','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',2,'match','auto','「밤이 너무 밝습니다」에서 각 이유와 그 이유를 받쳐 준 근거를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u3-C11","difficulty":2,"kind":"match","stem":"「밤이 너무 밝습니다」에서 각 이유와 그 이유를 받쳐 준 근거를 알맞게 이으세요.","pairs":[{"l":"① 잠을 방해한다","r":"잠드는 데 걸리는 시간이 길어진다는 연구 결과"},{"l":"② 해마다 늘고 있다","r":"밤 밝기를 해마다 조사한 그래프"},{"l":"③ 곤충과 새의 생활을 어지럽힌다","r":"지나친 빛을 막기 위한 우리나라의 제도"}],"mis":"K6-2-u3-X01","explanation":["같은 장에 함께 놓인 것끼리 이어요.","이유와 근거를 한 쌍씩 갈라내요.","그래야 하나씩 따져 볼 수 있어요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#6','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',2,'mc','auto','「필요 없는 밤 불빛을 줄입시다」가 가치 있고 중요한 주장인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X03','K6-2-u3-X07']::text[],false,'{"seq":6,"concept":"K6-2-u3-C11","difficulty":2,"kind":"mc","stem":"「필요 없는 밤 불빛을 줄입시다」가 가치 있고 중요한 주장인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사람의 잠과 주변 생물의 생활과 이어져 있고, 불빛 하나를 끄는 일은 오늘 바로 할 수 있어서","correct":true},{"t":"카드 뉴스의 그림이 보기 좋아서","mis":"K6-2-u3-X03"},{"t":"카드가 모두 여섯 장이어서","mis":"K6-2-u3-X03"},{"t":"밤이 무섭다는 사람이 많아서","mis":"K6-2-u3-X07"}],"explanation":["문제 해결에 도움이 되는지 보아요.","실천 가능한지 보아요.","그림이나 장 수는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#7','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C12',2,'mc','auto','「밤이 너무 밝습니다」에서 주장을 뒷받침하는 힘이 가장 약한 이유는 어느 것인가요?',ARRAY['K6-2-u3-X18','K6-2-u3-X02']::text[],false,'{"seq":7,"concept":"K6-2-u3-C12","difficulty":2,"kind":"mc","stem":"「밤이 너무 밝습니다」에서 주장을 뒷받침하는 힘이 가장 약한 이유는 어느 것인가요?","options":[{"t":"밤에 켜 두는 불빛이 해마다 늘고 있기 때문이다","correct":true},{"t":"지나친 밤 불빛은 잠을 방해하기 때문이다","mis":"K6-2-u3-X18"},{"t":"곤충과 새의 생활을 어지럽히기 때문이다","mis":"K6-2-u3-X18"},{"t":"세 이유가 모두 똑같이 약하다","mis":"K6-2-u3-X02"}],"explanation":["세 이유에 「그래서 왜 줄여야 하는데?」를 물어요.","①과 ③은 무엇이 나빠지는지 말해요.","②는 얼마나 많은지만 말해요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#8','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C12',2,'ox','auto','이유 하나와 근거 하나가 약하니 「밤 불빛을 줄이자」는 틀린 주장이에요.',ARRAY['K6-2-u3-X20']::text[],false,'{"seq":8,"concept":"K6-2-u3-C12","difficulty":2,"kind":"ox","stem":"이유 하나와 근거 하나가 약하니 「밤 불빛을 줄이자」는 틀린 주장이에요.","answer":"X","reason_options":[{"t":"주장은 가치 있고 튼튼한 근거도 있어, 약한 자리만 고치면 되기 때문에","correct":true},{"t":"약한 데가 하나라도 있으면 그 카드 뉴스는 믿을 수 없기 때문에","mis":"K6-2-u3-X20"}],"mis":"K6-2-u3-X20","explanation":["주장은 가치 있고 실천 가능해요.","근거 ①과 ②는 확인할 수 있는 자료예요.","약한 자리는 고칠 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#9','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C11',2,'mc','auto','카드 뉴스의 이유마다 던져 보면 좋은 물음은 어느 것인가요?',ARRAY['K6-2-u3-X12','K6-2-u3-X03']::text[],false,'{"seq":9,"concept":"K6-2-u3-C11","difficulty":2,"kind":"mc","stem":"카드 뉴스의 이유마다 던져 보면 좋은 물음은 어느 것인가요?","options":[{"t":"「그래서 왜 그래야 하는데?」","correct":true},{"t":"「이 이유는 몇 글자일까?」","mis":"K6-2-u3-X12"},{"t":"「이 이유를 쓴 사람은 유명할까?」","mis":"K6-2-u3-X03"},{"t":"「이 이유 옆에 그림이 있을까?」","mis":"K6-2-u3-X03"}],"explanation":["이유는 주장의 까닭을 말해야 해요.","「그래서 왜?」에 답하는지 보아요.","글자 수나 그림은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_basic#10','kor',6,2,'u3','L09','g6_2_kor_u3_L09_basic','lesson_basic','K6-2-u3-C12',3,'mc','auto','근거 ③이 이유 ③을 뒷받침하지 못하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X19','K6-2-u3-X08']::text[],false,'{"seq":10,"concept":"K6-2-u3-C12","difficulty":3,"kind":"mc","stem":"근거 ③이 이유 ③을 뒷받침하지 못하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"제도는 문제에 대한 해결 방안이지 생활이 어지럽혀진다는 것을 보여 주지 못해서","correct":true},{"t":"제도라는 낱말이 어려워서","mis":"K6-2-u3-X19"},{"t":"우리나라만 다루고 다른 나라는 다루지 않아서","mis":"K6-2-u3-X19"},{"t":"근거는 많을수록 좋은데 하나뿐이어서","mis":"K6-2-u3-X08"}],"explanation":["이유 ③은 「생활을 어지럽힌다」예요.","근거 ③은 그 뒤에 나선 해결 방안이에요.","이유를 보여 주는 자료가 아니에요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#1','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',2,'sa','auto','이유 ②는 밤 불빛이 얼마나 많은지, 곧 문제의 ○○만 말해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C12","difficulty":2,"kind":"sa","stem":"이유 ②는 밤 불빛이 얼마나 많은지, 곧 문제의 ○○만 말해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["규모"],"explanation":["규모는 일이 벌어진 크기나 범위예요.","많다는 것만으로는 나쁜 것이 되지 않아요.","무엇이 어떻게 나빠지는지까지 말해야 해요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"},"mis":"K6-2-u3-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#2','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C11',2,'mc','auto','카드 뉴스의 근거마다 던져 보면 좋은 물음은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X17','K6-2-u3-X01']::text[],false,'{"seq":2,"concept":"K6-2-u3-C11","difficulty":2,"kind":"mc","stem":"카드 뉴스의 근거마다 던져 보면 좋은 물음은 어느 것인가요?","options":[{"t":"「이게 그 이유를 보여 주나?」","correct":true},{"t":"「이 근거는 길까?」","mis":"K6-2-u3-X08"},{"t":"「이 근거가 마음을 세게 움직이나?」","mis":"K6-2-u3-X17"},{"t":"「이 근거는 몇 번째 장에 있나?」","mis":"K6-2-u3-X01"}],"explanation":["근거는 이유를 받쳐 주어야 해요.","그 이유를 정말 보여 주는지 물어요.","길이나 마음의 세기는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#3','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',3,'mc','auto','이유 ②를 주장을 뒷받침하는 이유로 고친 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X18','K6-2-u3-X01','K6-2-u3-X07']::text[],false,'{"seq":3,"concept":"K6-2-u3-C12","difficulty":3,"kind":"mc","stem":"이유 ②를 주장을 뒷받침하는 이유로 고친 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"늘어난 밤 불빛 때문에 잠을 설치거나 생활이 어지럽혀지는 생물이 함께 늘기 때문이다","correct":true},{"t":"밤 불빛이 아주아주 많이 늘고 있기 때문이다","mis":"K6-2-u3-X18"},{"t":"밤 불빛이 늘고 있다는 그래프가 있기 때문이다","mis":"K6-2-u3-X01"},{"t":"밤 불빛이 늘어서 속상하기 때문이다","mis":"K6-2-u3-X07"}],"explanation":["늘고 있다는 것은 규모예요.","늘어서 무엇이 나빠지는지 말해야 이유가 서요.","더 크게 말하거나 근거를 이유 자리에 넣으면 안 돼요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#4','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',3,'mc','auto','근거 ③ 대신 이유 ③을 뒷받침할 근거로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X19','K6-2-u3-X08']::text[],false,'{"seq":4,"concept":"K6-2-u3-C12","difficulty":3,"kind":"mc","stem":"근거 ③ 대신 이유 ③을 뒷받침할 근거로 알맞은 것은 어느 것인가요?","options":[{"t":"밤 불빛 둘레에 곤충이 모여들어 맴도는 모습을 관찰한 기록","correct":true},{"t":"지나친 빛을 막는 다른 나라의 규칙","mis":"K6-2-u3-X19"},{"t":"밤 불빛을 줄이자는 행사 소식","mis":"K6-2-u3-X19"},{"t":"나는 밤에 새소리를 좋아한다는 말","mis":"K6-2-u3-X08"}],"explanation":["이유 ③은 생활이 어지럽혀진다는 것이에요.","그 모습을 보여 주는 관찰 기록이 근거가 돼요.","규칙이나 행사는 해결 방안이에요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#5','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C11',3,'ox','auto','카드 뉴스를 평가할 때에는 약한 자리부터 찾아야 해요.',ARRAY['K6-2-u3-X11']::text[],false,'{"seq":5,"concept":"K6-2-u3-C11","difficulty":3,"kind":"ox","stem":"카드 뉴스를 평가할 때에는 약한 자리부터 찾아야 해요.","answer":"X","reason_options":[{"t":"잘 세워진 자리를 먼저 세고 나서 약한 자리를 찾아야 무엇을 살리고 고칠지 보이기 때문에","correct":true},{"t":"평가는 고칠 곳을 찾는 일이니 약한 곳부터 찾아야 하기 때문에","mis":"K6-2-u3-X11"}],"mis":"K6-2-u3-X11","explanation":["이 카드 뉴스에는 잘 세워진 자리가 더 많아요.","그것부터 세요.","그다음 약한 자리를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#6','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',3,'match','auto','「밤이 너무 밝습니다」의 자리와 그 자리를 판단한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C12","difficulty":3,"kind":"match","stem":"「밤이 너무 밝습니다」의 자리와 그 자리를 판단한 내용을 알맞게 이으세요.","pairs":[{"l":"주장","r":"가치 있고 실천 가능하다"},{"l":"이유 ②","r":"문제의 규모만 말해 힘이 약하다"},{"l":"근거 ③","r":"해결 방안이라 이유를 보여 주지 못한다"},{"l":"근거 ①","r":"확인할 수 있는 자료로 이유를 잘 받쳐 준다"}],"mis":"K6-2-u3-X18","explanation":["주장과 근거 ①은 튼튼해요.","이유 ②는 규모만 말해요.","근거 ③은 해결 방안이에요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#7','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',3,'error','auto','「밤이 너무 밝습니다」를 평가한 말이에요. 지나치게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X20','K6-2-u3-X11']::text[],false,'{"seq":7,"concept":"K6-2-u3-C12","difficulty":3,"kind":"error","stem":"「밤이 너무 밝습니다」를 평가한 말이에요. 지나치게 말한 친구는 누구인가요?","options":[{"t":"서아 — 「약한 데가 있으니 이 카드 뉴스는 믿을 수 없어.」","correct":true,"mis_target":"K6-2-u3-X20"},{"t":"하랑 — 「주장은 가치 있고 근거 두 개는 튼튼해. 다만 이유 ②와 근거 ③은 고치면 좋겠어.」","mis":"K6-2-u3-X20"},{"t":"주원 — 「이유 ①과 ③은 왜 줄여야 하는지를 곧바로 말해 줘.」","mis":"K6-2-u3-X11"}],"explanation":["하랑은 타당한 점과 고칠 자리를 함께 말했어요.","주원은 잘 세워진 자리를 짚었어요.","서아는 하나가 약하다고 전체를 버렸어요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#8','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',4,'mc','auto','이유 ②와 근거 ③의 약한 점을 바르게 가른 것은 어느 것인가요?',ARRAY['K6-2-u3-X19','K6-2-u3-X08','K6-2-u3-X02']::text[],false,'{"seq":8,"concept":"K6-2-u3-C12","difficulty":4,"kind":"mc","stem":"이유 ②와 근거 ③의 약한 점을 바르게 가른 것은 어느 것인가요?","options":[{"t":"이유 ②는 문제의 규모만 말하고 까닭을 말하지 않으며, 근거 ③은 이유를 보여 주지 않고 해결 방안을 말한다","correct":true},{"t":"이유 ②는 해결 방안을 말하고, 근거 ③은 문제의 규모를 말한다","mis":"K6-2-u3-X19"},{"t":"둘 다 말한 사람의 느낌이라 주관적이다","mis":"K6-2-u3-X08"},{"t":"둘 다 주장과 관련이 없어 지워야 한다","mis":"K6-2-u3-X02"}],"explanation":["이유 ②의 약함은 규모예요.","근거 ③의 약함은 해결 방안이에요.","약한 갈래가 서로 달라요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#9','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C11',4,'essay','teacher','「밤이 너무 밝습니다」를 평가 기준표 세 항목에 ◎ · ○ · △로 판단하고 까닭을 한 문장씩 쓰세요. 타당한 점을 먼저 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C11","difficulty":4,"kind":"essay","stem":"「밤이 너무 밝습니다」를 평가 기준표 세 항목에 ◎ · ○ · △로 판단하고 까닭을 한 문장씩 쓰세요. 타당한 점을 먼저 쓰세요.","answer_guide":{"answer":"예: 주장 ◎ — 사람의 잠과 생물의 생활에 도움이 되고 불빛 하나를 끄는 일은 오늘 바로 할 수 있다. 이유 ○ — 이유 ①과 ③은 왜 줄여야 하는지를 곧바로 말하지만 이유 ②는 늘고 있다는 규모만 말해 보통이다. 근거 ○ — 근거 ①과 ②는 확인할 수 있는 자료이지만 근거 ③은 해결 방안이라 이유 ③을 보여 주지 못한다.","scoring_points":["세 항목에 판단을 표시했는가","타당한 점을 먼저 쓰고 약한 자리를 까닭과 함께 썼는가","이유 ②(규모)와 근거 ③(해결 방안)의 약한 까닭을 바르게 썼는가"]},"explanation":["잘 세워진 자리부터 세요.","약한 자리는 까닭과 함께 써요.","표시마다 한 문장씩 붙여요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L09_challenge#10','kor',6,2,'u3','L09','g6_2_kor_u3_L09_challenge','lesson_challenge','K6-2-u3-C12',4,'essay','teacher','근거 ③이 이유 ③을 뒷받침하지 못하는 까닭을 쓰고, 이유 ③을 뒷받침할 근거를 새로 생각해 쓰세요. 숫자를 지어내지 말고, 그 근거가 사실인지 확인할 방법도 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C12","difficulty":4,"kind":"essay","stem":"근거 ③이 이유 ③을 뒷받침하지 못하는 까닭을 쓰고, 이유 ③을 뒷받침할 근거를 새로 생각해 쓰세요. 숫자를 지어내지 말고, 그 근거가 사실인지 확인할 방법도 함께 쓰세요.","answer_guide":{"answer":"예: 근거 ③의 제도는 문제를 막으려고 마련한 해결 방안이어서, 밤 불빛이 곤충과 새의 생활을 어지럽힌다는 것을 보여 주지 못한다. 새 근거 — 밤 불빛 둘레에 곤충이 모여들어 맴도는 모습을 관찰한 기록. 확인 방법 — 밤 불빛과 생물에 대해 다룬 책이나 기사를 찾아보고, 생물을 연구하는 기관의 누리집에서 출처를 확인한다.","scoring_points":["근거 ③이 해결 방안이라 이유를 보여 주지 못한다는 것을 썼는가","이유 ③을 보여 주는 새 근거를 썼는가","숫자를 지어내지 않고 확인 방법을 썼는가"]},"explanation":["근거는 이유를 보여 주어야 해요.","해결 방안은 그 뒤의 일이에요.","확인할 방법까지 생각해요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#1','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',1,'mc','auto','주제와 관련된 영상을 찾을 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-2-u3-X22','K6-2-u3-X03']::text[],false,'{"seq":1,"concept":"K6-2-u3-C13","difficulty":1,"kind":"mc","stem":"주제와 관련된 영상을 찾을 때 알맞은 방법은 어느 것인가요?","options":[{"t":"주제와 관련된 구체적인 말로 찾고, 끝에 「어린이 · 교육용」 같은 말을 붙인다","correct":true},{"t":"두루뭉술한 한 낱말로만 찾는다","mis":"K6-2-u3-X22"},{"t":"자동으로 뜨는 자극적인 말을 눌러 본다","mis":"K6-2-u3-X22"},{"t":"조회 수가 가장 많은 영상만 고른다","mis":"K6-2-u3-X03"}],"explanation":["구체적인 말로 찾아야 엉뚱한 영상이 덜 나와요.","「어린이·교육용·뉴스」를 붙이면 볼 만한 영상이 나와요.","자극적인 말은 무시해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#2','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C14',1,'sa','auto','「넣고」를 소리 나는 대로 쓰세요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C14","difficulty":1,"kind":"sa","stem":"「넣고」를 소리 나는 대로 쓰세요. 두 글자로 쓰세요.","answer":["너코","[너코]"],"explanation":["받침 ㅎ 뒤에 ㄱ이 왔어요.","ㅎ과 ㄱ이 합쳐 ㅋ이 돼요.","그래서 [너코]로 소리 나요."],"mis":"K6-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#3','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',1,'ox','auto','주장이 없는 영상은 평가표로 잴 수 없어요.',ARRAY['K6-2-u3-X21']::text[],false,'{"seq":3,"concept":"K6-2-u3-C13","difficulty":1,"kind":"ox","stem":"주장이 없는 영상은 평가표로 잴 수 없어요.","answer":"O","reason_options":[{"t":"평가표는 주장 · 이유 · 근거를 재는 것이라 주장이 없으면 잴 것이 없기 때문에","correct":true},{"t":"영상이라면 모두 평가표로 잴 수 있기 때문에","mis":"K6-2-u3-X21"}],"mis":"K6-2-u3-X21","explanation":["평가표의 세 항목은 주장·이유·근거예요.","주장이 없으면 잴 것이 없어요.","먼저 평가할 수 있는 영상인지 가려내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#4','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C14',1,'mc','auto','「좋아」를 바르게 발음한 것은 어느 것인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":4,"concept":"K6-2-u3-C14","difficulty":1,"kind":"mc","stem":"「좋아」를 바르게 발음한 것은 어느 것인가요?","options":[{"t":"[조아]","correct":true},{"t":"[조하]","mis":"K6-2-u3-X23"},{"t":"[존아]","mis":"K6-2-u3-X23"},{"t":"[조타]","mis":"K6-2-u3-X23"}],"explanation":["받침 ㅎ 뒤에 모음이 왔어요.","모음 앞에서는 ㅎ 소리를 내지 않아요.","그래서 [조아]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#5','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',2,'mc','auto','「물 아껴 쓰기」를 다룬 세 영상 가운데 주장이 가장 뚜렷한 영상은 어느 것인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X21']::text[],false,'{"seq":5,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"「물 아껴 쓰기」를 다룬 세 영상 가운데 주장이 가장 뚜렷한 영상은 어느 것인가요?","options":[{"t":"수도꼭지 삼십 초","correct":true},{"t":"물이 오는 길","mis":"K6-2-u3-X15"},{"t":"우리 집 물 쓰기 도전","mis":"K6-2-u3-X21"},{"t":"셋 다 똑같이 뚜렷하다","mis":"K6-2-u3-X21"}],"explanation":["「수도꼭지 삼십 초」는 언제 무엇을 할지 또렷하게 말해요.","「물이 오는 길」은 알려 주는 영상이에요.","「물 쓰기 도전」의 주장은 넓고 근거가 소감이에요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#6','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',2,'match','auto','각 영상과 그 영상에서 살펴야 할 자리를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C13","difficulty":2,"kind":"match","stem":"각 영상과 그 영상에서 살펴야 할 자리를 알맞게 이으세요.","pairs":[{"l":"수도꼭지 삼십 초","r":"주장 · 이유 · 근거가 모두 갖추어져 있다"},{"l":"물이 오는 길","r":"주장이 없어서 평가표로 잴 수 없다"},{"l":"우리 집 물 쓰기 도전","r":"근거가 만든 사람의 느낌에 머물러 있다"}],"mis":"K6-2-u3-X21","explanation":["약한 자리의 갈래가 서로 달라요.","주장이 없는 영상은 평가 대상이 아니에요.","근거가 소감이면 객관적이지 않아요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#7','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',2,'mc','auto','영상을 보는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X22']::text[],false,'{"seq":7,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"영상을 보는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"자세히 보기 → 알아낸 것 말하기 → 무슨 일이 일어나는지 생각하기 → 궁금한 것 묻기","correct":true},{"t":"생각하기 → 자세히 보기 → 궁금한 것 묻기 → 알아낸 것 말하기","mis":"K6-2-u3-X22"},{"t":"궁금한 것 묻기 → 생각하기 → 자세히 보기","mis":"K6-2-u3-X22"},{"t":"자세히 보기 → 생각하기 → 궁금한 것 묻기","mis":"K6-2-u3-X22"}],"explanation":["먼저 말하지 않고 끝까지 보아요.","본 것만 말한 뒤에 생각해요.","마지막에 남은 물음을 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#8','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C14',2,'mc','auto','「빨갛다」를 바르게 발음한 것은 어느 것인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":8,"concept":"K6-2-u3-C14","difficulty":2,"kind":"mc","stem":"「빨갛다」를 바르게 발음한 것은 어느 것인가요?","options":[{"t":"[빨가타]","correct":true},{"t":"[빨갇다]","mis":"K6-2-u3-X23"},{"t":"[빨가다]","mis":"K6-2-u3-X23"},{"t":"[빨각따]","mis":"K6-2-u3-X23"}],"explanation":["받침 ㅎ 뒤에 ㄷ이 왔어요.","ㅎ과 ㄷ이 합쳐 ㅌ이 돼요.","그래서 [빨가타]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#9','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',2,'ox','auto','영상을 평가할 때에는 말투 · 편집 · 음악을 먼저 보고 그다음에 주장 · 이유 · 근거를 봐요.',ARRAY['K6-2-u3-X21']::text[],false,'{"seq":9,"concept":"K6-2-u3-C13","difficulty":2,"kind":"ox","stem":"영상을 평가할 때에는 말투 · 편집 · 음악을 먼저 보고 그다음에 주장 · 이유 · 근거를 봐요.","answer":"X","reason_options":[{"t":"내용의 타당성을 먼저 평가하고 표현은 그다음에 살펴야 하기 때문에","correct":true},{"t":"재미있는 영상이 곧 타당한 영상이기 때문에","mis":"K6-2-u3-X21"}],"mis":"K6-2-u3-X21","explanation":["말투·편집·음악도 살필 수 있어요.","그러나 차례가 있어요.","차례를 바꾸면 재미있는 영상이 곧 타당한 영상이 돼 버려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_basic#10','kor',6,2,'u3','L12','g6_2_kor_u3_L12_basic','lesson_basic','K6-2-u3-C13',3,'error','auto','가장 타당한 영상을 고른 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X21']::text[],false,'{"seq":10,"concept":"K6-2-u3-C13","difficulty":3,"kind":"error","stem":"가장 타당한 영상을 고른 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"예린 — 「‘우리 집 물 쓰기 도전’은 음악이 신나서 가장 타당해.」","correct":true,"mis_target":"K6-2-u3-X21"},{"t":"도겸 — 「‘수도꼭지 삼십 초’는 누가 보아도 확인할 수 있는 자료로 이유를 받쳤어.」","mis":"K6-2-u3-X21"},{"t":"하율 — 「‘물이 오는 길’은 주장이 없어서 평가에서 뺐어.」","mis":"K6-2-u3-X21"}],"explanation":["도겸은 근거의 객관성을 까닭으로 들었어요.","하율은 평가할 수 있는 영상을 먼저 가려냈어요.","예린은 표현으로 타당성을 판단했어요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#1','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',2,'sa','auto','「그렇지」를 소리 나는 대로 쓰세요. 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C14","difficulty":2,"kind":"sa","stem":"「그렇지」를 소리 나는 대로 쓰세요. 세 글자로 쓰세요.","answer":["그러치","[그러치]"],"explanation":["받침 ㅎ 뒤에 ㅈ이 왔어요.","ㅎ과 ㅈ이 합쳐 ㅊ이 돼요.","그래서 [그러치]예요."],"mis":"K6-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#2','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',2,'mc','auto','친구에게 영상을 설명할 때 넣어야 할 것을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X21','K6-2-u3-X12']::text[],false,'{"seq":2,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"친구에게 영상을 설명할 때 넣어야 할 것을 바르게 모은 것은 어느 것인가요?","options":[{"t":"제목 · 주장 · 이유 · 근거 · 세 기준으로 판단한 결과 · 그렇게 판단한 까닭","correct":true},{"t":"영상을 몇 번 보았는지 · 나온 사람의 옷차림","mis":"K6-2-u3-X21"},{"t":"제목과 판단 결과만","mis":"K6-2-u3-X12"},{"t":"영상이 재미있었다는 느낌만","mis":"K6-2-u3-X12"}],"explanation":["듣는 친구가 내 판단을 따라올 수 있어야 해요.","주장·이유·근거와 판단을 넣어요.","왜 그렇게 판단했는지 까닭도 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#3','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',3,'mc','auto','「우리 집 물 쓰기 도전」의 근거를 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X14','K6-2-u3-X17','K6-2-u3-X08']::text[],false,'{"seq":3,"concept":"K6-2-u3-C13","difficulty":3,"kind":"mc","stem":"「우리 집 물 쓰기 도전」의 근거를 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"도전하기 전과 도전한 뒤에 쓴 물의 양을 재어 견주어 보여 준다","correct":true},{"t":"도전이 얼마나 뿌듯했는지 더 크게 말한다","mis":"K6-2-u3-X14"},{"t":"신나는 음악을 더 넣는다","mis":"K6-2-u3-X17"},{"t":"도전한 사람을 더 많이 보여 준다","mis":"K6-2-u3-X08"}],"explanation":["지금 근거는 만든 사람의 소감이에요.","누가 보아도 확인할 수 있는 자료로 바꾸어요.","전과 뒤를 견주면 객관적인 근거가 돼요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#4','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',3,'mc','auto','「넣는」의 바른 발음과 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":4,"concept":"K6-2-u3-C14","difficulty":3,"kind":"mc","stem":"「넣는」의 바른 발음과 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"[넌는] — 받침 ㅎ 뒤에 ㄴ이 오면 ㅎ을 ㄴ으로 발음해서","correct":true},{"t":"[너는] — 받침 ㅎ은 소리를 내지 않아서","mis":"K6-2-u3-X23"},{"t":"[너흔] — ㅎ을 그대로 뒤로 넘겨서","mis":"K6-2-u3-X23"},{"t":"[넏는] — ㅎ을 ㄷ으로 끊어 발음해서","mis":"K6-2-u3-X23"}],"explanation":["받침 ㅎ 뒤에 ㄴ이 왔어요.","이때는 ㅎ을 ㄴ으로 발음해요.","그래서 [넌는]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#5','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',3,'ox','auto','영상을 볼 때 「알아낸 것 말하기」와 「생각하기」를 한꺼번에 해도 돼요.',ARRAY['K6-2-u3-X22']::text[],false,'{"seq":5,"concept":"K6-2-u3-C13","difficulty":3,"kind":"ox","stem":"영상을 볼 때 「알아낸 것 말하기」와 「생각하기」를 한꺼번에 해도 돼요.","answer":"X","reason_options":[{"t":"한꺼번에 하면 본 것과 짐작한 것이 섞이기 때문에","correct":true},{"t":"본 것과 짐작한 것은 같은 것이기 때문에","mis":"K6-2-u3-X22"}],"mis":"K6-2-u3-X22","explanation":["알아낸 것은 본 것만 말해요.","생각하기는 무슨 일이 일어나는지 말해요.","둘을 나누어야 섞이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#6','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',3,'match','auto','받침 ㅎ 뒤에 오는 소리와 그 발음을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C14","difficulty":3,"kind":"match","stem":"받침 ㅎ 뒤에 오는 소리와 그 발음을 알맞게 이으세요.","pairs":[{"l":"ㄱ · ㄷ · ㅈ이 올 때","r":"합쳐서 ㅋ · ㅌ · ㅊ으로 발음한다"},{"l":"ㄴ이 올 때","r":"ㄴ으로 발음한다"},{"l":"모음이 올 때","r":"ㅎ 소리를 내지 않는다"}],"mis":"K6-2-u3-X23","explanation":["넣고[너코] — ㄱ과 합쳐요.","넣는[넌는] — ㄴ으로 소리 나요.","좋아[조아] — ㅎ 소리가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#7','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',3,'error','auto','평가할 수 있는 영상인지 가려내는 말이에요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X21','K6-2-u3-X08']::text[],false,'{"seq":7,"concept":"K6-2-u3-C13","difficulty":3,"kind":"error","stem":"평가할 수 있는 영상인지 가려내는 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민호 — 「‘물이 오는 길’은 근거가 약하니 △로 표시하면 돼.」","correct":true,"mis_target":"K6-2-u3-X21"},{"t":"아린 — 「‘물이 오는 길’은 무엇을 하자는 말이 없으니 평가표에서 빼야 해.」","mis":"K6-2-u3-X21"},{"t":"서준 — 「‘우리 집 물 쓰기 도전’은 주장은 있지만 근거가 느낌이야.」","mis":"K6-2-u3-X08"}],"explanation":["「물이 오는 길」은 알려 주는 영상이에요.","주장이 없으니 평가표로 잴 수 없어요.","△는 평가할 수 있는 영상에 쓰는 표시예요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#8','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',4,'mc','auto','친구와 가장 타당한 영상을 다르게 골랐을 때 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u3-X12','K6-2-u3-X02']::text[],false,'{"seq":8,"concept":"K6-2-u3-C13","difficulty":4,"kind":"mc","stem":"친구와 가장 타당한 영상을 다르게 골랐을 때 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「나는 근거가 객관적인지를 가장 무겁게 보았어. 너는 어떤 기준을 무겁게 보았니?」","correct":true},{"t":"「내 생각이 맞으니까 너도 바꿔.」","mis":"K6-2-u3-X12"},{"t":"「둘 다 틀렸으니 다른 영상을 찾자.」","mis":"K6-2-u3-X02"},{"t":"「그냥 그 영상이 좋았어.」","mis":"K6-2-u3-X12"}],"explanation":["판단은 갈릴 수 있어요.","어떤 기준을 무겁게 보았는지 서로 말해요.","까닭이 있어야 이야기가 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#9','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C13',4,'essay','teacher','「물 아껴 쓰기」를 다룬 세 영상 가운데 가장 타당한 영상을 골라, 제목 → 주장 → 이유 → 근거 → 판단 → 까닭 차례로 친구에게 설명하는 말을 쓰세요. 다른 두 영상을 고르지 않은 까닭도 한 문장씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C13","difficulty":4,"kind":"essay","stem":"「물 아껴 쓰기」를 다룬 세 영상 가운데 가장 타당한 영상을 골라, 제목 → 주장 → 이유 → 근거 → 판단 → 까닭 차례로 친구에게 설명하는 말을 쓰세요. 다른 두 영상을 고르지 않은 까닭도 한 문장씩 쓰세요.","answer_guide":{"answer":"예: 제가 고른 영상은 「수도꼭지 삼십 초」입니다. 주장은 이를 닦는 동안 수도꼭지를 잠그자는 것이고, 이유는 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문입니다. 근거로 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 주었습니다. 세 기준 모두 ◎로 판단했는데, 누가 보아도 확인할 수 있는 자료로 이유를 받쳤기 때문입니다. 「물이 오는 길」은 주장이 없어 평가에서 뺐고, 「우리 집 물 쓰기 도전」은 근거가 만든 사람의 소감이라 고르지 않았습니다.","scoring_points":["제목·주장·이유·근거·판단·까닭을 차례대로 썼는가","판단한 까닭이 세 기준에 맞는가","다른 두 영상을 고르지 않은 까닭을 바르게 썼는가"]},"explanation":["설명의 차례를 지켜요.","판단에는 까닭을 붙여요.","주장이 없는 영상은 먼저 가려내요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_L12_challenge#10','kor',6,2,'u3','L12','g6_2_kor_u3_L12_challenge','lesson_challenge','K6-2-u3-C14',4,'essay','teacher','「놓고」 · 「놓는」 · 「놓아」를 넣어 문장을 하나씩 만들고, 각 낱말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u3-C14","difficulty":4,"kind":"essay","stem":"「놓고」 · 「놓는」 · 「놓아」를 넣어 문장을 하나씩 만들고, 각 낱말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「책상 위에 가방을 놓고 앉았다.」에서 「놓고」는 [노코], 「꽃병을 놓는 자리를 찾았다.」에서 「놓는」은 [논는], 「컵을 식탁에 놓아 두었다.」에서 「놓아」는 [노아]로 소리 난다. 받침 ㅎ 뒤에 ㄱ이 오면 합쳐서 ㅋ으로, ㄴ이 오면 ㄴ으로 소리 나고, 모음이 오면 ㅎ 소리를 내지 않기 때문이다.","scoring_points":["세 낱말을 넣어 문장을 하나씩 만들었는가","[노코]·[논는]·[노아]로 바르게 썼는가","뒤에 오는 소리에 따른 까닭을 썼는가"]},"explanation":["ㄱ 앞 — 합쳐서 ㅋ.","ㄴ 앞 — ㄴ으로.","모음 앞 — 소리 없음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#1','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C1',1,'mc','auto','윤채가 한 말의 주장은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"mc","stem":"윤채가 한 말의 주장은 무엇인가요?","options":[{"t":"쉬는 시간마다 교실 창문을 열자","correct":true},{"t":"창문을 닫아 두면 교실 공기가 탁해진다","mis":"K6-2-u3-X01"},{"t":"창문을 연 날 수업 시간에 덜 졸렸다","mis":"K6-2-u3-X01"},{"t":"교실에 공기 측정기를 더 사자","mis":"K6-2-u3-X01"}],"explanation":["윤채가 하자고 한 일이 주장이에요.","「탁해지기 때문」은 이유예요.","덜 졸렸다는 것은 근거로 든 경험이에요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#2','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C2',1,'mc','auto','비판적으로 본다는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"mc","stem":"비판적으로 본다는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"옳고 그른지를 제대로 따져 보는 것","correct":true},{"t":"무조건 믿지 않는 것","mis":"K6-2-u3-X02"},{"t":"말한 사람을 깎아내리는 것","mis":"K6-2-u3-X02"},{"t":"어디든 잘못이 있다고 미리 정해 두는 것","mis":"K6-2-u3-X02"}],"explanation":["비판은 의심과 달라요.","까닭을 들어 따져요.","맞는 것은 맞다고도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#3','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C3',1,'mc','auto','주장하는 말은 한 번 듣고 지나가요. 그래서 어떻게 들어야 할까요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":3,"concept":"K6-2-u3-C3","difficulty":1,"kind":"mc","stem":"주장하는 말은 한 번 듣고 지나가요. 그래서 어떻게 들어야 할까요?","options":[{"t":"이유나 근거를 놓치지 않도록 메모하며 듣는다","correct":true},{"t":"한 번 들었으니 느낌만 기억한다","mis":"K6-2-u3-X04"},{"t":"말하는 사람의 목소리만 기억한다","mis":"K6-2-u3-X04"},{"t":"끝까지 듣지 않고 결론을 정한다","mis":"K6-2-u3-X04"}],"explanation":["글은 다시 읽지만 말은 되감을 수 없어요.","이유와 근거를 적으며 들어요.","그래야 평가할 거리가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#4','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C4',1,'mc','auto','주장이 가치 있고 중요한지 판단하는 물음은 어느 것인가요?',ARRAY['K6-2-u3-X05','K6-2-u3-X03']::text[],false,'{"seq":4,"concept":"K6-2-u3-C4","difficulty":1,"kind":"mc","stem":"주장이 가치 있고 중요한지 판단하는 물음은 어느 것인가요?","options":[{"t":"문제를 해결하거나 생활하는 데 도움이 되는가?","correct":true},{"t":"말이 멋있는가?","mis":"K6-2-u3-X05"},{"t":"주장이 긴가?","mis":"K6-2-u3-X05"},{"t":"말한 사람이 유명한가?","mis":"K6-2-u3-X03"}],"explanation":["주장은 도움이 되는지 보아요.","실천 가능한지도 보아요.","멋·길이·유명함은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#5','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C6',1,'match','auto','근거 자료의 이름과 그 자료가 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u3-C6","difficulty":1,"kind":"match","stem":"근거 자료의 이름과 그 자료가 하는 일을 알맞게 이으세요.","pairs":[{"l":"그래프","r":"늘고 주는 흐름을 한눈에 보여 준다"},{"l":"면담 자료","r":"그 일을 겪은 사람의 말을 그대로 옮긴다"},{"l":"표","r":"여러 값을 나란히 놓아 견주게 해 준다"}],"mis":"K6-2-u3-X10","explanation":["그래프는 흐름이에요.","면담 자료는 사람의 말이에요.","표는 나란히 견주게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#6','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C7',1,'mc','auto','주장하는 말을 평가하는 일은 어떤 일인가요?',ARRAY['K6-2-u3-X11','K6-2-u3-X03']::text[],false,'{"seq":6,"concept":"K6-2-u3-C7","difficulty":1,"kind":"mc","stem":"주장하는 말을 평가하는 일은 어떤 일인가요?","options":[{"t":"더 나아지게 하는 일","correct":true},{"t":"이긴 쪽을 고르는 일","mis":"K6-2-u3-X11"},{"t":"흠을 찾아내는 일","mis":"K6-2-u3-X11"},{"t":"말한 사람을 칭찬만 하는 일","mis":"K6-2-u3-X03"}],"explanation":["평가는 겨루기가 아니에요.","살릴 것과 고칠 것을 함께 찾아요.","그래서 더 나아지게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#7','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C9',1,'mc','auto','영상 「걸을 땐, 고개를 들어요」의 주장은 무엇인가요?',ARRAY['K6-2-u3-X15','K6-2-u3-X17']::text[],false,'{"seq":7,"concept":"K6-2-u3-C9","difficulty":1,"kind":"mc","stem":"영상 「걸을 땐, 고개를 들어요」의 주장은 무엇인가요?","options":[{"t":"걸을 때는 화면을 보지 말고 고개를 들자","correct":true},{"t":"횡단보도를 더 넓히자","mis":"K6-2-u3-X15"},{"t":"자전거를 타지 말자","mis":"K6-2-u3-X15"},{"t":"북소리를 크게 듣자","mis":"K6-2-u3-X17"}],"explanation":["제목과 마지막 자막이 같은 말을 해요.","장면들은 걸으며 화면을 볼 때의 문제를 보여 줘요.","셋을 합치면 이 주장이 돼요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#8','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C11',1,'mc','auto','카드 뉴스에서 이유와 근거가 대개 놓이는 자리는 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X03']::text[],false,'{"seq":8,"concept":"K6-2-u3-C11","difficulty":1,"kind":"mc","stem":"카드 뉴스에서 이유와 근거가 대개 놓이는 자리는 어느 것인가요?","options":[{"t":"가운데 장에 한 장에 한 쌍씩","correct":true},{"t":"첫 장의 제목 자리","mis":"K6-2-u3-X01"},{"t":"마지막 장의 그림 안","mis":"K6-2-u3-X01"},{"t":"카드 뉴스에는 근거가 없다","mis":"K6-2-u3-X03"}],"explanation":["첫 장에는 제목과 주장이 들어가요.","가운데 장에 이유와 근거가 한 쌍씩 놓여요.","마지막 장은 대개 실천을 권해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#9','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C1',2,'mc','auto','윤채의 첫째 이유를 뒷받침하는 근거는 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X08']::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":2,"kind":"mc","stem":"윤채의 첫째 이유를 뒷받침하는 근거는 어느 것인가요?","options":[{"t":"우리 반 공기 측정기로 잰 수치가 창문을 연 뒤 내려간 것","correct":true},{"t":"창문을 열면 기분이 상쾌해진다는 것","mis":"K6-2-u3-X01"},{"t":"창문을 연 날 덜 졸렸다는 것","mis":"K6-2-u3-X08"},{"t":"창가에 앉은 사람부터 열자는 것","mis":"K6-2-u3-X01"}],"explanation":["첫째 이유는 「공기가 탁해진다」예요.","그것을 보여 주는 것은 측정기로 잰 수치예요.","상쾌함은 둘째 이유예요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#10','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C8',2,'mc','auto','윤채의 근거 가운데 객관적인 것은 어느 것인가요?',ARRAY['K6-2-u3-X08']::text[],false,'{"seq":10,"concept":"K6-2-u3-C8","difficulty":2,"kind":"mc","stem":"윤채의 근거 가운데 객관적인 것은 어느 것인가요?","options":[{"t":"공기 측정기로 잰 수치","correct":true},{"t":"창문을 연 날 덜 졸렸다는 경험","mis":"K6-2-u3-X08"},{"t":"창문을 열면 상쾌하다는 느낌","mis":"K6-2-u3-X08"},{"t":"창가 자리가 좋다는 생각","mis":"K6-2-u3-X08"}],"explanation":["측정기로 잰 수치는 누가 보아도 같아요.","덜 졸렸다는 것은 윤채 한 사람의 경험이에요.","느낌과 생각은 주관적이에요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#11','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C6',2,'mc','auto','근거가 사실인지 확인하는 방법을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u3-X09','K6-2-u3-X03']::text[],false,'{"seq":11,"concept":"K6-2-u3-C6","difficulty":2,"kind":"mc","stem":"근거가 사실인지 확인하는 방법을 바르게 모은 것은 어느 것인가요?","options":[{"t":"책이나 기사 찾아보기 · 그 일을 맡은 기관의 누리집 확인하기 · 아는 어른께 여쭙기","correct":true},{"t":"검색해서 맨 위에 나온 것 믿기","mis":"K6-2-u3-X09"},{"t":"말한 사람에게 맞는지만 묻기","mis":"K6-2-u3-X09"},{"t":"친구들이 다 믿으면 사실로 보기","mis":"K6-2-u3-X03"}],"explanation":["확인하는 방법은 여러 가지예요.","찾은 기사도 출처를 한 번 더 살펴요.","많이 믿는다고 사실이 되지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#12','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C9',2,'match','auto','「걸을 땐, 고개를 들어요」에서 영상의 요소와 그에 해당하는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u3-C9","difficulty":2,"kind":"match","stem":"「걸을 땐, 고개를 들어요」에서 영상의 요소와 그에 해당하는 것을 알맞게 이으세요.","pairs":[{"l":"제목","r":"걸을 땐, 고개를 들어요"},{"l":"제시한 자료","r":"학교 앞에서 조사한 화면"},{"l":"강조하는 표현","r":"되풀이되는 빨간 자막 「멈춰!」"}],"mis":"K6-2-u3-X15","explanation":["제목은 영상의 이름이에요.","조사 화면은 자료예요.","되풀이 자막은 강조예요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#13','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C5',2,'mc','auto','「가까운 층은 계단으로」의 이유 가운데 타당하지 않은 것은 어느 것인가요?',ARRAY['K6-2-u3-X07','K6-2-u3-X02']::text[],false,'{"seq":13,"concept":"K6-2-u3-C5","difficulty":2,"kind":"mc","stem":"「가까운 층은 계단으로」의 이유 가운데 타당하지 않은 것은 어느 것인가요?","options":[{"t":"계단으로 다니는 사람이 더 멋있어 보이기 때문이다","correct":true},{"t":"꼭 필요한 사람이 오래 기다리게 되기 때문이다","mis":"K6-2-u3-X07"},{"t":"몸을 움직일 좋은 기회이기 때문이다","mis":"K6-2-u3-X07"},{"t":"세 이유 모두 타당하지 않다","mis":"K6-2-u3-X02"}],"explanation":["주장과 관련 있는지, 많은 사람이 받아들일 만한지 보아요.","멋있어 보이는 것은 사람마다 달라요.","이유 ①과 ②는 받아들일 만해요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#14','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C12',2,'mc','auto','「놀이터 쓰레기를 줄이자. 놀이터 쓰레기가 해마다 늘고 있기 때문이다.」의 이유가 약한 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X09','K6-2-u3-X12','K6-2-u3-X06']::text[],false,'{"seq":14,"concept":"K6-2-u3-C12","difficulty":2,"kind":"mc","stem":"「놀이터 쓰레기를 줄이자. 놀이터 쓰레기가 해마다 늘고 있기 때문이다.」의 이유가 약한 까닭은 어느 것인가요?","options":[{"t":"늘고 있다는 것은 문제의 규모일 뿐 왜 줄여야 하는지는 말하지 않아서","correct":true},{"t":"늘고 있다는 것은 사실이 아니어서","mis":"K6-2-u3-X09"},{"t":"이유가 너무 짧아서","mis":"K6-2-u3-X12"},{"t":"이유가 주장과 관련이 없어서","mis":"K6-2-u3-X06"}],"explanation":["「그래서 왜 줄여야 하는데?」를 물어요.","늘고 있다는 것은 크기예요.","무엇이 나빠지는지 말해야 이유가 서요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#15','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C13',2,'mc','auto','영상을 찾을 주제를 고를 때 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X07','K6-2-u3-X22']::text[],false,'{"seq":15,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"영상을 찾을 주제를 고를 때 알맞은 것은 어느 것인가요?","options":[{"t":"여러 사람이 함께 생각해 볼 만한 것으로 고른다","correct":true},{"t":"나만 좋아하는 것으로만 고른다","mis":"K6-2-u3-X07"},{"t":"자극적일수록 좋은 주제다","mis":"K6-2-u3-X22"},{"t":"처음 뜬 영상의 주제를 그대로 쓴다","mis":"K6-2-u3-X22"}],"explanation":["환경·건강·안전·우리 동네처럼 함께 생각할 주제가 좋아요.","좋아하는 것만으로 고르지 않아요.","자극적인 것은 피해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#16','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C14',2,'mc','auto','「좋다」를 바르게 발음한 것은 어느 것인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":16,"concept":"K6-2-u3-C14","difficulty":2,"kind":"mc","stem":"「좋다」를 바르게 발음한 것은 어느 것인가요?","options":[{"t":"[조타]","correct":true},{"t":"[졷다]","mis":"K6-2-u3-X23"},{"t":"[조다]","mis":"K6-2-u3-X23"},{"t":"[존다]","mis":"K6-2-u3-X23"}],"explanation":["받침 ㅎ 뒤에 ㄷ이 왔어요.","ㅎ과 ㄷ이 합쳐 ㅌ이 돼요.","그래서 [조타]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#17','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C8',3,'mc','auto','윤채의 둘째 근거 「창문을 연 날 덜 졸렸다」를 객관적인 근거로 고친 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X14','K6-2-u3-X08']::text[],false,'{"seq":17,"concept":"K6-2-u3-C8","difficulty":3,"kind":"mc","stem":"윤채의 둘째 근거 「창문을 연 날 덜 졸렸다」를 객관적인 근거로 고친 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"창문을 연 날과 닫은 날, 수업 중에 졸렸다고 답한 사람 수를 우리 반에서 조사해 견준 표","correct":true},{"t":"나는 창문을 연 날 정말 정말 덜 졸렸다는 말","mis":"K6-2-u3-X14"},{"t":"상쾌한 바람 소리를 들려주는 것","mis":"K6-2-u3-X14"},{"t":"창문을 활짝 연 교실 사진","mis":"K6-2-u3-X08"}],"explanation":["한 사람의 경험은 주관적이에요.","반 전체에게 물어 견주면 확인할 수 있어요.","더 힘주어 말하는 것은 고치는 것이 아니에요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#18','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C10',3,'mc','auto','「걸을 땐, 고개를 들어요」의 타당성을 따지려면 무엇을 살펴야 하나요?',ARRAY['K6-2-u3-X17']::text[],false,'{"seq":18,"concept":"K6-2-u3-C10","difficulty":3,"kind":"mc","stem":"「걸을 땐, 고개를 들어요」의 타당성을 따지려면 무엇을 살펴야 하나요?","options":[{"t":"장면 1 · 3과 조사 화면이 걸으며 화면을 보면 위험하다는 것을 정말 보여 주는지","correct":true},{"t":"북소리가 얼마나 큰지","mis":"K6-2-u3-X17"},{"t":"자막 색이 얼마나 빨간지","mis":"K6-2-u3-X17"},{"t":"자막이 몇 번 되풀이되는지","mis":"K6-2-u3-X17"}],"explanation":["강조는 주장을 찾는 데 썼어요.","타당성은 자료가 이유를 보여 주는지로 따져요.","소리·색·되풀이는 기준이 아니에요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#19','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C11',3,'mc','auto','「밤이 너무 밝습니다」의 근거 ①이 이유 ①을 잘 받쳐 주는 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X01']::text[],false,'{"seq":19,"concept":"K6-2-u3-C11","difficulty":3,"kind":"mc","stem":"「밤이 너무 밝습니다」의 근거 ①이 이유 ①을 잘 받쳐 주는 까닭은 어느 것인가요?","options":[{"t":"잠드는 데 걸리는 시간이 길어진다는, 확인할 수 있는 연구 결과여서","correct":true},{"t":"연구라는 말이 어려워 보여서","mis":"K6-2-u3-X08"},{"t":"셋째 장에 놓여 있어서","mis":"K6-2-u3-X01"},{"t":"근거가 길어서","mis":"K6-2-u3-X08"}],"explanation":["이유 ①은 잠을 방해한다는 것이에요.","근거 ①은 잠드는 시간이 길어진다는 것을 보여 줘요.","확인할 수 있는 자료예요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#20','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C5',3,'mc','auto','「가까운 층은 계단으로」에서 이유 ③ 자리에 놓을 더 나은 이유로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X07','K6-2-u3-X06']::text[],false,'{"seq":20,"concept":"K6-2-u3-C5","difficulty":3,"kind":"mc","stem":"「가까운 층은 계단으로」에서 이유 ③ 자리에 놓을 더 나은 이유로 알맞은 것은 어느 것인가요?","options":[{"t":"승강기를 덜 쓰면 전기를 아낄 수 있기 때문이다","correct":true},{"t":"계단에서 찍은 사진이 잘 나오기 때문이다","mis":"K6-2-u3-X07"},{"t":"승강기를 타면 지루하기 때문이다","mis":"K6-2-u3-X07"},{"t":"건물에 계단이 있기 때문이다","mis":"K6-2-u3-X06"}],"explanation":["주장과 관련 있어야 해요.","많은 사람이 받아들일 만해야 해요.","전기를 아끼는 일은 누구에게나 해당해요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#21','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C7',3,'mc','auto','친구와 판단이 갈렸을 때 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K6-2-u3-X12']::text[],false,'{"seq":21,"concept":"K6-2-u3-C7","difficulty":3,"kind":"mc","stem":"친구와 판단이 갈렸을 때 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"「나는 이유가 많은 사람에게 받아들여질 만한지를 가장 무겁게 보아 △로 했어.」","correct":true},{"t":"「그냥 그렇게 느꼈어.」","mis":"K6-2-u3-X12"},{"t":"「내 생각에는 그게 맞아.」","mis":"K6-2-u3-X12"},{"t":"「네가 ◎를 했으니 나는 △를 할래.」","mis":"K6-2-u3-X12"}],"explanation":["판단은 갈릴 수 있어요.","어떤 기준을 무겁게 보았는지 말해요.","느낌만으로는 까닭이 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#22','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C2',3,'mc','auto','이 단원에서 배운 「비판적으로 보기」를 가장 바르게 말한 것은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X17','K6-2-u3-X03']::text[],false,'{"seq":22,"concept":"K6-2-u3-C2","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 「비판적으로 보기」를 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"타당한 점을 먼저 세고, 보완할 점을 까닭과 함께 말하는 것","correct":true},{"t":"약한 데를 빠짐없이 찾아내 그 자료를 버리는 것","mis":"K6-2-u3-X02"},{"t":"강조가 센 쪽을 믿는 것","mis":"K6-2-u3-X17"},{"t":"말 잘하는 사람을 따르는 것","mis":"K6-2-u3-X03"}],"explanation":["비판은 의심이 아니에요.","살릴 것을 먼저 세어요.","고칠 것은 까닭과 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#23','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C7',4,'mc','auto','윤채의 발표를 더 낫게 고치는 조언으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X14','K6-2-u3-X20','K6-2-u3-X08']::text[],false,'{"seq":23,"concept":"K6-2-u3-C7","difficulty":4,"kind":"mc","stem":"윤채의 발표를 더 낫게 고치는 조언으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장과 첫째 이유 · 측정 수치는 살리고, 둘째 이유와 졸린 경험은 우리 반 조사처럼 확인할 수 있는 자료로 바꾸자","correct":true},{"t":"둘째 이유를 더 힘주어 여러 번 말하자","mis":"K6-2-u3-X14"},{"t":"약한 데가 있으니 발표를 모두 새로 쓰자","mis":"K6-2-u3-X20"},{"t":"측정 수치는 빼고 느낌을 더 넣자","mis":"K6-2-u3-X08"}],"explanation":["살릴 것을 먼저 정해요.","약한 자리는 확인할 수 있는 자료로 바꾸어요.","전체를 버리거나 느낌을 키우지 않아요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#24','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C7',4,'essay','teacher','윤채의 발표를 타당한 점과 보완할 점으로 나누어 평가하고, 보완할 점을 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C7","difficulty":4,"kind":"essay","stem":"윤채의 발표를 타당한 점과 보완할 점으로 나누어 평가하고, 보완할 점을 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 타당한 점 — 쉬는 시간 십 분에 창가에 앉은 사람부터 창문을 열자는 주장은 오늘 바로 할 수 있고, 공기가 탁해진다는 첫째 이유는 우리 반 공기 측정기로 잰 수치라는 확인할 수 있는 근거로 받쳐져 있다. 보완할 점 — 기분이 상쾌해진다는 둘째 이유와 덜 졸렸다는 근거는 윤채 한 사람의 느낌과 경험이라 많은 사람이 받아들이기 어렵다. 고칠 방법 — 창문을 연 날과 닫은 날 졸렸다고 답한 사람 수를 우리 반에서 조사해 견준 표로 바꾼다.","scoring_points":["타당한 점을 먼저 썼는가","보완할 점을 기준(받아들일 만함·객관성)에 대어 썼는가","확인할 수 있는 자료로 고치는 방법을 썼는가"]},"explanation":["살릴 것부터 써요.","고칠 것은 기준과 함께 써요.","느낌은 조사 자료로 바꾸어요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_a#25','kor',6,2,'u3','','g6_2_kor_u3_review_a','unit_review','K6-2-u3-C1',4,'essay','teacher','우리 학교나 동네를 더 낫게 만들 주장을 하나 정해 주장 · 이유 · 근거로 쓰세요. 근거는 확인할 수 있는 자료로 쓰고 출처를 밝히되, 숫자를 지어내지 마세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C1","difficulty":4,"kind":"essay","stem":"우리 학교나 동네를 더 낫게 만들 주장을 하나 정해 주장 · 이유 · 근거로 쓰세요. 근거는 확인할 수 있는 자료로 쓰고 출처를 밝히되, 숫자를 지어내지 마세요.","answer_guide":{"answer":"예: 주장 — 학교 앞 횡단보도에서는 신호가 바뀌어도 좌우를 한 번 더 살피고 건너자. 이유 — 신호가 바뀐 뒤에도 미처 멈추지 못한 차나 자전거가 지나갈 수 있기 때문이다. 근거 — 우리 반이 지난주 아침에 학교 앞 횡단보도를 지켜보며 신호가 바뀐 뒤 지나간 자전거를 적은 기록이 있다.","scoring_points":["실천 가능한 주장을 썼는가","주장과 관련 있고 많은 사람이 받아들일 만한 이유를 썼는가","출처가 밝혀진 확인할 수 있는 근거를 썼는가"]},"explanation":["주장은 언제 무엇을 할지 분명하게.","이유는 누구에게나 해당하게.","근거는 확인할 수 있게, 출처와 함께."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#1','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C1',1,'sa','auto','어떤 주제에 대한 자신의 의견을 드러내는 말을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"sa","stem":"어떤 주제에 대한 자신의 의견을 드러내는 말을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["주장"],"explanation":["이유는 까닭을 설명해요.","근거는 이유를 뒷받침해요.","의견을 드러내는 말은 주장이에요."],"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#2','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C2',1,'ox','auto','비판적으로 보면 다른 사람의 의견과 내 의견을 견주어 볼 수 있어요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"ox","stem":"비판적으로 보면 다른 사람의 의견과 내 의견을 견주어 볼 수 있어요.","answer":"O","reason_options":[{"t":"주장 · 이유 · 근거를 따져 보면 내 생각과 어디가 같고 다른지 보이기 때문에","correct":true},{"t":"비판적으로 보면 내 의견만 옳다는 것을 알게 되기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["따져 보면 내용을 제대로 이해해요.","내 생각과 견주어 볼 수 있어요.","내 의견만 옳다는 뜻은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#3','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C3',1,'ox','auto','주장하는 말을 들을 때 지나치게 감정에 호소하지는 않는지도 살펴요.',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":3,"concept":"K6-2-u3-C3","difficulty":1,"kind":"ox","stem":"주장하는 말을 들을 때 지나치게 감정에 호소하지는 않는지도 살펴요.","answer":"O","reason_options":[{"t":"말하는 사람의 표현이나 태도도 살펴 들어야 하기 때문에","correct":true},{"t":"감정에 호소하는 말일수록 타당하기 때문에","mis":"K6-2-u3-X04"}],"mis":"K6-2-u3-X04","explanation":["내용뿐 아니라 태도도 살펴요.","감정에 호소하면 마음이 먼저 움직여요.","그럴수록 이유와 근거를 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#4','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C5',1,'mc','auto','이유의 타당성을 판단하는 물음은 어느 것인가요?',ARRAY['K6-2-u3-X07','K6-2-u3-X10','K6-2-u3-X06']::text[],false,'{"seq":4,"concept":"K6-2-u3-C5","difficulty":1,"kind":"mc","stem":"이유의 타당성을 판단하는 물음은 어느 것인가요?","options":[{"t":"이유가 주장과 관련 있는가?","correct":true},{"t":"이유가 말한 사람의 마음에 드는가?","mis":"K6-2-u3-X07"},{"t":"이유가 조사한 표로 되어 있는가?","mis":"K6-2-u3-X10"},{"t":"이유가 짧은가?","mis":"K6-2-u3-X06"}],"explanation":["이유는 주장과 관련 있어야 해요.","많은 사람이 받아들일 만해야 해요.","표는 근거의 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#5','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C6',1,'sa','auto','늘고 주는 흐름을 한눈에 보여 주는 근거 자료를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u3-C6","difficulty":1,"kind":"sa","stem":"늘고 주는 흐름을 한눈에 보여 주는 근거 자료를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["그래프"],"explanation":["표는 값을 나란히 놓아요.","흐름을 보여 주는 것은 그래프예요.","「밤 밝기를 해마다 조사한」 자료가 그래프였어요."],"mis":"K6-2-u3-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#6','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C8',1,'sa','auto','자기 혼자만의 생각이나 느낌에 치우친 것을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u3-C8","difficulty":1,"kind":"sa","stem":"자기 혼자만의 생각이나 느낌에 치우친 것을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["주관적"],"explanation":["누가 보아도 그러한 것은 객관적이에요.","혼자만의 느낌에 치우친 것은 주관적이에요.","근거는 객관적이어야 해요."],"mis":"K6-2-u3-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#7','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C9',1,'sa','auto','영상의 주장을 파악할 때 살피는 세 가지는 제목 · 제시한 ○○ · 강조하는 장면이나 표현이에요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u3-C9","difficulty":1,"kind":"sa","stem":"영상의 주장을 파악할 때 살피는 세 가지는 제목 · 제시한 ○○ · 강조하는 장면이나 표현이에요. ○○에 알맞은 두 글자를 쓰세요.","answer":["자료"],"explanation":["제목을 정한 까닭을 생각해요.","제시한 자료의 내용을 파악해요.","강조된 장면과 표현을 찾아요."],"mis":"K6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#8','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C14',1,'mc','auto','「쌓고」를 바르게 발음한 것은 어느 것인가요?',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":8,"concept":"K6-2-u3-C14","difficulty":1,"kind":"mc","stem":"「쌓고」를 바르게 발음한 것은 어느 것인가요?","options":[{"t":"[싸코]","correct":true},{"t":"[싸고]","mis":"K6-2-u3-X23"},{"t":"[싿고]","mis":"K6-2-u3-X23"},{"t":"[쌋꼬]","mis":"K6-2-u3-X23"}],"explanation":["받침 ㅎ 뒤에 ㄱ이 왔어요.","ㅎ과 ㄱ이 합쳐 ㅋ이 돼요.","그래서 [싸코]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#9','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C1',2,'match','auto','윤채가 한 말의 자리와 그 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":2,"kind":"match","stem":"윤채가 한 말의 자리와 그 내용을 알맞게 이으세요.","pairs":[{"l":"주장","r":"쉬는 시간마다 교실 창문을 열자"},{"l":"첫째 이유","r":"닫아 두면 공기가 탁해져 머리가 무거워진다"},{"l":"첫째 근거","r":"공기 측정기로 잰 수치가 내려갔다"}],"mis":"K6-2-u3-X01","explanation":["하자는 말이 주장이에요.","「~ 때문입니다」가 이유예요.","측정한 수치가 근거예요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#10','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C5',2,'mc','auto','윤채의 둘째 이유 「창문을 열면 기분이 상쾌해지기 때문입니다」를 평가한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X06','K6-2-u3-X08','K6-2-u3-X20']::text[],false,'{"seq":10,"concept":"K6-2-u3-C5","difficulty":2,"kind":"mc","stem":"윤채의 둘째 이유 「창문을 열면 기분이 상쾌해지기 때문입니다」를 평가한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"주장과 관련은 있지만 느낌이라 사람마다 달라 많은 사람이 받아들이기에 약하다","correct":true},{"t":"주장과 아무 관련이 없다","mis":"K6-2-u3-X06"},{"t":"누가 보아도 그러한 사실이라 아주 튼튼하다","mis":"K6-2-u3-X08"},{"t":"이유가 약하니 주장 전체가 틀렸다","mis":"K6-2-u3-X20"}],"explanation":["창문을 여는 일과 이어지니 관련은 있어요.","그러나 상쾌함은 사람마다 달라요.","하나만 통과한 이유예요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#11','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C8',2,'ox','auto','남이 만든 자료를 출처 없이 쓰면 그 자료를 내 것처럼 쓰게 돼요.',ARRAY['K6-2-u3-X13']::text[],false,'{"seq":11,"concept":"K6-2-u3-C8","difficulty":2,"kind":"ox","stem":"남이 만든 자료를 출처 없이 쓰면 그 자료를 내 것처럼 쓰게 돼요.","answer":"O","reason_options":[{"t":"누가 만든 자료인지 밝히지 않으면 듣는 사람은 내가 만든 것으로 알기 때문에","correct":true},{"t":"자료는 쓰는 사람의 것이 되기 때문에","mis":"K6-2-u3-X13"}],"mis":"K6-2-u3-X13","explanation":["가져다 쓴 자료는 어디에서 왔는지 밝혀요.","그래야 남의 것을 내 것처럼 쓰지 않아요.","듣는 사람도 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#12','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C9',2,'mc','auto','「걸을 땐, 고개를 들어요」에 장면 2의 조사 화면을 넣은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":12,"concept":"K6-2-u3-C9","difficulty":2,"kind":"mc","stem":"「걸을 땐, 고개를 들어요」에 장면 2의 조사 화면을 넣은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"걸으며 화면을 보는 문제가 우리 가까이에 실제로 있다는 것을 보여 주려고","correct":true},{"t":"학교가 얼마나 큰지 알려 주려고","mis":"K6-2-u3-X15"},{"t":"화면을 보는 것이 재미있다는 것을 알리려고","mis":"K6-2-u3-X15"},{"t":"영상을 길게 만들려고","mis":"K6-2-u3-X15"}],"explanation":["자료를 넣은 자리에는 까닭이 있어요.","조사 화면은 문제가 있다는 것을 보여 줘요.","우리 학교 앞이라 더 가깝게 느껴져요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#13','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C11',2,'mc','auto','「가까운 층은 계단으로」의 주장은 무엇인가요?',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":13,"concept":"K6-2-u3-C11","difficulty":2,"kind":"mc","stem":"「가까운 층은 계단으로」의 주장은 무엇인가요?","options":[{"t":"삼 층까지는 계단으로 다니자","correct":true},{"t":"승강기를 없애자","mis":"K6-2-u3-X01"},{"t":"계단을 새로 칠하자","mis":"K6-2-u3-X01"},{"t":"승강기를 기다린 시간을 재자","mis":"K6-2-u3-X01"}],"explanation":["첫머리의 「다닙시다」가 주장이에요.","승강기를 없애자는 말은 없어요.","시간을 잰 것은 근거예요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#14','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',2,'ox','auto','제도가 마련되어 있다는 것은 문제가 왜 생기는지를 보여 주는 근거예요.',ARRAY['K6-2-u3-X19']::text[],false,'{"seq":14,"concept":"K6-2-u3-C12","difficulty":2,"kind":"ox","stem":"제도가 마련되어 있다는 것은 문제가 왜 생기는지를 보여 주는 근거예요.","answer":"X","reason_options":[{"t":"제도는 문제에 대한 해결 방안이라 문제가 왜 생기는지는 보여 주지 못하기 때문에","correct":true},{"t":"제도가 있다는 것은 문제가 생기는 까닭을 말해 주기 때문에","mis":"K6-2-u3-X19"}],"mis":"K6-2-u3-X19","explanation":["제도는 이미 나선 답이에요.","근거는 이유를 보여 주어야 해요.","해결 방안은 그 뒤의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#15','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C13',2,'ox','auto','가장 타당한 영상을 고르면 그 활동은 끝나요.',ARRAY['K6-2-u3-X12']::text[],false,'{"seq":15,"concept":"K6-2-u3-C13","difficulty":2,"kind":"ox","stem":"가장 타당한 영상을 고르면 그 활동은 끝나요.","answer":"X","reason_options":[{"t":"왜 그것을 골랐는지 말로 세울 수 있을 때 끝나기 때문에","correct":true},{"t":"고르는 것이 평가의 끝이기 때문에","mis":"K6-2-u3-X12"}],"mis":"K6-2-u3-X12","explanation":["고르는 것이 끝이 아니에요.","판단한 까닭을 말로 세워야 해요.","그래야 친구가 따라올 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#16','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C14',2,'match','auto','낱말과 그 발음을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"K6-2-u3-C14","difficulty":2,"kind":"match","stem":"낱말과 그 발음을 알맞게 이으세요.","pairs":[{"l":"넣고","r":"[너코]"},{"l":"넣는","r":"[넌는]"},{"l":"넣어","r":"[너어]"}],"mis":"K6-2-u3-X23","explanation":["ㄱ 앞에서는 합쳐 ㅋ이 돼요.","ㄴ 앞에서는 ㄴ이 돼요.","모음 앞에서는 ㅎ 소리가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#17','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C7',3,'error','auto','윤채의 발표를 평가한 말이에요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X20','K6-2-u3-X11','K6-2-u3-X14']::text[],false,'{"seq":17,"concept":"K6-2-u3-C7","difficulty":3,"kind":"error","stem":"윤채의 발표를 평가한 말이에요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"시온 — 「둘째 이유가 약하니 윤채의 주장은 틀렸어.」","correct":true,"mis_target":"K6-2-u3-X20"},{"t":"마루 — 「주장은 오늘 바로 해 볼 수 있고, 측정한 수치는 확인할 수 있는 근거야.」","mis":"K6-2-u3-X11"},{"t":"이든 — 「둘째 이유와 근거는 느낌이라 조사 자료로 바꾸면 좋겠어.」","mis":"K6-2-u3-X14"}],"explanation":["마루는 타당한 점을 먼저 짚었어요.","이든은 고칠 방법을 말했어요.","시온은 하나가 약하다고 전체를 버렸어요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#18','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',3,'mc','auto','장면 2 「걸으며 화면을 보는 학생이 생각보다 많다」는 무엇을 보여 주는 자료인가요?',ARRAY['K6-2-u3-X18','K6-2-u3-X19','K6-2-u3-X08']::text[],false,'{"seq":18,"concept":"K6-2-u3-C12","difficulty":3,"kind":"mc","stem":"장면 2 「걸으며 화면을 보는 학생이 생각보다 많다」는 무엇을 보여 주는 자료인가요?","options":[{"t":"문제의 규모 — 그것만으로는 왜 위험한지를 보여 주지 못한다","correct":true},{"t":"위험한 까닭","mis":"K6-2-u3-X18"},{"t":"문제의 해결 방안","mis":"K6-2-u3-X19"},{"t":"만든 사람의 느낌","mis":"K6-2-u3-X08"}],"explanation":["많다는 것은 크기예요.","왜 위험한지는 장면 1·3이 보여 줘요.","규모만으로는 까닭이 되지 않아요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#19','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',3,'ox','auto','「밤이 너무 밝습니다」의 근거 ② 그래프는 이유 ②와 관련이 있어요.',ARRAY['K6-2-u3-X10']::text[],false,'{"seq":19,"concept":"K6-2-u3-C12","difficulty":3,"kind":"ox","stem":"「밤이 너무 밝습니다」의 근거 ② 그래프는 이유 ②와 관련이 있어요.","answer":"O","reason_options":[{"t":"밤 불빛이 해마다 늘고 있다는 이유 ②를 그래프가 그대로 보여 주기 때문에","correct":true},{"t":"그래프는 어떤 이유와도 관련이 없기 때문에","mis":"K6-2-u3-X10"}],"mis":"K6-2-u3-X10","explanation":["근거 ②는 이유 ②를 잘 보여 줘요.","약한 것은 이유 ② 자체예요.","근거와 이유를 따로 따져요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#20','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C6',3,'mc','auto','「층마다 승강기를 기다린 시간을 잰 표」가 뒷받침하는 이유는 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X06']::text[],false,'{"seq":20,"concept":"K6-2-u3-C6","difficulty":3,"kind":"mc","stem":"「층마다 승강기를 기다린 시간을 잰 표」가 뒷받침하는 이유는 어느 것인가요?","options":[{"t":"이유 ① — 꼭 필요한 사람이 오래 기다리게 된다","correct":true},{"t":"이유 ② — 몸을 움직일 좋은 기회이다","mis":"K6-2-u3-X01"},{"t":"이유 ③ — 더 멋있어 보인다","mis":"K6-2-u3-X01"},{"t":"어느 이유와도 관련이 없다","mis":"K6-2-u3-X06"}],"explanation":["기다린 시간은 오래 기다린다는 것을 보여 줘요.","그래서 이유 ①의 근거예요.","이유 ②는 안내 자료가 받쳐 줘요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#21','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C13',3,'mc','auto','「물이 오는 길」을 다루는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X21']::text[],false,'{"seq":21,"concept":"K6-2-u3-C13","difficulty":3,"kind":"mc","stem":"「물이 오는 길」을 다루는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"주장이 없는 정보 영상이라 평가표에서 빼고, 물에 대해 알아보는 자료로 쓸 수 있다","correct":true},{"t":"근거가 약하니 △로 표시한다","mis":"K6-2-u3-X21"},{"t":"주장이 없으니 가장 타당한 영상이다","mis":"K6-2-u3-X21"},{"t":"재미있으니 ◎로 표시한다","mis":"K6-2-u3-X21"}],"explanation":["알려 주는 영상은 주장이 없어요.","평가표로 잴 수 없어요.","그래도 정보를 얻는 데는 쓸 수 있어요."],"asset":{"type":"passage","lines":["영상 1 「수도꼭지 삼십 초」 — 주장: 이를 닦는 동안에는 수도꼭지를 잠그자.","이유: 잠그지 않으면 쓰지도 않는 물이 그대로 흘러가기 때문이다.","근거: 잠갔을 때와 잠그지 않았을 때 받아 낸 물의 양을 나란히 보여 준 화면","영상 2 「물이 오는 길」 — 강에서 정수장을 지나 집까지 물이 오는 과정을 알려 준다.","무엇을 하자는 말은 나오지 않는다.","영상 3 「우리 집 물 쓰기 도전」 — 주장: 물을 아껴 쓰자.","이유: 물을 아끼면 뿌듯하기 때문이다.","근거: 도전을 해 본 만든 사람의 소감"],"title":"「물 아껴 쓰기」를 다룬 영상 세 편"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#22','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C2',3,'ox','auto','「어떤 영상이든 잘못이 있게 마련이야.」라고 미리 정하고 보는 것이 비판적으로 보는 거예요.',ARRAY['K6-2-u3-X02']::text[],false,'{"seq":22,"concept":"K6-2-u3-C2","difficulty":3,"kind":"ox","stem":"「어떤 영상이든 잘못이 있게 마련이야.」라고 미리 정하고 보는 것이 비판적으로 보는 거예요.","answer":"X","reason_options":[{"t":"잘못이 있다고 미리 정하는 것은 따져 보기 전에 판단한 것이기 때문에","correct":true},{"t":"어디든 잘못을 찾아야 비판한 것이기 때문에","mis":"K6-2-u3-X02"}],"mis":"K6-2-u3-X02","explanation":["비판은 따져 본 뒤에 판단해요.","미리 정하면 의심이에요.","맞는 것은 맞다고 말할 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#23','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',4,'mc','auto','「걸을 땐, 고개를 들어요」를 평가한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X18','K6-2-u3-X16']::text[],false,'{"seq":23,"concept":"K6-2-u3-C12","difficulty":4,"kind":"mc","stem":"「걸을 땐, 고개를 들어요」를 평가한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장은 실천 가능하고 장면 1 · 3이 위험한 순간을 보여 주지만, 장면 2 조사는 규모만 보여 주며 북소리와 되풀이 자막은 타당성과 관계없다","correct":true},{"t":"북소리와 자막이 세서 가장 타당한 영상이다","mis":"K6-2-u3-X17"},{"t":"조사 화면이 있으니 모든 자리가 튼튼하다","mis":"K6-2-u3-X18"},{"t":"주장을 말로 하지 않으니 평가할 수 없다","mis":"K6-2-u3-X16"}],"explanation":["타당한 점을 먼저 세어요.","규모만 보여 주는 자료는 약한 자리예요.","강조의 세기는 타당성과 따로예요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#24','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C9',4,'essay','teacher','「걸을 땐, 고개를 들어요」에서 제목 · 제시한 자료 · 강조하는 표현을 하나씩 찾아 쓰고 주장을 한 문장으로 쓰세요. 그리고 장면 4의 강조가 이 주장의 타당성을 알려 주지 못하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C9","difficulty":4,"kind":"essay","stem":"「걸을 땐, 고개를 들어요」에서 제목 · 제시한 자료 · 강조하는 표현을 하나씩 찾아 쓰고 주장을 한 문장으로 쓰세요. 그리고 장면 4의 강조가 이 주장의 타당성을 알려 주지 못하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 제목 — 「걸을 땐, 고개를 들어요」. 자료 — 학교 앞에서 걸으며 화면을 보는 학생이 많다는 조사 화면. 강조 — 세 번 되풀이되는 빨간 자막 「멈춰!」와 점점 커지는 북소리. 주장 — 걸을 때는 화면을 보지 말고 고개를 들자. 장면 4의 강조는 만든 사람이 「멈춰」를 가장 하고 싶은 말로 여긴다는 것만 알려 줄 뿐이다. 주장이 타당한지는 장면 1·3과 조사 화면이 걸으며 화면을 보면 위험하다는 이유를 정말 보여 주는지로 따로 따져야 한다.","scoring_points":["제목·자료·강조를 하나씩 바르게 찾았는가","주장을 한 문장으로 썼는가","강조와 타당성이 다른 까닭과 따지는 방법을 썼는가"]},"explanation":["셋을 합쳐 주장을 세워요.","강조는 실마리예요.","타당성은 자료로 따져요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_b#25','kor',6,2,'u3','','g6_2_kor_u3_review_b','unit_review','K6-2-u3-C12',4,'essay','teacher','「밤이 너무 밝습니다」를 예로 들어, 이유나 근거 하나가 약하다고 주장 전체를 틀렸다고 하면 안 되는 까닭을 쓰고, 그 카드 뉴스를 평가하는 말을 「주장은 … 다만 …」의 꼴로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C12","difficulty":4,"kind":"essay","stem":"「밤이 너무 밝습니다」를 예로 들어, 이유나 근거 하나가 약하다고 주장 전체를 틀렸다고 하면 안 되는 까닭을 쓰고, 그 카드 뉴스를 평가하는 말을 「주장은 … 다만 …」의 꼴로 쓰세요.","answer_guide":{"answer":"예: 이유 ②와 근거 ③이 약해도 주장은 가치 있고 실천 가능하며, 이유 ①·③과 근거 ①·②는 튼튼하다. 약한 자리는 고칠 자리이지 주장 전체를 무너뜨리는 것이 아니다. 평가하는 말 — 「주장은 가치 있고 근거 두 개는 튼튼해. 다만 이유 ②는 늘어서 무엇이 나빠지는지 말하도록, 근거 ③은 생물이 어지럽혀지는 모습을 보여 주는 자료로 바꾸면 좋겠어.」","scoring_points":["튼튼한 자리와 약한 자리를 함께 짚었는가","약한 자리가 주장 전체를 틀리게 하지 않는 까닭을 썼는가","「주장은 … 다만 …」 꼴로 고칠 방법까지 썼는가"]},"explanation":["하나가 약하다고 전체가 틀린 것은 아니에요.","타당한 점을 먼저 말해요.","약한 자리는 고칠 방법과 함께 말해요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#1','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C1',1,'ox','auto','근거는 이유를 뒷받침하는 자료나 사실이에요.',ARRAY['K6-2-u3-X01']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"ox","stem":"근거는 이유를 뒷받침하는 자료나 사실이에요.","answer":"O","reason_options":[{"t":"근거가 있어야 이유가 사실인지 확인할 수 있기 때문에","correct":true},{"t":"근거는 주장을 다른 말로 한 번 더 말한 것이기 때문에","mis":"K6-2-u3-X01"}],"mis":"K6-2-u3-X01","explanation":["근거는 이유를 받쳐 줘요.","자료나 사실이어야 해요.","주장을 되풀이한 말은 근거가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#2','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C2',1,'sa','auto','옳고 그른지를 제대로 따져 보며 보는 것을 「○○○으로 본다」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"sa","stem":"옳고 그른지를 제대로 따져 보며 보는 것을 「○○○으로 본다」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["비판적"],"explanation":["무조건 믿지 않는 것이 아니에요.","무조건 의심하는 것도 아니에요.","따져 보며 보는 것이에요."],"mis":"K6-2-u3-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#3','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C3',1,'sa','auto','이유나 근거를 놓치지 않도록 적으며 듣는 것을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u3-C3","difficulty":1,"kind":"sa","stem":"이유나 근거를 놓치지 않도록 적으며 듣는 것을 「○○하며 듣기」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["메모"],"explanation":["적으며 들으면 메모하며 듣기예요.","간추리며 들으면 요약하며 듣기예요.","내 생각과 견주면 견주며 듣기예요."],"mis":"K6-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#4','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C4',1,'ox','auto','「우리 모두 훌륭한 사람이 됩시다」는 실천하기 쉬운 주장이에요.',ARRAY['K6-2-u3-X05']::text[],false,'{"seq":4,"concept":"K6-2-u3-C4","difficulty":1,"kind":"ox","stem":"「우리 모두 훌륭한 사람이 됩시다」는 실천하기 쉬운 주장이에요.","answer":"X","reason_options":[{"t":"말은 크지만 무엇부터 해야 할지 알 수 없기 때문에","correct":true},{"t":"누구나 바라는 일이기 때문에","mis":"K6-2-u3-X05"}],"mis":"K6-2-u3-X05","explanation":["누구나 바라는 일이어도","언제 무엇을 할지 없으면 실천하기 어려워요.","실천 가능해야 가치 있는 주장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#5','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C6',1,'mc','auto','근거로 쓰기 어려운 것은 어느 것인가요?',ARRAY['K6-2-u3-X08']::text[],false,'{"seq":5,"concept":"K6-2-u3-C6","difficulty":1,"kind":"mc","stem":"근거로 쓰기 어려운 것은 어느 것인가요?","options":[{"t":"말한 사람의 느낌이나 짐작","correct":true},{"t":"조사한 표","mis":"K6-2-u3-X08"},{"t":"그 일을 겪은 사람의 면담 자료","mis":"K6-2-u3-X08"},{"t":"실제로 있었던 사례","mis":"K6-2-u3-X08"}],"explanation":["표·면담 자료·사례는 근거 자료예요.","느낌이나 짐작은 근거가 되지 못해요.","근거는 객관적이어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#6','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C8',1,'ox','auto','「나는 새 책 냄새를 좋아한다」는 객관적인 근거예요.',ARRAY['K6-2-u3-X08']::text[],false,'{"seq":6,"concept":"K6-2-u3-C8","difficulty":1,"kind":"ox","stem":"「나는 새 책 냄새를 좋아한다」는 객관적인 근거예요.","answer":"X","reason_options":[{"t":"말한 사람 혼자만의 느낌이라 누가 보아도 그러한 것이 아니기 때문에","correct":true},{"t":"말한 사람이 직접 겪은 것이라 언제나 객관적이기 때문에","mis":"K6-2-u3-X08"}],"mis":"K6-2-u3-X08","explanation":["좋아하는 것은 사람마다 달라요.","혼자만의 느낌은 주관적이에요.","확인할 수 있는 자료로 바꾸어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#7','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C10',1,'ox','auto','빨간 자막 「멈춰!」가 세 번 되풀이되니 「걸을 땐, 고개를 들어요」의 주장은 틀림없이 타당해요.',ARRAY['K6-2-u3-X17']::text[],false,'{"seq":7,"concept":"K6-2-u3-C10","difficulty":1,"kind":"ox","stem":"빨간 자막 「멈춰!」가 세 번 되풀이되니 「걸을 땐, 고개를 들어요」의 주장은 틀림없이 타당해요.","answer":"X","reason_options":[{"t":"되풀이는 하고 싶은 말을 알려 줄 뿐 타당한지는 자료로 따로 따져야 하기 때문에","correct":true},{"t":"되풀이가 많을수록 주장이 옳기 때문에","mis":"K6-2-u3-X17"}],"mis":"K6-2-u3-X17","explanation":["되풀이 자막은 강조예요.","강조는 주장을 찾는 실마리예요.","타당성은 자료로 따져요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#8','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C14',1,'sa','auto','「좋아」를 소리 나는 대로 쓰세요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K6-2-u3-C14","difficulty":1,"kind":"sa","stem":"「좋아」를 소리 나는 대로 쓰세요. 두 글자로 쓰세요.","answer":["조아","[조아]"],"explanation":["받침 ㅎ 뒤에 모음이 왔어요.","모음 앞에서는 ㅎ 소리를 내지 않아요.","그래서 [조아]예요."],"mis":"K6-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#9','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C3',2,'mc','auto','윤채의 말을 요약하며 들은 메모로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":9,"concept":"K6-2-u3-C3","difficulty":2,"kind":"mc","stem":"윤채의 말을 요약하며 들은 메모로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장 — 쉬는 시간마다 창문 열기 / 이유 — 공기가 탁해짐, 기분이 상쾌해짐 / 근거 — 측정 수치, 덜 졸린 경험","correct":true},{"t":"윤채는 목소리가 또렷했다","mis":"K6-2-u3-X04"},{"t":"창문 · 공기 · 졸림","mis":"K6-2-u3-X04"},{"t":"창문을 열자는 말에 나는 반대한다","mis":"K6-2-u3-X04"}],"explanation":["요약하며 듣기는 주장·이유·근거로 간추리는 것이에요.","낱말만 적으면 무엇이 무엇인지 몰라요.","목소리나 내 찬반은 요약이 아니에요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#10','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C7',2,'ox','auto','윤채의 발표는 둘째 이유가 약하니 평가할 때 그것부터 짚어야 해요.',ARRAY['K6-2-u3-X11']::text[],false,'{"seq":10,"concept":"K6-2-u3-C7","difficulty":2,"kind":"ox","stem":"윤채의 발표는 둘째 이유가 약하니 평가할 때 그것부터 짚어야 해요.","answer":"X","reason_options":[{"t":"주장이 실천 가능하고 첫째 이유와 근거가 튼튼하다는 타당한 점을 먼저 찾아야 하기 때문에","correct":true},{"t":"평가는 약한 곳을 찾는 일이기 때문에","mis":"K6-2-u3-X11"}],"mis":"K6-2-u3-X11","explanation":["타당한 점을 먼저 찾아요.","그다음 보완할 점을 찾아요.","그래야 무엇을 살릴지 보여요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#11','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C8',2,'mc','auto','근거를 말할 때 「○○ 소식지에 실린 내용입니다.」처럼 덧붙이는 것을 무엇이라고 하나요?',ARRAY['K6-2-u3-X14','K6-2-u3-X01']::text[],false,'{"seq":11,"concept":"K6-2-u3-C8","difficulty":2,"kind":"mc","stem":"근거를 말할 때 「○○ 소식지에 실린 내용입니다.」처럼 덧붙이는 것을 무엇이라고 하나요?","options":[{"t":"출처를 밝히기","correct":true},{"t":"감정에 호소하기","mis":"K6-2-u3-X14"},{"t":"주장을 되풀이하기","mis":"K6-2-u3-X01"},{"t":"이유를 바꾸기","mis":"K6-2-u3-X01"}],"explanation":["어디에서 나온 자료인지 말하는 것이에요.","출처를 밝히면 확인할 수 있어요.","근거를 믿을 수 있게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#12','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C10',2,'mc','auto','장면 4의 북소리와 되풀이 자막이 알려 주는 것은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X21']::text[],false,'{"seq":12,"concept":"K6-2-u3-C10","difficulty":2,"kind":"mc","stem":"장면 4의 북소리와 되풀이 자막이 알려 주는 것은 어느 것인가요?","options":[{"t":"만든 사람이 「멈춰」를 가장 하고 싶은 말로 여긴다는 것","correct":true},{"t":"주장이 사실이라는 것","mis":"K6-2-u3-X17"},{"t":"주장이 타당하다는 것","mis":"K6-2-u3-X17"},{"t":"영상이 재미있다는 것","mis":"K6-2-u3-X21"}],"explanation":["강조는 하고 싶은 말을 가리켜요.","사실인지·타당한지는 알려 주지 못해요.","재미와 타당성도 달라요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#13','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C5',2,'ox','auto','「가까운 층은 계단으로」에서 타당하지 않은 이유 ③을 지우면 할 일이 끝나요.',ARRAY['K6-2-u3-X11']::text[],false,'{"seq":13,"concept":"K6-2-u3-C5","difficulty":2,"kind":"ox","stem":"「가까운 층은 계단으로」에서 타당하지 않은 이유 ③을 지우면 할 일이 끝나요.","answer":"X","reason_options":[{"t":"그 자리에 주장을 더 잘 뒷받침하는 이유를 놓아 보아야 하기 때문에","correct":true},{"t":"타당하지 않은 이유는 지우기만 하면 되기 때문에","mis":"K6-2-u3-X11"}],"mis":"K6-2-u3-X11","explanation":["지우는 것으로 끝내지 않아요.","더 나은 이유를 생각해 보아요.","예: 승강기를 덜 쓰면 전기를 아낄 수 있다."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#14','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C12',2,'mc','auto','카드 뉴스에서 약한 자리를 찾았을 때 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-2-u3-X20','K6-2-u3-X03']::text[],false,'{"seq":14,"concept":"K6-2-u3-C12","difficulty":2,"kind":"mc","stem":"카드 뉴스에서 약한 자리를 찾았을 때 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「주장은 가치 있어. 다만 이 근거는 이렇게 바꾸면 좋겠어.」","correct":true},{"t":"「약한 데가 있으니 다 믿을 수 없어.」","mis":"K6-2-u3-X20"},{"t":"「처음부터 틀린 카드 뉴스야.」","mis":"K6-2-u3-X20"},{"t":"「약한 데는 그냥 모른 척하자.」","mis":"K6-2-u3-X03"}],"explanation":["평가는 고칠 자리를 짚어 주는 일이에요.","타당한 점은 살려요.","약한 자리는 고칠 방법과 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#15','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C13',2,'mc','auto','손 씻기에 대한 영상을 찾을 때 알맞은 찾는 말은 어느 것인가요?',ARRAY['K6-2-u3-X22']::text[],false,'{"seq":15,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"손 씻기에 대한 영상을 찾을 때 알맞은 찾는 말은 어느 것인가요?","options":[{"t":"「손 씻기 방법 어린이 교육용」","correct":true},{"t":"「손」","mis":"K6-2-u3-X22"},{"t":"「충격 손 세균 실화」","mis":"K6-2-u3-X22"},{"t":"「아무거나 재밌는 거」","mis":"K6-2-u3-X22"}],"explanation":["구체적인 말로 찾아요.","「어린이·교육용」을 붙이면 볼 만한 영상이 나와요.","자극적인 말은 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#16','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C14',2,'ox','auto','「놓아」는 [노하]로 발음해요.',ARRAY['K6-2-u3-X23']::text[],false,'{"seq":16,"concept":"K6-2-u3-C14","difficulty":2,"kind":"ox","stem":"「놓아」는 [노하]로 발음해요.","answer":"X","reason_options":[{"t":"받침 ㅎ 뒤에 모음이 오면 ㅎ 소리를 내지 않아 [노아]로 발음하기 때문에","correct":true},{"t":"받침 ㅎ은 언제나 그대로 소리 내기 때문에","mis":"K6-2-u3-X23"}],"mis":"K6-2-u3-X23","explanation":["받침 ㅎ 뒤에 모음이 왔어요.","이때는 ㅎ 소리를 내지 않아요.","그래서 [노아]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#17','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C5',3,'ox','auto','윤채의 둘째 이유는 주장과 관련이 없어서 약해요.',ARRAY['K6-2-u3-X06']::text[],false,'{"seq":17,"concept":"K6-2-u3-C5","difficulty":3,"kind":"ox","stem":"윤채의 둘째 이유는 주장과 관련이 없어서 약해요.","answer":"X","reason_options":[{"t":"관련은 있지만 느낌이라 많은 사람이 받아들이기 어려워 약하기 때문에","correct":true},{"t":"기분은 창문을 여는 일과 아무 관련이 없기 때문에","mis":"K6-2-u3-X06"}],"mis":"K6-2-u3-X06","explanation":["창문을 열면 상쾌하다는 것은 창문 열기와 이어져요.","그러니 관련은 있어요.","약한 까닭은 받아들일 만하지 않다는 것이에요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#18','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C9',3,'ox','auto','「걸을 땐, 고개를 들어요」는 「화면을 보지 맙시다」라고 직접 말하지 않으니 주장이 없는 영상이에요.',ARRAY['K6-2-u3-X16']::text[],false,'{"seq":18,"concept":"K6-2-u3-C9","difficulty":3,"kind":"ox","stem":"「걸을 땐, 고개를 들어요」는 「화면을 보지 맙시다」라고 직접 말하지 않으니 주장이 없는 영상이에요.","answer":"X","reason_options":[{"t":"제목과 자료와 강조된 장면을 합치면 주장이 드러나기 때문에","correct":true},{"t":"주장은 문장으로 말해야만 있는 것이기 때문에","mis":"K6-2-u3-X16"}],"mis":"K6-2-u3-X16","explanation":["영상은 주장을 직접 말하지 않는 경우가 많아요.","보는 사람이 스스로 이어 붙여요.","제목과 마지막 자막이 주장을 가리켜요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#19','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C12',3,'mc','auto','이유 ②는 약한데 근거 ②는 튼튼하다고 볼 수 있는 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X03','K6-2-u3-X12']::text[],false,'{"seq":19,"concept":"K6-2-u3-C12","difficulty":3,"kind":"mc","stem":"이유 ②는 약한데 근거 ②는 튼튼하다고 볼 수 있는 까닭은 어느 것인가요?","options":[{"t":"근거 ②는 이유 ②를 잘 보여 주지만, 이유 ② 자체가 왜 줄여야 하는지를 말하지 못해서","correct":true},{"t":"둘은 같은 것이라 함께 약하다","mis":"K6-2-u3-X01"},{"t":"근거 ②가 그래프라서 무조건 옳다","mis":"K6-2-u3-X03"},{"t":"이유 ②가 짧아서","mis":"K6-2-u3-X12"}],"explanation":["근거는 이유와의 관계로 재요.","이유는 주장과의 관계로 재요.","재는 자가 달라서 판단도 달라요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#20','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C7',3,'ox','auto','「가까운 층은 계단으로」는 이유 ③이 약하니 평가할 가치가 없어요.',ARRAY['K6-2-u3-X20']::text[],false,'{"seq":20,"concept":"K6-2-u3-C7","difficulty":3,"kind":"ox","stem":"「가까운 층은 계단으로」는 이유 ③이 약하니 평가할 가치가 없어요.","answer":"X","reason_options":[{"t":"이유 ①·②와 두 근거는 확인할 수 있어 타당한 점이 많기 때문에","correct":true},{"t":"이유 하나가 약하면 카드 뉴스 전체를 버려야 하기 때문에","mis":"K6-2-u3-X20"}],"mis":"K6-2-u3-X20","explanation":["타당한 점을 먼저 세어요.","이유 ①·②와 두 근거는 튼튼해요.","이유 ③만 고치면 돼요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#21','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C13',3,'ox','auto','영상 평가표에 「거친 말이 없는가」 같은 기준을 더하고 싶으면, 내용의 타당성을 먼저 평가한 뒤에 더해요.',ARRAY['K6-2-u3-X21']::text[],false,'{"seq":21,"concept":"K6-2-u3-C13","difficulty":3,"kind":"ox","stem":"영상 평가표에 「거친 말이 없는가」 같은 기준을 더하고 싶으면, 내용의 타당성을 먼저 평가한 뒤에 더해요.","answer":"O","reason_options":[{"t":"표현의 문제는 내용의 타당성을 충분히 평가한 다음에 살펴야 하기 때문에","correct":true},{"t":"표현이 알맞으면 내용도 저절로 타당하기 때문에","mis":"K6-2-u3-X21"}],"mis":"K6-2-u3-X21","explanation":["표현도 살필 수 있어요.","그러나 내용이 먼저예요.","차례를 바꾸면 재미가 타당성을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#22','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C13',3,'error','auto','단원을 마치며 다짐한 말이에요. 지키기 어려운 다짐을 한 친구는 누구인가요?',ARRAY['K6-2-u3-X12']::text[],false,'{"seq":22,"concept":"K6-2-u3-C13","difficulty":3,"kind":"error","stem":"단원을 마치며 다짐한 말이에요. 지키기 어려운 다짐을 한 친구는 누구인가요?","options":[{"t":"하늘 — 「앞으로 열심히 따져 보겠다.」","correct":true,"mis_target":"K6-2-u3-X12"},{"t":"지율 — 「오늘 저녁에 본 영상 하나를 골라 주장과 근거를 적어 보겠다.」","mis":"K6-2-u3-X12"},{"t":"로하 — 「내일 학급 회의에서 친구 주장의 이유를 메모하며 듣겠다.」","mis":"K6-2-u3-X12"}],"explanation":["지율과 로하는 언제·어디에서·무엇을 할지 정했어요.","하늘의 다짐은 무엇부터 할지 알 수 없어요.","다짐도 실천 가능해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#23','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C11',4,'mc','auto','윤채의 말 · 「걸을 땐, 고개를 들어요」 · 「가까운 층은 계단으로」를 함께 평가할 때 공통으로 쓰는 기준은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X21','K6-2-u3-X03']::text[],false,'{"seq":23,"concept":"K6-2-u3-C11","difficulty":4,"kind":"mc","stem":"윤채의 말 · 「걸을 땐, 고개를 들어요」 · 「가까운 층은 계단으로」를 함께 평가할 때 공통으로 쓰는 기준은 어느 것인가요?","options":[{"t":"주장은 가치 있고 중요한가 · 이유는 주장을 뒷받침하는가 · 근거는 이유를 뒷받침하는가","correct":true},{"t":"말은 목소리, 영상은 음악, 카드 뉴스는 그림","mis":"K6-2-u3-X17"},{"t":"말의 길이 · 영상 길이 · 카드 장 수","mis":"K6-2-u3-X21"},{"t":"누가 만들었는가 하나만","mis":"K6-2-u3-X03"}],"explanation":["담는 그릇은 셋이에요.","따지는 기준은 하나예요.","목소리·음악·그림은 표현일 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#24','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C5',4,'essay','teacher','「가까운 층은 계단으로」의 이유 ③이 왜 타당하지 않은지 이유를 재는 두 물음에 대어 쓰고, 이유 ③ 자리에 놓을 더 나은 이유를 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C5","difficulty":4,"kind":"essay","stem":"「가까운 층은 계단으로」의 이유 ③이 왜 타당하지 않은지 이유를 재는 두 물음에 대어 쓰고, 이유 ③ 자리에 놓을 더 나은 이유를 두 가지 쓰세요.","answer_guide":{"answer":"예: 이유 ③은 계단으로 다니자는 주장과 관련은 있지만, 멋있어 보이는 것은 사람마다 달라 많은 사람이 받아들이기 어렵다. 그래서 두 물음 가운데 하나만 통과한다. 더 나은 이유 — 승강기를 덜 쓰면 전기를 아낄 수 있기 때문이다. 가까운 층은 승강기를 기다리는 것보다 계단이 오히려 빠르기 때문이다.","scoring_points":["주장과 관련 있는지 따졌는가","많은 사람이 받아들일 만한지 따졌는가","두 물음을 통과하는 이유를 두 가지 썼는가"]},"explanation":["관련은 있어요.","받아들일 만하지 않아요.","지우지 말고 더 나은 이유를 놓아요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_c#25','kor',6,2,'u3','','g6_2_kor_u3_review_c','unit_review','K6-2-u3-C14',4,'essay','teacher','「쌓고」 · 「쌓는」 · 「쌓아」를 넣어 문장을 하나씩 만들고, 각 낱말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C14","difficulty":4,"kind":"essay","stem":"「쌓고」 · 「쌓는」 · 「쌓아」를 넣어 문장을 하나씩 만들고, 각 낱말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「블록을 높이 쌓고 사진을 찍었다.」에서 「쌓고」는 [싸코], 「모래성을 쌓는 아이들이 있다.」에서 「쌓는」은 [싼는], 「돌을 차곡차곡 쌓아 올렸다.」에서 「쌓아」는 [싸아]로 소리 난다. 받침 ㅎ 뒤에 ㄱ이 오면 합쳐서 ㅋ으로, ㄴ이 오면 ㄴ으로 소리 나고, 모음이 오면 ㅎ 소리를 내지 않기 때문이다.","scoring_points":["세 낱말을 넣어 문장을 하나씩 만들었는가","[싸코]·[싼는]·[싸아]로 바르게 썼는가","뒤에 오는 소리에 따른 까닭을 썼는가"]},"explanation":["ㄱ 앞 — 합쳐서 ㅋ.","ㄴ 앞 — ㄴ으로.","모음 앞 — 소리 없음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#1','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C1',1,'mc','auto','「이유」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X01','K6-2-u3-X07']::text[],false,'{"seq":1,"concept":"K6-2-u3-C1","difficulty":1,"kind":"mc","stem":"「이유」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"왜 그렇게 주장하는지를 설명하는 말","correct":true},{"t":"어떤 주제에 대한 자신의 의견을 드러내는 말","mis":"K6-2-u3-X01"},{"t":"이유를 뒷받침하는 자료나 사실","mis":"K6-2-u3-X01"},{"t":"말한 사람이 좋아하는 것","mis":"K6-2-u3-X07"}],"explanation":["주장은 의견이에요.","이유는 그 의견의 까닭이에요.","근거는 이유를 받쳐 주는 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#2','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C2',1,'mc','auto','주장을 따져 보며 들었을 때 좋은 점은 어느 것인가요?',ARRAY['K6-2-u3-X02','K6-2-u3-X04']::text[],false,'{"seq":2,"concept":"K6-2-u3-C2","difficulty":1,"kind":"mc","stem":"주장을 따져 보며 들었을 때 좋은 점은 어느 것인가요?","options":[{"t":"믿을 만한 정보를 골라 쓸 수 있다","correct":true},{"t":"말한 사람과 다툴 수 있다","mis":"K6-2-u3-X02"},{"t":"모든 주장이 틀렸다는 것을 알게 된다","mis":"K6-2-u3-X02"},{"t":"듣는 시간이 짧아진다","mis":"K6-2-u3-X04"}],"explanation":["따져 보면 사실인 것과 아닌 것을 가를 수 있어요.","그래서 믿을 만한 정보를 골라 써요.","따지는 것은 다투는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#3','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C3',1,'mc','auto','주장하는 말을 들을 때 하지 않아야 할 일은 어느 것인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":3,"concept":"K6-2-u3-C3","difficulty":1,"kind":"mc","stem":"주장하는 말을 들을 때 하지 않아야 할 일은 어느 것인가요?","options":[{"t":"말이 끝나기 전에 결론을 미리 정해 둔다","correct":true},{"t":"주장 · 이유 · 근거로 나누어 간추린다","mis":"K6-2-u3-X04"},{"t":"내 생각과 견주어 본다","mis":"K6-2-u3-X04"},{"t":"이유와 근거를 적는다","mis":"K6-2-u3-X04"}],"explanation":["간추리기·견주기·적기는 모두 알맞은 방법이에요.","결론은 다 듣고 따진 뒤에 내려요.","미리 정하면 따질 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#4','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C4',1,'sa','auto','주장이 가치 있으려면 문제 해결에 도움이 되고 ○○ 가능해야 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K6-2-u3-C4","difficulty":1,"kind":"sa","stem":"주장이 가치 있으려면 문제 해결에 도움이 되고 ○○ 가능해야 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["실천"],"explanation":["주장을 재는 물음은 두 가지예요.","도움이 되는가, 실천 가능한가.","「잠자기 전에 열 쪽씩」처럼 바로 할 수 있어야 해요."],"mis":"K6-2-u3-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#5','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C6',1,'ox','auto','근거로 나온 기사도 어디에서 나온 자료인지 한 번 더 살펴야 해요.',ARRAY['K6-2-u3-X09']::text[],false,'{"seq":5,"concept":"K6-2-u3-C6","difficulty":1,"kind":"ox","stem":"근거로 나온 기사도 어디에서 나온 자료인지 한 번 더 살펴야 해요.","answer":"O","reason_options":[{"t":"찾은 기사도 출처가 믿을 만한지 다시 따져 보아야 하기 때문에","correct":true},{"t":"기사에 나온 내용은 모두 사실이기 때문에","mis":"K6-2-u3-X09"}],"mis":"K6-2-u3-X09","explanation":["근거가 사실인지 따로 확인해요.","찾은 기사도 그대로 믿지 않아요.","어디에서 나온 자료인지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#6','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C8',1,'mc','auto','근거의 출처를 밝혀 말한 것은 어느 것인가요?',ARRAY['K6-2-u3-X13']::text[],false,'{"seq":6,"concept":"K6-2-u3-C8","difficulty":1,"kind":"mc","stem":"근거의 출처를 밝혀 말한 것은 어느 것인가요?","options":[{"t":"「우리 학교 도서관에서 지난달에 조사한 표입니다.」","correct":true},{"t":"「어디서 봤는데 다들 그렇대요.」","mis":"K6-2-u3-X13"},{"t":"「누가 그러던데 맞대요.」","mis":"K6-2-u3-X13"},{"t":"「제가 알기로는 그래요.」","mis":"K6-2-u3-X13"}],"explanation":["어디에서 언제 나온 자료인지 밝혀요.","그래야 듣는 사람이 확인할 수 있어요.","「어디서 봤는데」는 출처가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#7','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C9',1,'mc','auto','알려 주는 영상의 제목은 어느 것인가요?',ARRAY['K6-2-u3-X15']::text[],false,'{"seq":7,"concept":"K6-2-u3-C9","difficulty":1,"kind":"mc","stem":"알려 주는 영상의 제목은 어느 것인가요?","options":[{"t":"우리 동네 버스는 하루에 몇 번 다닐까","correct":true},{"t":"가까운 길은 걸어서 다닙시다","mis":"K6-2-u3-X15"},{"t":"오늘부터 휴대 전화를 내려놓읍시다","mis":"K6-2-u3-X15"},{"t":"쓰지 않는 불은 끕시다","mis":"K6-2-u3-X15"}],"explanation":["「~ㅂ시다」는 무엇을 하자고 이끄는 제목이에요.","「몇 번 다닐까」는 사실을 알려 주는 제목이에요.","영상마다 하는 일이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#8','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C11',1,'ox','auto','카드 뉴스는 그림과 짧은 글을 여러 장으로 이어 핵심만 빠르게 전해요.',ARRAY['K6-2-u3-X03']::text[],false,'{"seq":8,"concept":"K6-2-u3-C11","difficulty":1,"kind":"ox","stem":"카드 뉴스는 그림과 짧은 글을 여러 장으로 이어 핵심만 빠르게 전해요.","answer":"O","reason_options":[{"t":"그래서 빠진 것이 잘 보이지 않아 따져 보며 보아야 하기 때문에","correct":true},{"t":"그래서 따져 볼 필요 없이 빠르게 믿으면 되기 때문에","mis":"K6-2-u3-X03"}],"mis":"K6-2-u3-X03","explanation":["카드 뉴스는 짧고 빨라요.","짧을수록 빠진 것이 숨어요.","그래서 따져 보며 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#9','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C1',2,'sa','auto','윤채의 주장은 「쉬는 시간마다 교실 ○○을 열자」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u3-C1","difficulty":2,"kind":"sa","stem":"윤채의 주장은 「쉬는 시간마다 교실 ○○을 열자」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["창문"],"explanation":["윤채가 하자고 한 일을 찾아요.","첫 줄과 마지막 줄에 있어요.","「창문을 열자」예요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"},"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#10','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C4',2,'mc','auto','윤채의 주장이 실천 가능하다고 볼 수 있는 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X05','K6-2-u3-X03']::text[],false,'{"seq":10,"concept":"K6-2-u3-C4","difficulty":2,"kind":"mc","stem":"윤채의 주장이 실천 가능하다고 볼 수 있는 까닭은 어느 것인가요?","options":[{"t":"쉬는 시간 십 분에 창가에 앉은 사람부터 열자고 언제 · 누가 · 무엇을 할지 정했다","correct":true},{"t":"공기가 좋아지면 모두에게 좋기 때문이다","mis":"K6-2-u3-X05"},{"t":"윤채가 말을 잘하기 때문이다","mis":"K6-2-u3-X03"},{"t":"교실 창문이 크기 때문이다","mis":"K6-2-u3-X05"}],"explanation":["실천 가능하려면 언제 무엇을 할지 정해져 있어야 해요.","윤채는 쉬는 시간·창가 사람·창문 열기를 말했어요.","오늘 바로 할 수 있어요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#11','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C6',2,'error','auto','근거를 확인하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X09']::text[],false,'{"seq":11,"concept":"K6-2-u3-C6","difficulty":2,"kind":"error","stem":"근거를 확인하는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"윤슬 — 「누리 소통망에서 많이 퍼진 글이면 사실이야.」","correct":true,"mis_target":"K6-2-u3-X09"},{"t":"겸 — 「그 내용을 다룬 책을 찾아볼래.」","mis":"K6-2-u3-X09"},{"t":"나래 — 「찾은 기사도 어디에서 나온 건지 살펴볼래.」","mis":"K6-2-u3-X09"}],"explanation":["겸은 책을 찾아보았어요.","나래는 출처를 다시 살폈어요.","많이 퍼졌다고 사실인 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#12','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C9',2,'sa','auto','「걸을 땐, 고개를 들어요」 마지막 화면에 남은 자막은 「걸을 땐, ○○를 들어요」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u3-C9","difficulty":2,"kind":"sa","stem":"「걸을 땐, 고개를 들어요」 마지막 화면에 남은 자막은 「걸을 땐, ○○를 들어요」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["고개"],"explanation":["마지막에 소리가 멈춰요.","글자만 남아요.","가장 하고 싶은 말을 마지막에 두었어요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"},"mis":"K6-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#13','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C4',2,'match','auto','판단 기준과 그 기준이 재는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"K6-2-u3-C4","difficulty":2,"kind":"match","stem":"판단 기준과 그 기준이 재는 것을 알맞게 이으세요.","pairs":[{"l":"실천 가능한가","r":"주장"},{"l":"많은 사람이 받아들일 만한가","r":"이유"},{"l":"객관적인 사실이나 정보인가","r":"근거"}],"mis":"K6-2-u3-X01","explanation":["실천 가능성은 주장을 재요.","받아들일 만함은 이유를 재요.","객관성은 근거를 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#14','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C11',2,'sa','auto','카드 뉴스의 근거마다 「이게 그 ○○를 보여 주나?」를 물어요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"K6-2-u3-C11","difficulty":2,"kind":"sa","stem":"카드 뉴스의 근거마다 「이게 그 ○○를 보여 주나?」를 물어요. ○○에 알맞은 두 글자를 쓰세요.","answer":["이유"],"explanation":["근거는 이유를 받쳐 줘요.","그 이유를 정말 보여 주는지 물어요.","보여 주지 못하면 약한 근거예요."],"mis":"K6-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#15','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C13',2,'mc','auto','평가할 수 있는 영상인지 먼저 가려내는 까닭은 어느 것인가요?',ARRAY['K6-2-u3-X21','K6-2-u3-X15']::text[],false,'{"seq":15,"concept":"K6-2-u3-C13","difficulty":2,"kind":"mc","stem":"평가할 수 있는 영상인지 먼저 가려내는 까닭은 어느 것인가요?","options":[{"t":"주장이 없는 영상은 주장 · 이유 · 근거를 재는 평가표로 잴 수 없어서","correct":true},{"t":"긴 영상은 평가할 수 없어서","mis":"K6-2-u3-X21"},{"t":"음악이 없는 영상은 평가할 수 없어서","mis":"K6-2-u3-X21"},{"t":"모든 영상에는 주장이 있어서","mis":"K6-2-u3-X15"}],"explanation":["평가표는 주장·이유·근거를 재요.","알려 주는 영상에는 주장이 없어요.","그래서 먼저 가려내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#16','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C14',2,'sa','auto','「쌓는」을 소리 나는 대로 쓰세요. 두 글자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"K6-2-u3-C14","difficulty":2,"kind":"sa","stem":"「쌓는」을 소리 나는 대로 쓰세요. 두 글자로 쓰세요.","answer":["싼는","[싼는]"],"explanation":["받침 ㅎ 뒤에 ㄴ이 왔어요.","이때 ㅎ은 ㄴ으로 소리 나요.","그래서 [싼는]이에요."],"mis":"K6-2-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#17','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C7',3,'mc','auto','윤채의 발표를 평가 기준표로 판단한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X12','K6-2-u3-X20','K6-2-u3-X05']::text[],false,'{"seq":17,"concept":"K6-2-u3-C7","difficulty":3,"kind":"mc","stem":"윤채의 발표를 평가 기준표로 판단한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주장 ◎ — 실천 가능 / 이유 ○ — 첫째는 튼튼하나 둘째는 느낌 / 근거 ○ — 측정 수치는 객관적이나 졸린 경험은 주관적","correct":true},{"t":"모두 ◎ — 창문을 열자는 말이 마음에 든다","mis":"K6-2-u3-X12"},{"t":"모두 △ — 약한 데가 있다","mis":"K6-2-u3-X20"},{"t":"주장 △ — 창문은 누구나 열 수 있어 시시하다","mis":"K6-2-u3-X05"}],"explanation":["주장은 오늘 바로 할 수 있어요.","이유와 근거는 하나씩 튼튼하고 하나씩 약해요.","표시마다 까닭이 있어야 해요."],"asset":{"type":"passage","lines":["저는 쉬는 시간마다 교실 창문을 열자고 말하고 싶습니다.","첫째, 창문을 닫아 두면 교실 공기가 탁해져 머리가 무거워지기 때문입니다.","우리 반 공기 측정기로 재어 보니, 창문을 연 쉬는 시간 뒤에는","공기가 탁한 정도를 나타내는 수치가 눈에 띄게 내려갔습니다.","둘째, 창문을 열면 기분이 상쾌해지기 때문입니다.","저는 창문을 연 날 수업 시간에 덜 졸렸습니다.","쉬는 시간 십 분, 창가에 앉은 사람부터 창문을 열어 봅시다."],"title":"윤채의 주장하는 말 「창문을 여는 십 분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#18','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C10',3,'error','auto','「걸을 땐, 고개를 들어요」를 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X15']::text[],false,'{"seq":18,"concept":"K6-2-u3-C10","difficulty":3,"kind":"error","stem":"「걸을 땐, 고개를 들어요」를 보고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"한결 — 「북소리가 커서 무서웠어. 그러니 이 영상은 옳아.」","correct":true,"mis_target":"K6-2-u3-X17"},{"t":"소이 — 「장면 1과 3이 위험한 순간을 보여 주니 이유를 받쳐 줘.」","mis":"K6-2-u3-X15"},{"t":"재아 — 「마지막 자막을 보니 걸을 땐 고개를 들자는 주장이야.」","mis":"K6-2-u3-X15"}],"explanation":["소이는 자료가 이유를 받치는지 보았어요.","재아는 강조로 주장을 찾았어요.","한결은 강조의 세기를 타당성으로 여겼어요."],"asset":{"type":"passage","lines":["장면 1 — 화면을 보며 횡단보도 앞에 선 사람들. 신호가 바뀐 것을 늦게 알아챈다.","장면 2 — 학교 앞에서 조사한 화면. 걸으며 화면을 보는 학생이 생각보다 많다.","장면 3 — 다가오는 자전거 소리를 못 듣고 멈칫하는 아이를 가까이 잡는다.","장면 4 — 빨간 자막 「멈춰!」가 세 번 되풀이되고 북소리가 점점 커진다.","장면 5 — 소리가 멈추고 글자만 남는다. 「걸을 땐, 고개를 들어요」"],"title":"영상 「걸을 땐, 고개를 들어요」의 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#19','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C12',3,'error','auto','근거 ③을 고치자는 의견이에요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u3-X19','K6-2-u3-X13']::text[],false,'{"seq":19,"concept":"K6-2-u3-C12","difficulty":3,"kind":"error","stem":"근거 ③을 고치자는 의견이에요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"다올 — 「다른 나라의 제도도 덧붙이면 근거 ③이 튼튼해져.」","correct":true,"mis_target":"K6-2-u3-X19"},{"t":"리안 — 「곤충이 불빛 둘레를 맴도는 모습을 관찰한 기록으로 바꾸자.」","mis":"K6-2-u3-X19"},{"t":"하민 — 「새가 불빛 때문에 길을 헤맨다는 연구를 찾아 출처를 밝히자.」","mis":"K6-2-u3-X13"}],"explanation":["리안과 하민은 이유 ③을 보여 주는 자료를 골랐어요.","다올은 해결 방안을 하나 더 보탰어요.","해결 방안은 몇 개를 보태도 이유를 보여 주지 못해요."],"asset":{"type":"passage","lines":["셋째 장 — 이유 ① 지나친 밤 불빛은 잠을 방해하기 때문입니다.","근거 ① 잠들기 전 밝은 빛을 오래 보면 잠드는 데 걸리는 시간이 길어진다는 연구 결과","넷째 장 — 이유 ② 밤에 켜 두는 불빛이 해마다 늘고 있기 때문입니다.","근거 ② 밤 밝기를 해마다 조사한 그래프 — 밝은 곳이 꾸준히 넓어지고 있다","다섯째 장 — 이유 ③ 밤 불빛이 곤충과 새의 생활을 어지럽히기 때문입니다.","근거 ③ 우리나라에도 지나친 빛을 막기 위한 제도가 마련되어 있습니다.","여섯째 장 — 오늘 밤, 쓰지 않는 불빛 하나를 끄는 것이 첫걸음입니다.","밝기를 줄이는 것이 어둠을 늘리는 일은 아닙니다."],"title":"카드 뉴스 「밤이 너무 밝습니다」 셋째~여섯째 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#20','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C5',3,'sa','auto','「가까운 층은 계단으로」의 세 이유 가운데 많은 사람이 받아들이기 어려운 이유는 몇 번인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"K6-2-u3-C5","difficulty":3,"kind":"sa","stem":"「가까운 층은 계단으로」의 세 이유 가운데 많은 사람이 받아들이기 어려운 이유는 몇 번인가요? 숫자로 쓰세요.","answer":["3","③"],"explanation":["멋있어 보이는 것은 사람마다 달라요.","많은 사람이 고개를 끄덕이기 어려워요.","그래서 이유 ③이 타당하지 않아요."],"asset":{"type":"passage","lines":["주장 — 삼 층까지는 계단으로 다닙시다.","이유 ① 짧은 거리에 승강기를 쓰면, 꼭 필요한 사람이 오래 기다리게 되기 때문입니다.","이유 ② 계단을 오르내리는 것이 몸을 움직일 좋은 기회이기 때문입니다.","이유 ③ 계단으로 다니는 사람이 더 멋있어 보이기 때문입니다.","근거 — 층마다 승강기를 기다린 시간을 잰 표","근거 — 짧은 계단 오르기가 몸에 도움이 된다는 안내 자료"],"title":"카드 뉴스 「가까운 층은 계단으로」"},"mis":"K6-2-u3-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#21','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C3',3,'mc','auto','주장하는 말을 듣는 방법과 하는 일을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u3-X04']::text[],false,'{"seq":21,"concept":"K6-2-u3-C3","difficulty":3,"kind":"mc","stem":"주장하는 말을 듣는 방법과 하는 일을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"메모하며 듣기 — 이유 · 근거 적기 / 요약하며 듣기 — 주장 · 이유 · 근거로 간추리기 / 견주며 듣기 — 내 생각과 견주기","correct":true},{"t":"메모하며 듣기 — 내 생각과 견주기 / 요약하며 듣기 — 이유 적기","mis":"K6-2-u3-X04"},{"t":"견주며 듣기 — 목소리 크기 견주기 / 메모하며 듣기 — 느낌 적기","mis":"K6-2-u3-X04"},{"t":"요약하며 듣기 — 말한 사람의 옷차림 간추리기","mis":"K6-2-u3-X04"}],"explanation":["메모는 적는 것이에요.","요약은 세 자리로 간추리는 것이에요.","견주기는 내 생각과 견주는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#22','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C10',3,'mc','auto','주장하는 말 · 영상 · 카드 뉴스를 평가하는 방법에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X17','K6-2-u3-X03','K6-2-u3-X15']::text[],false,'{"seq":22,"concept":"K6-2-u3-C10","difficulty":3,"kind":"mc","stem":"주장하는 말 · 영상 · 카드 뉴스를 평가하는 방법에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"담는 그릇은 달라도 주장 · 이유 · 근거를 세 기준으로 따지는 방법은 같다","correct":true},{"t":"영상은 강조의 세기로 평가한다","mis":"K6-2-u3-X17"},{"t":"카드 뉴스는 짧아서 평가하지 않는다","mis":"K6-2-u3-X03"},{"t":"주장하는 말만 평가할 수 있다","mis":"K6-2-u3-X15"}],"explanation":["세 자리에서 같은 기준을 썼어요.","영상은 제목·자료·강조로 주장을 찾았어요.","찾은 뒤 따지는 방법은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#23','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C6',4,'mc','auto','「급식을 남기지 맙시다. 남은 음식을 버리는 데 수고와 돈이 들기 때문입니다.」의 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u3-X08','K6-2-u3-X19','K6-2-u3-X18']::text[],false,'{"seq":23,"concept":"K6-2-u3-C6","difficulty":4,"kind":"mc","stem":"「급식을 남기지 맙시다. 남은 음식을 버리는 데 수고와 돈이 들기 때문입니다.」의 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"영양 선생님께 여쭈어 받은, 한 주 동안 우리 학교에서 남은 음식의 양과 처리 방법 기록","correct":true},{"t":"나는 급식이 맛있다는 말","mis":"K6-2-u3-X08"},{"t":"음식물 쓰레기를 줄이려고 다른 학교가 만든 규칙","mis":"K6-2-u3-X19"},{"t":"남은 음식이 해마다 늘고 있다는 말 하나만","mis":"K6-2-u3-X18"}],"explanation":["이유는 버리는 데 수고와 돈이 든다는 것이에요.","그것을 보여 주는 기록이 근거예요.","규칙은 해결 방안, 늘고 있다는 말은 규모예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#24','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C13',4,'essay','teacher','관심 있는 주제를 하나 정해, 그 주제의 영상을 찾을 때 쓸 찾는 말을 쓰고, 찾은 영상을 볼 때와 친구에게 설명할 때 지킬 차례를 각각 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u3-C13","difficulty":4,"kind":"essay","stem":"관심 있는 주제를 하나 정해, 그 주제의 영상을 찾을 때 쓸 찾는 말을 쓰고, 찾은 영상을 볼 때와 친구에게 설명할 때 지킬 차례를 각각 쓰세요.","answer_guide":{"answer":"예: 주제 — 자전거 안전. 찾는 말 — 「자전거 안전모 쓰는 방법 어린이 교육용」. 볼 때의 차례 — 말하지 않고 끝까지 자세히 보기 → 본 것만 말하기 → 무슨 일이 일어나는지 생각하기 → 궁금한 것 묻기. 설명할 때의 차례 — 제목 → 주장 → 이유 → 근거 → 세 기준으로 판단한 결과 → 그렇게 판단한 까닭.","scoring_points":["여러 사람이 함께 생각할 주제와 구체적인 찾는 말을 썼는가","영상을 보는 네 단계를 차례대로 썼는가","설명할 때 넣을 것을 차례대로 썼는가"]},"explanation":["구체적인 말로 찾아요.","본 것과 생각을 섞지 않아요.","판단에는 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u3_review_d#25','kor',6,2,'u3','','g6_2_kor_u3_review_d','unit_review','K6-2-u3-C2',4,'essay','teacher','이 단원에서 배운 말로 「비판적으로 본다는 것」을 설명하고, 생활 속에서 실천할 다짐을 언제 · 어디에서 · 무엇을 할지 넣어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u3-C2","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 말로 「비판적으로 본다는 것」을 설명하고, 생활 속에서 실천할 다짐을 언제 · 어디에서 · 무엇을 할지 넣어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 비판적으로 본다는 것은 무조건 믿거나 무조건 의심하는 것이 아니라, 주장 · 이유 · 근거가 타당한지 제대로 따져 보고 타당한 점을 먼저 세운 뒤 보완할 점을 까닭과 함께 말하는 것이다. 다짐 — 이번 주 토요일 저녁에 집에서 본 광고 영상 하나를 골라 제목 · 자료 · 강조된 표현으로 주장을 찾고 근거가 객관적인지 공책에 적어 보겠다.","scoring_points":["비판적으로 보기와 무조건 의심하기를 갈라 설명했는가","타당한 점을 먼저 세운다는 점을 썼는가","언제·어디에서·무엇을 할지 담은 다짐을 썼는가"]},"explanation":["비판은 의심이 아니에요.","살릴 것을 먼저 세어요.","다짐도 실천 가능해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
